INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal bicicleta', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/BICYCLE_CRUNCH/heroImage_BBtOafu.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_002-A2.mp4', 'forca', 'CRUNCH', 'Iniciante', 'HIPS', 'The bicycle crunch is a dynamic exercise that strengthens the core, lower abdominals, and lower back. The movement also improves stability, balance and coordination.', '["Deite-se de costas com os joelhos flexionados e os pés apoiados no chão. Coloque as mãos atrás da cabeça.","Levante as escápulas e as pernas do chão, flexionando os joelhos a 90 graus. Em seguida, pedale lentamente no ar alternando as pernas como se estivesse andando de bicicleta."]');
