INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LUNGE/heroImage_BBtOcN3.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_029-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Avançado', 'HAMSTRINGS', 'The standard lunge is a foundation bodyweight exercise used to strengthen the muscles of the lower extremities.', '["Fique em pé com os pés afastados na largura dos ombros e com as mãos na cintura. Mantenha um arco natural na parte inferior das costas e o queixo paralelo ao chão.","Dê um grande passo à frente, 30 a 60 cm do seu pé de trás. Assim que o pé tocar o chão, abaixe seus quadris no chão até que o joelho à frente forme um ângulo de 90 graus.","Pressione o pé da frente e volte para a posição ereta. Continue avançando com a mesma perna até completar a quantidade desejada de repetições, depois troque de perna e comece de novo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdução de ombro com faixa elástica', 'LATS', '', NULL, NULL, 'forca,mobilidade', 'BANDED_EXERCISES', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de prancha', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/PLANK/heroImage_BBtOiSn.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_016-A2.mp4', 'forca,yoga,pilates', 'PLANK', 'Iniciante', 'SHOULDERS', 'Essa posição fundamental ensina como manter o corpo estável, como uma prancha resistente. Seu corpo também fica parecido a uma prancha porque você fica em linha reta dos pés à cabeça. Essa postura é considerada uma das melhores fortalecedoras do core.', '["Deite-se no chão com os cotovelos diretamente embaixo dos ombros e com as pernas completamente estendidas. Eleve o tronco para o ar até formar uma linha reta desde os ombros até os tornozelos. Contraia o estômago e os glúteos e mantenha essa posição durante o tempo desejado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão do ombro com faixa elástica a 90 graus', 'SHOULDERS', '', NULL, NULL, 'forca,mobilidade', 'BANDED_EXERCISES', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca', 'BICEPS', '', NULL, NULL, 'forca', 'BANDED_EXERCISES', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral com elevação de perna com faixa elástica', 'OBLIQUES', '', NULL, NULL, 'forca', 'BANDED_EXERCISES', '', 'ABS, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal invertida', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/REVERSE_CRUNCH/heroImage_BBtO7Hs.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_014-B2.mp4', 'forca', 'CRUNCH', 'Iniciante', 'HIPS', 'The reverse crunch is a basic core strengthening exercise that also improves stability throughout the lower back, hips and spine. By starting the movement in your lower body and bringing your knees to your chest, you protect your back and create a greater range of motion, which can help place more tension on your abdominal muscles.', '["Deite-se de costas com os joelhos unidos e as pernas flexionadas a um ângulo de 90 graus, com os pés apoiados no chão. Coloque as palmas para baixo no chão, para ter suporte.","Contraia o abdômen para levantar os quadris do chão enquanto comprime os joelhos contra tórax. Faça uma pausa no topo do movimento, em seguida abaixe-se de volta sem arquear a coluna lombar ou desgrudá-la do chão."]');
