INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT/heroImage_BBtOa8W.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_031-A3.mp4', 'forca,mobilidade', 'SQUAT', 'Iniciante', 'HAMSTRINGS', 'The squat is a lower-body strength exercise that targets the quads, hamstrings and glutes. The exercise also improves posture and increases flexibility and hip mobility.', '["Assuma uma posição mais ereta possível, com os pés alinhados com os ombros e os dedos do pé levemente apontados para fora. Mantenha os braços na sua frente, na altura do tórax, para ajudar a manter o equilíbrio.","Baixe os quadris como se fosse sentar, até que suas coxas fiquem paralelas ao chão. Faça uma pausa, apoie-se no calcanhar e eleve o corpo de volta à posição inicial. Contraia os glúteos no topo do movimento."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Corda naval alternada – Ondulação com deslocamento lateral', 'SHOULDERS', '', NULL, NULL, 'forca', 'BATTLE_ROPE', '', 'ABS, ABDUCTORS, ADDUCTORS, GLUTES, CALVES, LOWER_BACK, HAMSTRINGS', NULL, NULL);
