INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Polichinelos', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/JUMPING_JACKS/heroImage_BBtOf8L.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_008-A3.mp4', 'forca,cardio', 'CARDIO', 'Iniciante', 'FOREARM', 'This dynamic full-body exercise is a popular warm-up that increases body temperature, aerobic capacity, and strength.', '["Fique em pé, com os pés juntos e os braços ao lado do corpo.","Rapidamente, levante os braços acima da cabeça enquanto salta, movendo os pés para os lados. Imediatamente, reverta o movimento saltando de volta para a posição de pé."]');
