INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino com barra', 'CHEST', 'Banco, Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_BENCH_PRESS/heroImage_BBtOag7.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_087-A2.mp4', 'forca', 'BENCH_PRESS', 'Avançado', 'SHOULDERS, TRICEPS', 'The barbell bench press is an upper body pressing drill that builds size and strength in the upper body, specifically in the chest, triceps, and shoulders. Lying flat on a bench allows for improved stability. The exercise allows for the greatest amount of weight to be used, which makes it ideal for building strength, size, and power.', '["Deite-se sobre as costas em um banco. Segure uma barra acima do tórax com uma pegada pronada, com as mãos mais afastadas que a largura dos ombros e com os braços totalmente estendidos.  Essa é a sua posição inicial.","Abaixe a barra em um movimento ininterrupto e controlado. Certifique-se de manter os cotovelos recolhidos perto do corpo para que os antebraços formem um ângulo de 45 graus com o corpo na posição para baixo. Pause, depois levante a barra em uma linha reta de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino com pegada fechada na barra', 'TRICEPS', 'Banco, Barra', 'https://connect.garmin.com/images/exercises/images/CLOSE_GRIP_BARBELL_BENCH_PRESS/heroImage_BBtOfci.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_088-A1.mp4', 'forca', 'BENCH_PRESS', 'Avançado', 'CHEST, SHOULDERS', 'The close-grip barbell bench press is an upper-body pressing drill that emphasizes building strength in the triceps as well as the chest. This exercises also increases upper body pushing strength. By placing your hands closer than shoulder-width apart, you force your triceps to do more of the work, thus making this an effective arm-building exercise. If you experience shoulder pain, a slight incline is preferred or dumbbells are suggested.', '["Segure uma barra com uma pegada supinada, com as mãos afastadas de 15 a 30 cm uma da outra e segure-a acima do esterno com os braços totalmente retos.","Abaixe a barra lentamente até o tórax. Certifique-se de manter os cotovelos recolhidos próximos às laterais do corpo, com a parte superior dos braços formando um ângulo de 45 graus com o corpo. Pause, depois levante a barra em uma linha reta de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de barra no chão', 'CHEST', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_FLOOR_PRESS/heroImage_BBtOafv.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_097-A2.mp4', 'forca', 'BENCH_PRESS', 'Avançado', 'SHOULDERS, TRICEPS', 'The barbell floor press is an upper body exercise for the chest, shoulders and triceps. When performed on the floor, the range of motion of the exercise is limited to reduce the strain placed on the shoulder joint.', '["Deite-se com as costas totalmente apoiadas no chão. Segure uma barra de uma gaiola de agachamento ou peça que um colega posicione uma barra em suas mãos. Segure-a com uma pegada pronada, com as mãos mais afastadas que a largura dos ombros. Levante a barra acima da cabeça, trazendo-a para cima do peito com os braços completamente estendidos.","Estenda os braços para cima, mantendo os cotovelos firmes. Pause. Lentamente baixe a barra até que os cotovelos estejam apoiados no chão. Siga o número indicado de repetições."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino', 'CHEST', '', NULL, NULL, 'forca', 'BENCH_PRESS', '', 'SHOULDERS, TRICEPS', NULL, NULL);
