INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de haltere em banco inclinado', 'CHEST', '', NULL, NULL, 'forca', 'BENCH_PRESS', '', 'SHOULDERS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de haltere no banco', 'CHEST', 'Banco, Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_BENCH_PRESS/heroImage_BBtOcy1.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_161-A2.mp4', 'forca', 'BENCH_PRESS', 'Avançado', 'SHOULDERS, TRICEPS', 'The dumbbell bench press is an upper body exercise that strengthens the chest, shoulders, and triceps while improving muscular balance. Using dumbbells allows for a great range of motion in the chest and can also be easier on the shoulders and prevent pain.', '["Deite-se de costas em um banco e segure um par de halteres diretamente acima do esterno com os braços completamente estendidos. Una as escápulas, projete levemente o tórax para fora e mantenha as palmas das mãos voltadas para frente.","Abaixe lentamente ambos os halteres nas laterais do peito. Pause e depois levante os halteres de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento no solo com halteres', 'CHEST', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_FLOOR_PRESS/heroImage_BBtOa9Z.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_181-A1.mp4', 'forca', 'BENCH_PRESS', 'Iniciante', 'SHOULDERS, TRICEPS', 'The dumbbell floor press is a shoulder-friendly upper body pressing exercise that strengthens the chest, shoulders, and arms. Utilizing the floor removes potential strain placed on the shoulder joint.', '["Segure os halteres com uma pegada pronada e deite-se de costas, com uma postura reta. Flexione os joelhos com os pés firmemente apoiados no chão. Estenda os cotovelos para uma posição de 90 graus e com os tríceps apoiados no chão, enquanto segura os halteres acima do tórax.","Expire e mantenha o tronco firme e encaixado enquanto simultaneamente estende os halteres em direção ao teto. Faça uma pausa e retorne para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de barra em banco inclinado', 'CHEST', '', NULL, NULL, 'forca', 'BENCH_PRESS', '', 'SHOULDERS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de haltere em banco inclinado', 'CHEST', 'Banco, Halteres', 'https://connect.garmin.com/images/exercises/images/INCLINE_DUMBBELL_BENCH_PRESS/heroImage_BBtOa5e.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_164-A3.mp4', 'forca', 'BENCH_PRESS', 'Avançado', 'SHOULDERS, TRICEPS', 'The incline dumbbell bench press is an upper-body strengthening exercise that targets the chest, shoulder, and triceps. The inclined position increases the exercise''s emphasis on the upper chest and shoulders. Using dumbbells allows for a greater range of motion and can help prevent any strength imbalances on either arm.', '["Ajuste um banco regulável para uma inclinação de 30 a 45 graus. Deite de costas no banco e segure um par de halteres diretamente acima dos ombros com os braços completamente estendidos.","Una as escápulas, projete levemente o tórax para fora. Abaixe ambos os halteres para as laterais do tórax. Pause e depois levante os halteres de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino horizontal com Kettlebell', 'CHEST', 'Banco, Kettlebells', 'https://connect.garmin.com/images/exercises/images/KETTLEBELL_CHEST_PRESS/heroImage_BBtOiJK.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_242-A3.mp4', 'forca', 'BENCH_PRESS', 'Intermediário', 'SHOULDERS, TRICEPS', 'The kettlebell chest press is a variation of the traditional bench press. Stabilizing the kettlebell throughout the press builds additional strength in the chest, triceps, and delts.', '["Pegue um par de kettlebells e se deite de costas sobre um banco plano. Com os braços completamente estendidos, segure o kettlebell diretamente acima do seu tórax com as palmas voltadas uma para a outra.","Baixe os kettlebells lentamente nas laterais do tórax e mantenha os cotovelos próximos ao corpo, de modo a criar um ângulo de 45 graus na posição inferior. Faça uma pausa e, em seguida, impulsione os kettlebells de volta à posição inicial."]');
