INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de halteres com pegada neutra em banco inclinado', 'CHEST', '', NULL, NULL, 'forca', 'BENCH_PRESS', '', 'SHOULDERS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino deitado com encaixe parcial', 'CHEST', 'Barra, Banco, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/PARTIAL_LOCKOUT/heroImage_BBtOcFI.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_263-A1.mp4', 'forca', 'BENCH_PRESS', 'Intermediário', 'SHOULDERS, TRICEPS', 'The partial lockout is an isometric exercise that increases strength and endurance in the chest, shoulders, and triceps. The exercise works through a short range of motion near the top portion of the bench press. This allows you to build strength if your sticking point is finishing the lift. The lockout forces you to hold a weight at the top of the motion (the isometric aspect), typically using a weight that is heavier than what you could use for a full range of motion repetition. This exercise helps exercisers adapt to using heavier weights and resistance.', '["Deite-se de costas sobre um banco embaixo de um aparelho de smith. Segure uma barra com carga com uma pegada pronada, dez a quinze centímetros acima do seu tórax.","Levante a barra para cima, estendendo completamente os braços. Faça uma pausa e, em seguida, abaixe lentamente a barra para a posição inicial, encaixando-a de volta no aparelho."]');
