INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Panturrilha em pé com barra', 'CALVES', 'Barra', 'https://connect.garmin.com/images/exercises/images/STANDING_BARBELL_CALF_RAISE/heroImage_BBtOff4.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_309-A4.mp4', 'forca', 'CALF_RAISE', 'Iniciante', '', 'A elevação da panturrilha em pé com barra desenvolve massa e força na parte inferior da perna. O uso de uma barra com pesos cria maior resistência, resultando no desenvolvimento direcionado dos músculos da panturrilha.', '["Fique em pé com os pés afastados na largura dos ombros. Coloque uma barra na parte superior das costas, puxando-a para baixo com uma pegada dorsal enquanto aperta as omoplatas para obter estabilidade.","Pressione as pontas dos pés, levantando os calcanhares do chão. Faça uma pausa, abaixe os calcanhares de volta à posição inicial."]');
