INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal engatinhado', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/CARDIO_CORE_CRAWL/heroImage_BBtOiUv.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_011-B1.mp4', 'cardio', 'CARDIO', 'Iniciante', 'GLUTES, LOWER_BACK, TRAPS, QUADS, SHOULDERS', 'The cardio core crawl is a dynamic, multi-joint exercise that targets the core, hips, and glutes. The exercise also strengthens the lower back and shoulders.', '["Inicie o movimento apoiando-se sobre suas mãos e joelhos. Mantenha o tronco firme e as costas levemente arqueadas. Eleve os joelhos a dois ou três centímetros do chão de forma a apoiar seu peso sobre seus pés e mãos.","Mova uma mão para frente e flexione simultaneamente o joelho oposto trazendo-o até a altura do tórax. Retorne a mão e o pé para a posição inicial. Em seguida, mova a outra mão para a frente enquanto traz o outro  joelho até a altura do tórax. Retorne à posição inicial."]');
