INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com polichinelos', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT_JACKS/heroImage_BBtOfbq.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_033-A3.mp4', 'cardio', 'CARDIO', 'Intermediário', 'ABDUCTORS', 'Squat jacks are a lower-body power and strength exercise that target the quads, glutes, and hamstrings. The exercise also improves hip mobility and cardiovascular endurance.', '["Em pé, com os pés juntos e as mãos entrelaçadas atrás da cabeça, empurre o quadril para trás para ficar em um agachamento parcial.","Dê um pulo posicionando os pés para fora e para os lados, mantendo a posição de agachamento. Pule rapidamente, levando os  pés de volta à posição inicial"]');
