INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pular corda', 'CALVES', 'Pular corda', 'https://connect.garmin.com/images/exercises/images/JUMP_ROPE/heroImage_BBtOcKW.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_160-A3.mp4', 'cardio', 'CARDIO', 'Intermediário', 'HAMSTRINGS, GLUTES', 'Jumping rope is a full body conditioning drill that develops foot work, speed and agility. This exercise also improves cardiovascular endurance and coordination.', '["Segure as alças e deixe a corda suspensa atrás de você. Segure as alças nas laterais do corpo.","Balance a corda para cima e sobre a cabeça. Conforme a corda se aproxima de seus pés, dê um pulo de forma a permitir que ela passe por baixo de seus pés."]');
