INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Lenhador com medicine ball', 'OBLIQUES', 'Bola medicinal', 'https://connect.garmin.com/images/exercises/images/MEDICINE_BALL_WOOD_CHOPS/heroImage_BBtO7Id.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_303-A4.mp4', 'forca', 'CHOP', 'Intermediário', 'ABS, SHOULDERS', 'O exercício woodchop com bola medicinal aumenta a potência e a força rotacionais em todo o core, com ênfase nos oblíquos. Este exercício também melhora a mobilidade e a estabilidade do quadril e dos ombros.', '["Fique em pé e segure uma bola medicinal com as duas mãos na altura do peito. Agache-se, mantendo o peito para cima, e traga a bola para a parte externa de um joelho.","Fique de pé e gire o tronco o máximo possível, trazendo a bola para cima e acima do ombro oposto. Retorne à posição inicial."]');
