INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento abdominal com barra', 'ABS', 'Barra, Tapete', 'https://connect.garmin.com/images/exercises/images/BARBELL_ROLLOUT/heroImage_BBtOl6T.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_103-A1.mp4', 'forca', 'CORE', 'Avançado', 'LOWER_BACK, TRAPS, OBLIQUES, SHOULDERS', 'Barbell rollouts are a core strengthening exercise for the entire abdominal region. This exercise also improves strength and stability in the shoulders.', '["Posicione-se de joelhos sobre um colchonete para exercícios.  Coloque uma barra no chão e a segure com uma pegada pronada, com as mãos alinhadas com os ombros. Seus ombros devem estar diretamente sobre a barra. Esta é a sua posição inicial","Mantenha os joelhos em posição fixa, role a barra para fora à sua frente até que os braços estejam completamente estendidos diante do corpo. Faça uma pausa e reverta a direção retornando à posição inicial."]');
