INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal na roda de joelhos', 'ABS', 'Roda abdominal', 'https://connect.garmin.com/images/exercises/images/KNEELING_AB_WHEEL/heroImage_BBtO7D8.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_248-B1.mp4', 'forca', 'CORE', 'Intermediário', 'LOWER_BACK, TRAPS, OBLIQUES, SHOULDERS', 'The kneeling ab wheel increases strength and stability throughout the core and lower back. This exercise also improves strength in the shoulders and triceps.', '["Ajoelhe-se no chão e segure os cabos de uma roda para exercício abdominal com uma pegada pronada.","Com os braços estendidos, deslize a roda para frente. Seus joelhos deverão permanecer fixos e seu tronco irá avançar com os braços. Faça uma pausa e eleve o corpo de volta para a posição inicial."]');
