INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Russian Twist', 'OBLIQUES', 'Anilhas', 'https://connect.garmin.com/images/exercises/images/RUSSIAN_TWIST/heroImage_BBtO7HH.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_265-A1.mp4', 'forca', 'CORE', 'Intermediário', 'ABS, HIPS', 'The Russian twist increases rotational strength in the core and abdominals. The exercise also strengthens the lower back and hips.', '["Sente-se no chão com os joelhos e quadris flexionados a 90 graus e com os pés apoiados firmemente no chão. Segure uma anilha com os braços completamente estendidos na frente do tórax.","Incline-se para trás de forma que seu tronco esteja a um ângulo de 45 graus e use seu abdômen para girar o torso o máximo que puder em uma direção. Reverta o movimento e retorne à posição inicial, preparando-se para girar para a direção oposta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal oblíquo com levantamento de perna', 'OBLIQUES', '', NULL, NULL, 'forca', 'CORE', '', 'ABS, HIPS', NULL, NULL);
