INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Exercício abdominal inferior com bola suíça', 'ABS', 'Bola suíça', 'https://connect.garmin.com/images/exercises/images/SWISS_BALL_JACKKNIFE/heroImage_BBtO54l.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_288-A1.mp4', 'forca', 'CORE', 'Intermediário', 'HIPS', 'The Swiss ball jackknife is a core stabilizing exercise that improves balance, strength, and flexibility throughout the hip and abdominal region.', '["Coloque-se na posição de flexão, mantenha as mãos no chão, alinhadas com os ombros, e as canelas apoiadas sobre a bola suíça. Mantenha o tronco firme e encaixado. Deixe o corpo em linha reta desde os ombros até os pés.","Role a bola para dentro flexionando as pernas e puxando a bola com os pés até que as coxas encostem em seu estômago. Role a bola de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento com a bola suíça', 'ABS', '', NULL, NULL, 'forca', 'CORE', '', 'HIPS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal na barra – Pés aos cotovelos', 'ABS', '', NULL, NULL, 'forca,mobilidade', 'CORE', '', 'HIPS, FOREARM, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento com bola suíça', 'ABS', 'Bola suíça, Tapete', 'https://connect.garmin.com/images/exercises/images/SWISS_BALL_ROLLOUT/heroImage_BBtOcEr.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_290-B1.mp4', 'forca', 'CORE', 'Iniciante', 'TRAPS, SHOULDERS', 'The Swiss ball rollout increases strength and stability throughout the core. This exercise also improves strength and mobility in the shoulders and triceps.', '["Ajoelhe-se sobre um tapete com os cotovelos posicionados sobre uma bola de estabilidade. Role a bola para a frente com os cotovelos, o máximo que conseguir, sem relaxar suas costas.","Mantendo o tronco encaixado, role a bola de volta à posição inicial."]');
