INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal reto no cabo', 'ABS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/CABLE_CRUNCH/heroImage_BBtOacU.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_131-A1.mp4', 'forca', 'CRUNCH', 'Intermediário', '', 'The cable crunch is a core strengthening exercise that targets the entire abdominal region. The exercise also improves stability in the lower back and hips.', '["Prenda um puxador corda ao aparelho de cabo de polia alta. Ajoelhe-se diretamente embaixo do puxador, incline-se levemente para frente, pegue as duas extremidades e segure-as dos lados do rosto.","Mantenha o tronco firme e encaixado e se incline para frente enquanto leva seus cotovelos até as coxas. Faça uma pausa e volte lentamente para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal circular com os braços', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal invertido com perna cruzada', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', 'HIPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal grupado com braços cruzados', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal grupado', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/CRUNCH/heroImage_BBtOpYM.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_006-A2.mp4', 'forca', 'CRUNCH', 'Iniciante', '', 'The crunch is a basic body-weight exercise that strengthens the core and hips. The crunch is effective at working the abs because it causes flexion and places stress on the rectus abdominis - also known as the six pack muscles. Correct form will allow you to maintain tension on your abs as you crunch and lower your torso.', '["Deite-se de costas e coloque as mãos atrás da cabeça. Flexione os joelhos e apoie os pés firmemente no chão.  Esta é a sua posição inicial","Com os cotovelos abertos, contraia o abdômen, eleve os ombros e a parte superior das costas do chão. Mantenha-se nessa posição por um momento e retorne para baixo para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com elevação', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', 'HIPS', NULL, NULL);
