INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal oblíquo com flexão de joelho suspenso', 'OBLIQUES', 'Barra fixa para flexão', 'https://connect.garmin.com/images/exercises/images/HANGING_KNEE_RAISE_OBLIQUE_CRUNCH/heroImage_BBtOldc.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_148-A4.mp4', 'forca', 'CRUNCH', 'Avançado', 'ABS, FOREARM, HIPS, SHOULDERS, TRAPS', 'The hanging knee raise oblique crunch is a variation of the traditional hanging knee raise that strengthens the entire core including the lower abdominals, hip flexors and lower back. This exercise specifically targets the obliques while also improving stability in the upper back and shoulders.', '["Segure-se em uma barra fixa com uma pegada pronada e com as mãos alinhadas com os ombros, certificando-se de que seus braços estejam completamente retos e seus pés não estejam tocando o chão.","Mantenha o tronco firme e encaixado e use o abdômen para elevar os joelhos em direção aos ombros arredondando ou girando o tronco para o lado e contraindo os músculos oblíquos.  Retorne à posição inicial. Repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Cruzamento de quadris', 'OBLIQUES', '', NULL, NULL, 'forca', 'CRUNCH', '', 'HIPS, LOWER_BACK', NULL, NULL);
