INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal cruzado semiajoelhado', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de tronco com cabo em posição ajoelhada', 'ABS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/KNEELING_CABLE_CRUNCH/heroImage_BBtO4Uo.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_131-A1.mp4', 'forca', 'CRUNCH', 'Intermediário', '', 'The kneeling cable crunch increases strength and stability throughout the core. This exercise also improves strength throughout the hips and lower back.', '["Ajoelhe-se em frente a um aparelho de cabo ajustável, mantendo as pernas alinhadas com os ombros. Segure a corda com as palmas voltadas uma para a outra e puxe-a para os lados de sua cabeça.","Mantenha seu abdômen firme e flexione seu tronco para a frente, movendo sua cabeça em direção ao chão. Faça uma pausa por um segundo e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão oblíqua de tronco em posição ajoelhada', 'OBLIQUES', '', NULL, NULL, 'forca', 'CRUNCH', '', 'ABS', NULL, NULL);
