INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal invertido no banco', 'ABS', 'Banco', 'https://connect.garmin.com/images/exercises/images/REVERSE_CRUNCH_ON_A_BENCH/heroImage_BBtOiVb.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_085-A1.mp4', 'forca', 'CRUNCH', 'Iniciante', '', 'The reverse crunch on a bench is a simple and effective way to strengthen your core and hip flexor region. This exercise also increases strength in the lower lumbar area.', '["Sente-se na extremidade de um banco e coloque as mãos ao lado dos quadris. Endireite sua coluna levantando o peito e puxando os ombros para trás.","Flexione os joelhos a um ângulo de 90 graus e eleve os pés tirando-os do chão. Contraia o abdômen. Incline-se levemente para trás. Leve os joelhos para perto do tórax. Retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal invertido com elevação de quadril', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com rotação', 'ABS', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominais infra alternados com peso', 'ABS', 'Peso da mochila, Tapete', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_369-Cam1.mp4', 'forca', 'CRUNCH', 'Intermediário', 'LOWER_BACK', 'O abdominal infra alternado é um exercício intermediário de core usado para ativar e fortalecer os músculos da região abdominal.', '["Deite-se de costas no chão com as pernas estendidas e segure a mochila sobre o peito com os braços estendidos.","Levante ligeiramente as pernas do chão em um ângulo de 45 graus e comece a alternar pequenos movimentos controlados de chute para cima e para baixo, mantendo as omoplatas ligeiramente afastadas do chão.","Mantenha o core contraído e os movimentos estáveis durante todo o exercício.","Continue pela duração ou repetições desejadas."]');
