INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal cruzado skatista', 'OBLIQUES', '', 'https://connect.garmin.com/images/exercises/images/SKATER_CRUNCH_CROSS/heroImage_BBtOcHh.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_039-A3.mp4', 'forca', 'CRUNCH', 'Avançado', 'CALVES, HAMSTRINGS', 'This exercise is a dynamic multi-joint body-weight exercise that synergistically combines strength training and cardiovascular conditioning. This high-energy move encompasses plyometric and bilateral training.', '["Posicione-se em pé com os pés juntos. Dê um passo para trás na diagonal com sua perna direita cruzando atrás de sua perna esquerda, agachando-se ligeiramente e flexionando os braços na frente do peito. Gire o tronco para a esquerda.","Pule lateralmente com a perna esquerda, estendendo os braços para frente do tórax enquanto pula.","Aterrisse com a perna direita cruzando a esquerda atrás e na diagonal, flexionando ambos os joelhos e girando o tronco para a direita."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal lateral em pé', 'OBLIQUES', '', NULL, NULL, 'forca', 'CRUNCH', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com perna estendida com bola', 'ABS', 'Bola de Pilates', 'https://connect.garmin.com/images/exercises/images/STRAIGHT_LEG_CRUNCH_WITH_BALL/heroImage_BBtOnoN.jpg', NULL, 'forca', 'CRUNCH', 'Iniciante', '', 'O uso de uma bola fornece um estímulo que ajuda a ativar o feedback proprioceptivo do corpo.', '["Sente-se com os joelhos dobrados e os pés apoiados.","Coloque uma bola de Pilates de tamanho médio sob seu tórax e role sobre ela até que sua cabeça esteja no chão. Entrelace os dedos atrás da cabeça e estique as pernas, abrindo-as na largura do quadril.","Expire enquanto levanta a cabeça e os ombros do tapete.","Inspire e abaixe as costas até a metade da bola.","Expire e role para frente. Repita 10 vezes","Dobre os joelhos e role todo o caminho até se sentar."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal grupado sobre a bola suíça', 'ABS', 'Bola suíça', 'https://connect.garmin.com/images/exercises/images/SWISS_BALL_CRUNCH/heroImage_BBtOcOI.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_285-A1.mp4', 'forca', 'CRUNCH', 'Intermediário', '', 'The Swiss ball crunch increases muscular strength and endurance throughout the core region including the lower abdominals, lower back, and hip flexors. Performing the exercise on the Swiss ball will also increase balance and stability. Adding the Swiss ball has two main benefits. First it improves the range of motion on extension (the lower of the crunch), which builds abdominal strength. It also positions the body in a way that tends to place less stress on the upper and lower back.', '["Deite-se de costas sobre uma bola suíça com os joelhos flexionados em um ângulo de 90 graus e com os pés apoiados no chão e alinhados com os ombros. Entrelace os dedos atrás da cabeça. A bola deve estar sob seus quadris e sob a parte inferior das costas. Esta é a sua posição inicial","Flexione o tronco em direção ao joelhos, elevando o tórax. Pare quando o meio das costas não estiver mais tocando a bola. Faça uma pausa e retorne à posição inicial."]');
