INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca bíceps com barra', 'BICEPS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_BICEPS_CURL/heroImage_BBtOf31.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_093-A3.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'The barbell biceps curl develops size and strength of the biceps while helping improve grip strength.', '["Segure  a barra com uma pegada supinada, braços totalmente estendidos e as palmas voltadas para a frente.","Sem mover a parte superior dos braços, flexione os cotovelos e aproxime a barra dos ombros, o máximo que puder. Faça uma pausa e, em seguida, abaixe a barra para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca bíceps alternada com halteres', 'BICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_BICEPS_CURL/heroImage_BBtOkZz.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_176-A3.mp4', 'forca', 'CURL', 'Intermediário', '', 'The alternating dumbbell biceps curls develop size and strength of the biceps and forearms. The alternating of each arm eliminates any muscular imbalances on each side.', '["Segure um haltere em cada mão com uma pegada pronada e os braços completamente estendidos com as palmas voltadas para as laterais do corpo. Os pés deverão estar alinhados com os ombros e os halteres apoiados no nível das coxas.","Execute a rosca trazendo um haltere em direção ao mesmo ombro, mantendo o braço oposto estendido. Ao trazer o peso, gire ligeiramente o pulso para que a palma fique de frente para você. Pause e depois retorne à posição inicial.  Alterne os lados na próxima repetição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca do bíceps com haltere alternado sobre a Bola Suíça', 'BICEPS', '', NULL, NULL, 'forca', 'CURL', '', 'FOREARM', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca do bíceps alternada com halteres em posição inclinada', 'BICEPS', 'Banco, Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_INCLINE_DUMBBELL_BICEPS_CURL/heroImage_BBtOl00.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_165-A2.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'The incline dumbbell biceps curl develops size and strength in the biceps and forearms. The incline angle emphasizes the resistance on the lower portion of the biceps.', '["Pegue um par de halteres e sente-se em um banco inclinado em 45 graus. Mova as escápulas para trás e estenda totalmente os braços para baixo, permitindo que os halteres fiquem suspensos nas laterais do corpo com as palmas voltadas para fora.","Flexionando o cotovelo, eleve um haltere em direção ao ombro.  Faça uma pausa e então abaixe o corpo de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de pulso invertida com barra', 'FOREARM', '', NULL, NULL, 'forca', 'CURL', '', '', NULL, NULL);
