INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca scott vertical', 'BICEPS', 'Puxador, Banco', 'https://connect.garmin.com/images/exercises/images/DEAD_HANG_BICEPS_CURL/heroImage_BBtOcES.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_098-A1.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'The dead-hang biceps curl is an isolation exercise for the biceps and forearms. The forward hanging position maximizes the isolation of the biceps by removing assistance from the back and shoulders.', '["Posicione-se em frente a um banco para rosca scott com as pernas afastadas e alinhadas com os ombros. Leve o tórax para baixo até o topo do aparelho, permitindo que os braços fiquem pendentes, perpendiculares ao chão ou paralelos à parte de 90 graus do banco. Segure uma barra EZ com uma pegada estreita.","Curve e eleve a barra até a altura do rosto. Faça uma pausa, em seguida, retorne-a lentamente para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca do bíceps com barra EZ e pegada fechada', 'BICEPS', '', NULL, NULL, 'forca', 'CURL', '', 'FOREARM', NULL, NULL);
