INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca martelo com halteres', 'BICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_HAMMER_CURL/heroImage_BBtOad7.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_183-A3.mp4', 'forca', 'CURL', 'Iniciante', 'FOREARM', 'The dumbbell hammer curl increases strength and size in the biceps and forearms. The neutral-grip of the movement places more emphasis on the forearms.', '["Segure os halteres com uma pegada neutra, com as palmas das mãos voltadas uma para a outra. Mantenha o corpo ereto e os pés alinhados com os ombros.","Mantendo o tronco firme, eleve os halteres até a altura do ombro, mantendo as palmas das mãos voltadas uma para a outra. Faça uma pausa no topo do movimento, contraia o bíceps e, em seguida, abaixe o peso até a posição inicial."]');
