INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca bíceps em posição inclinada para frente', 'BICEPS', 'Barra', 'https://connect.garmin.com/images/exercises/images/FORWARD_BEND_BICEPS_CURL/heroImage_BBtOa4P.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_107-A1.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'This exercise develops strength in the forearms and bicep muscles. The forward bend improves shoulder stabilization.', '["Segure a barra com uma pegada invertida e as mãos alinhadas à largura dos ombros. Flexione ligeiramente os quadris  até que a parte superior de seu corpo fique praticamente paralela ao chão.","Contraia os bíceps, mantendo os cotovelos imóveis. Levante a barra até a altura dos ombros enquanto mantém uma tensão constante no bíceps. Lentamente leve o peso à posição inicial."]');
