INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca concentrada de um braço', 'BICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ONE_ARM_CONCENTRATION_CURL/heroImage_BBtO7zq.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_194-A1.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'This curl develops arm size and strength by isolating the bicep. The arm positioning forces the muscle to contract without the assistance of other muscle groups.', '["Segure um haltere com uma mão. Sente-se na beira de um banco e coloque os pés mais afastados que a largura dos ombros. Posicione a parte de trás do braço que está segurando o haltere na parte interna da coxa e apoie a mão oposta sobre o joelho oposto.","Lentamente curve o haltere para cima, o máximo possível. Faça uma pausa no topo e abaixe-o lentamente até a posição inicial."]');
