INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca do bíceps alternada sentada com pesos', 'BICEPS', 'Halteres, Banco', 'https://connect.garmin.com/images/exercises/images/SEATED_ALTERNATING_DUMBBELL_BICEPS_CURL/heroImage_BBtO7sc.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_169-A1.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'The seated alternating dumbbell biceps curls increases the strength and size of the biceps and forearms. Performing the movement from the seated position isolates the biceps.', '["Sentando em um banco, segure um par de halteres nas laterais do corpo, com os braços completamente estendidos e as palmas das mãos voltadas para frente.","Flexionando o cotovelo, traga um haltere em direção aos ombros.  Faça uma pausa e, em seguida, abaixe o braço para a posição inicial. Alterne o braço."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca invertida com halteres na posição sentada', 'BICEPS', '', NULL, NULL, 'forca', 'CURL', '', 'FOREARM', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca com halteres com postura alternada compensada', 'BICEPS', '', NULL, NULL, 'forca', 'CURL', '', 'FOREARM', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca bíceps com halteres em pé', 'BICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/STANDING_DUMBBELL_BICEPS_CURL/heroImage_BBtOcxL.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_202-A3.mp4', 'forca', 'CURL', 'Intermediário', 'FOREARM', 'The standing dumbbell biceps curl is a traditional bodybuilding move that develops density and strength throughout the biceps region. This exercise should always be performed with a controlled motion.', '["Segure um par de halteres e posicione-se em pé com o tronco firme e reto. Fique com os braços esticados, nas laterais do seu corpo, com  as palmas das mãos voltadas para frente.","Sem mover a parte superior dos braços, flexione os cotovelos e aproxime os halteres de seus ombros o máximo que puder. Faça uma pausa por um segundo e, lentamente, permita que os pesos retornem à posição inicial, com os braços completamente estendidos."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca alternada com halteres em pé', 'BICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/STANDING_ALTERNATING_DUMBBELL_CURLS/heroImage_BBtO50p.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_201-A3.mp4', 'forca', 'CURL', 'Iniciante', 'FOREARM', 'The standing alternating dumbbell curl is a strength building exercise for the biceps and forearms. Performing the curls in an alternating manner ensures muscular balance on both sides of the body.', '["Fique em pé, mantenha os pés ligeiramente afastados e segure um haltere em cada mão com uma pegada pronada e com as palmas voltadas para os lados. Esta é a sua posição inicial","Levante um haltere em direção ao ombro enquanto gira simultaneamente a parte de trás da mão. Pause com a palma da mão virada para seu ombro. Inverta o movimento, levando o peso de volta à posição inicial."]');
