INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com barra', 'HAMSTRINGS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_DEADLIFT/heroImage_BBtO4Va.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_096-A3.mp4', 'forca', 'DEADLIFT', 'Avançado', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', 'The barbell deadlift builds total-body strength by targeting the lower back, hamstrings, quads, and glutes. The exercise also increases core strength and stability.', '["De pé e em posição ereta, segure uma barra com uma pegada  pronada, com as mãos separadas por cerca de duas vezes a largura do ombro.","Sem deixar a região lombar se encurvar, abaixe lentamente a barra em direção ao solo. Faça uma pausa, levante-se e empurre seu quadril para a frente, enquanto contrai os glúteos. Retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra romeno', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'ADDUCTORS, FOREARM, LATS, LOWER_BACK, TRAPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com barra', 'HAMSTRINGS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_STRAIGHT_LEG_DEADLIFT/heroImage_BBtOiNv.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_106-A3.mp4', 'forca', 'DEADLIFT', 'Intermediário', 'TRAPS, LATS, GLUTES, ADDUCTORS', 'The barbell straight-leg deadlift builds strength in the core, hamstrings, glutes, and lower back. Correctly performing this exercise depends on mastering the hip hinge, which requires you to push your hips back and feel a stretch in your hamstrings to start the movement. Proper form includes not rounding your upper or lower back and keeping the barbell as close as possible to your body.', '["Fique em pé, mantenha os pés afastados e alinhados com os ombros.  Flexione levemente os joelhos e segure uma barra com as duas mãos com uma pegada pronada. Posicione as mãos um pouco mais afastadas que a largura dos ombros.","Mantenha o tórax e as costas retas e empurre os quadris para trás, enquanto abaixa a barra logo abaixo dos joelhos. Faça uma pausa e, em seguida, reverta o movimento para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com haltere', 'HAMSTRINGS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_DEADLIFT/heroImage_BBtOiJg.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_180-A3.mp4', 'forca', 'DEADLIFT', 'Intermediário', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', 'The dumbbell deadlift is a dynamic multi-joint exercise that builds strength in the lower body as well as the back, shoulders, and core, making it a great total-body exercise. By using dumbbell you''re able to achieve a greater range of motion. Starting with dumbbells can also be helpful when you''re learning the dumbbell movement as they allow for lower total weight to be used.', '["Segure um par de halteres na frente do corpo com uma pegada pronada, com as palmas voltadas para o corpo.","Incline-se para frente na altura dos quadris, flexionando ligeiramente os joelhos e abaixando os halteres até o chão, sem curvar as costas.  Mantenha o tórax firme e eleve-se de volta até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com uma perna com haltere para remada', 'LATS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'BICEPS, SHOULDERS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com haltere com pernas estendidas', 'HAMSTRINGS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_STRAIGHT_LEG_DEADLIFT/heroImage_BBtOa9u.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_203-A3.mp4', 'forca', 'DEADLIFT', 'Intermediário', 'TRAPS, LATS, GLUTES, ADDUCTORS', 'The dumbbell straight-leg deadlift strengthens the lower back, with an emphasis on the hamstrings and glutes. Performing the exercise with dumbbells will improve balance and stability on each side of the body while strengthening the core.', '["Segure um par de halteres com uma pegada pronada e mantenha-os no comprimento dos braços, em frente às coxas. Fique em pé com os pés alinhados com os ombros e os joelhos levemente flexionados. Mantenha o tronco firme e encaixado durante todo o exercício.","Sem mudar a curvatura dos joelhos, curve os quadris até que o tronco fique quase paralelo ao chão. Faça uma pausa e, em seguida, mova seus quadris para a frente, contraindo os glúteos firmemente para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento com kettlebell', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'LATS, TRAPS, FOREARM, QUADS, GLUTES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Movimentação vertical do Kettlebell', 'GLUTES', '', NULL, NULL, 'forca', 'DEADLIFT', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento sumô com kettlebell', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'LATS, TRAPS, FOREARM, QUADS, GLUTES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com um único braço e uma única perna', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'TRAPS, LATS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento no smith', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento com peso', 'HAMSTRINGS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_368-Cam1.mp4', 'forca', 'DEADLIFT', 'Intermediário', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', 'The barbell deadlift builds total-body strength by targeting the lower back, hamstrings, quads, and glutes. The exercise also increases core strength and stability.', '["Fique de pé com os pés afastados na largura dos ombros e coloque a mochila deitada no chão, na frente dos seus pés. Abaixe-se e segure a parte superior e inferior da mochila com as palmas das mãos voltadas para dentro.","Sem arredondar a região lombar, levante lentamente a mochila do chão. Faça uma pausa e, em seguida, levante-se e empurre o quadril para a frente, enquanto contrai os glúteos. Retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra rotacional com haltere', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'TRAPS, LATS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com um único braço', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com barra com uma perna', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com perna reta com barra e uma única perna', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'TRAPS, LATS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra unilateral com barra', 'HAMSTRINGS', 'Barra', 'https://connect.garmin.com/images/exercises/images/SINGLE_LEG_DEADLIFT_WITH_BARBELL/heroImage_BBtO54q.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_108-A3.mp4', 'forca', 'DEADLIFT', 'Intermediário', 'LATS, TRAPS, FOREARM, QUADS, GLUTES, ADDUCTORS', 'The single-leg deadlift with barbell builds leg and back strength while improving core stability, balance, and coordination.', '["Posicione-se em pé com os pés aproximadamente alinhados com os ombros. Segure uma barra com os braços totalmente estendidos em direção ao chão, com as mãos afastadas na largura dos ombros e as palmas voltadas para as coxas. Enquanto levanta um pé a poucos centímetros do chão e o leva para trás, flexione ligeiramente o joelho da perna de apoio.","Empurre os quadris para trás e flexione-se na altura da cintura para abaixar o tronco em direção ao chão, enquanto a perna de trás acompanha o movimento para ajudar no equilíbrio.   Empurre seu tórax para fora, abaixando o máximo que puder sem curvar a coluna lombar. Deixe os pesos tocarem o chão, faça uma pausa e depois contraia os glúteos, retornando à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Circuito de levantamento terra romeno unilateral', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'TRAPS, LATS, GLUTES, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Circuito de levantamento terra romeno com uma perna', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'DEADLIFT', '', 'TRAPS, LATS, GLUTES, ADDUCTORS', NULL, NULL);
