INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Crucifixo com halteres', 'CHEST', 'Halteres, Banco', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_FLYE/heroImage_BBtOiLi.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_162-A1.mp4', 'forca', 'FLYE', 'Iniciante', 'SHOULDERS', 'The dumbbell flye is an isolation exercise that strengthens the chest. The flye uses a different range of motion, which reduces the assistance of other muscles such as your shoulders and triceps. The movement can be used either before the bench press (to pre-exhaust your chest) or after the bench press to add more volume while using a lighter weight.', '["Segure um par de halteres com uma pegada pronada e  deite-se de costas sobre um banco plano. Estenda os braços para fora, distanciando-os do corpo, de forma que estejam paralelos ao chão e os halteres estejam na altura do tórax.","De forma controlada, eleve os braços de modo que as palmas fiquem voltadas uma para a outra e que os halteres fiquem exatamente acima do tórax. Faça uma pausa e contraia os músculos do tórax no topo do movimento. Abaixe os halteres devagar para os lados e para longe do corpo formando um arco com os braços. Quando os halteres estiverem praticamente alinhados com o peito, inverta o movimento e retorne à posição inicial."]');
