INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de quadril com barra no chão', 'GLUTES', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_HIP_THRUST_ON_FLOOR/heroImage_BBtOiD4.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_101-A2.mp4', 'forca', 'HIP_RAISE', 'Intermediário', 'HAMSTRINGS, HIPS', 'The barbell hip thrust builds strength and power in the glutes and lower body. This exercise also improves core strength and stability.', '["Deite-se de costas no chão com os joelhos flexionados, pés firmemente apoiados no chão e com uma barra posicionada sobre os quadris. Segure a barra com uma pegada pronada e com as mãos alinhadas com os ombros, posicionando-a de forma segura.","Contraia o tronco e pressione os calcanhares no chão, elevando seus quadris. Faça uma pausa no topo do movimento. Certifique-se de contrair os glúteos. Em seguida, retorne à posição inicial de forma controlada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de quadril no banco com barra', 'GLUTES', 'Barra, Banco', 'https://connect.garmin.com/images/exercises/images/BARBELL_HIP_THRUST_WITH_BENCH/heroImage_BBtSAkg.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_311-A5.mp4', 'forca', 'HIP_RAISE', 'Avançado', 'HAMSTRINGS, HIPS', 'A elevação do quadril com barra aumenta a força e a potência nos isquiotibiais e glúteos. O exercício também melhora a estabilidade em todo o core e parte inferior das costas.', '["Deite-se com a parte superior das costas apoiada em um banco e os pés apoiados no chão à sua frente. Segure uma barra em seus quadris.","Abaixe os quadris para que seus glúteos quase encostem no chão.","Pressionando os calcanhares e contraindo os glúteos, retorne a barra à posição inicial."]');
