INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de quadril', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/HIP_RAISE/heroImage_BBtOhct.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_007-A2.mp4', 'forca,mobilidade', 'HIP_RAISE', 'Iniciante', 'HAMSTRINGS, HIPS', 'The hip raise builds strength and stability in the hips. The movement also increases strength in the core, glutes, and hamstrings. This movement is one of the best at building glutes strength, and has multiple variations - including single leg options - that make it one of the most versatile exercises that doesn''t require any equipment.', '["Deite-se de costas no chão com os braços estendidos nas laterais do corpo, com os joelhos flexionados e os pés firmemente apoiados no chão.","Levante os quadris do chão, de modo que o corpo forme uma linha reta desde os ombros até os joelhos. Faça uma pausa no topo,  em seguida abaixe o corpo de volta à posição inicial."]');
