INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Balanço Com Kettlebell', 'GLUTES', 'Kettlebells', 'https://connect.garmin.com/images/exercises/images/KETTLEBELL_SWING/heroImage_BBtOa9h.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_244-A3.mp4', 'forca', 'HIP_RAISE', 'Intermediário', 'QUADS, LATS, ABS, HAMSTRINGS, SHOULDERS', 'O balanço do kettlebell cria força e explosão nos quadris e na parte inferior do corpo. Este exercício também aumenta a força na parte inferior das costas, core e ombros.', '["Segure um único kettlebell em ambas as mãos com uma pegada dorsal e os pés afastados na largura dos ombros. Dobre os joelhos levemente enquanto empurra os quadris para trás, mantendo o peito levantado e dobrando o tronco até que fique paralelo ao chão. Deixe o kettlebell cair entre as pernas com os braços totalmente estendidos.","Empurre os quadris para a frente com explosão, enquanto pressiona os glúteos. Deixe o impulso deste movimento impulsionar o kettlebell até a altura do ombro sem depender dos músculos do braço para fazer o trabalho. Permita que o kettlebell volte para baixo e repita o movimento."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de quadril unilateral', 'GLUTES', '', NULL, NULL, 'forca', 'HIP_RAISE', '', 'HAMSTRINGS, QUADS, HIPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de quadril unilateral com os pés na bola suíça', 'GLUTES', '', NULL, NULL, 'forca', 'HIP_RAISE', '', 'HAMSTRINGS, QUADS, HIPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de quadril com uma perna só', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/SINGLE_LEG_HIP_RAISE/heroImage_BBtOhcl.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_036-A1.mp4', 'forca,mobilidade', 'HIP_RAISE', 'Iniciante', 'HAMSTRINGS, HIPS', 'The single-leg hip raise builds strength and stability through the hamstrings and glutes. The movement also improves core strength, balance, and coordination.', '["Deite-se de costas com os joelhos flexionados e os calcanhares apoiados no chão. Mantenha os pés afastados e alinhados com os quadris.","Tire uma perna do chão e a estenda completamente.","Contraia o abdome, pressione o calcanhar que foi mantido no chão e eleve os quadris. Termine o movimento contraindo os glúteos.  Volte para o chão e repita."]');
