INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de quadril externo', 'ABDUCTORS', '', 'https://connect.garmin.com/images/exercises/images/EXTERNAL_HIP_RAISE/heroImage_BBtOfeg.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_003-B2.mp4', 'forca,mobilidade', 'HIP_STABILITY', 'Iniciante', '', 'The external hip raise increases strength and stability in hips and glutes. The exercise also actively engages the core.', '["Deite-se de lado com o braço apoiado no chão e estendido à frente. Mantenha as pernas completamente retas e os pés flexionados para você.","Levante a perna de cima em direção ao céu, parando aproximadamente na altura dos quadris e certificando-se de manter os pés e os quadris voltados para a frente completamente. Faça uma pausa e, em seguida, abaixe a perna à posição inicial."]');
