INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Balanço com um braço', 'QUADS', 'Kettlebells', 'https://connect.garmin.com/images/exercises/images/ONE_ARM_SWING/heroImage_BBtOf21.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_243-A3.mp4', 'forca,mobilidade', 'HIP_SWING', 'Iniciante', 'GLUTES, HAMSTRINGS, CALVES', 'The one-arm swing builds power and strength in the hamstrings and glutes. The exercise improves cardiovascular endurance.', '["Fique em pé com os pés alinhados com os ombros, os dedos levemente apontados para fora, e os joelhos ligeiramente flexionados. Segure um kettlebell em uma mão, bem na frente dos quadris. Posicione o outro braço estendido para fora, paralelo ao chão.","Empurre os quadris para trás e incline-se para frente na altura da cintura, mantendo o kettlebell próximo ao corpo. Mantenha o tórax reto, mantenha o abdômen contraído e as costas retas. Em seguida, impulsione os quadris para frente e contraia os glúteos, balançando o kettlebell para frente e para cima. Reverta o movimento para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Balanço de um só braço com haltere', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/SINGLE_ARM_DUMBBELL_SWING/heroImage_BBtOfb9.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_199-A3.mp4', 'forca', 'HIP_SWING', 'Intermediário', 'GLUTES, HAMSTRINGS, CALVES', 'The single-arm dumbbell swing builds power and explosiveness throughout the lower body, more specifically the hips and lower back. The exercise also improves muscular strength in the shoulders and cardiovascular endurance.', '["Fique em pé com os pés afastados e alinhados com os ombros e segure um haltere em frente aos quadris. Flexione os joelhos levemente enquanto segura o peso entre as suas pernas.","Empurre os quadris para trás e então os impulsione para frente enquanto mantém os joelhos levemente flexionados. O peso balançará para a frente até que fique entre o abdômen e o tórax. Empurre o quadril para trás e continue balançando o peso para frente e para trás."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Balanço com kettlebell unilateral', 'QUADS', '', NULL, NULL, 'forca', 'HIP_SWING', '', 'GLUTES, HAMSTRINGS, CALVES', NULL, NULL);
