INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Hiperextensão lombar na bola suíça', 'LOWER_BACK', 'Bola suíça', 'https://connect.garmin.com/images/exercises/images/SWISS_BALL_HYPEREXTENSION/heroImage_BBtOf1R.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_287-A1.mp4', 'forca,mobilidade', 'HYPEREXTENSION', 'Intermediário', '', 'The Swiss ball hyperextension builds strength in the lower back and glutes. Performing the exercise with a Swiss ball also ensures the core is actively engaged throughout the entire range of motion.', '["Posicione-se de joelhos com uma bola suíça a sua frente. Incline-se para frente e posicione a parte superior dos quadris e do estômago sobre a bola suíça. Estenda as pernas para trás. Inicie o movimento com a cabeça erguida e as costas estendidas, com o peito fora da bola e as mãos atrás da cabeça.","Abaixe o tórax e a cabeça até que os tendões estejam alongados e, em seguida, contraia a região lombar retornando à posição inicial."]');
