INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação frontal com cabo', 'SHOULDERS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/CABLE_FRONT_RAISE/heroImage_BBtOf4R.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_132-A4.mp4', 'forca', 'LATERAL_RAISE', 'Intermediário', 'TRAPS', 'The cable front raise increases strength, stability, and muscle growth in the shoulders with an emphasis on the front of the shoulders. Performing the exercise with the cables ensures resistance remains on the shoulders throughout the entire range of motion.', '["Fique em pé em frente a um aparelho de cabo ajustável com os seu pés alinhados com os ombros. Segure a corda na posição baixa com uma mão. Mantenha seu tórax elevado e os ombros para trás.","Mantenha seu tronco firme e levante o braço à sua frente, mantendo-o reto. Quando seu braço atingir a altura do ombro, faça uma pausa. Retorne à posição inicial e repita o movimento antes de realizá-lo com  o outro braço."]');
