INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento "Bom-dia"', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/GOOD_MORNING/heroImage_BBtOcBn.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_009-A3.mp4', 'forca', 'LEG_CURL', 'Iniciante', 'GLUTES, LOWER_BACK', 'The good morning builds strength in the lower back, glutes, and hamstrings while improving core strength and stability.', '["Fique em pé, mantenha os pés afastados e alinhados com os ombros.  Coloque as mãos atrás da cabeça, mantendo o tronco firme e em postura reta.","Flexione os quadris e abaixe o tórax até sentir um estiramento nos tendões da perna e até que as costas fiquem quase paralelas ao chão. Lavante para retornar à posição inicial."]');
