INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de pernas na barra fixa', 'ABS', 'Barra fixa para flexão', 'https://connect.garmin.com/images/exercises/images/HANGING_LEG_RAISE/heroImage_BBtO7CT.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_149-A3.mp4', 'forca', 'LEG_RAISE', 'Intermediário', 'HIPS, FOREARM, SHOULDERS', 'The hanging leg raise is a core strengthening exercise that targets the entire abdominal region with an emphasis on the lower abdominals and hip flexors. This exercise also improves stability in the lower back.', '["Segure-se em uma barra fixa com uma pegada pronada, certificando-se de que os braços fiquem completamente retos e os pés não toquem o chão.","Com as pernas completamente retas durante todo o exercício, contraia o tronco e use o abdômen para elevar os pés em direção aos ombros. Faça uma pausa quando as coxas estiverem na altura do tórax. Retorne à posição inicial."]');
