INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo alternado com haltere', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_LUNGE_WITH_REACH/heroImage_BBtOaa1.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_178-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Iniciante', 'HAMSTRINGS, SHOULDERS, ABS, BICEPS', 'The alternating dumbbell lunge with reach increases mobility and strength throughout the entire body. This exercise specifically targets the legs while also activating the core and shoulders.', '["Segure as extremidades de um haltere com ambas as mãos na altura do peito.","Estufe o peito e dê um passo largo para frente com uma perna. Flexione o joelho de trás em direção ao chão e mantenha a canela da perna da frente o mais vertical possível.","Enquanto mantém seu peito para cima, incline-se para frente com o haltere, sem curvar a região lombar. Retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com halteres e perna traseira elevada', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo alternado com halteres', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_LUNGE/heroImage_BBtOcBi.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_177-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Intermediário', 'HAMSTRINGS', 'The alternating dumbbell lunge is a single-leg strength exercise that targets the quads, hips, hamstrings and core. The alternating structure of the movement improves muscular balance on both sides of the body.', '["Segure um par de halteres com uma pegada neutra de forma que as palmas estejam voltadas uma para a outra. Posicione-se em pé e reto, com os pés afastados e alinhados com os ombros e os braços totalmente estendidos.","Estufe o peito e dê um passo largo para frente com uma perna. Flexione o joelho de trás em direção ao chão e mantenha a canela da perna frontal o mais vertical possível. Impulsione a perna da frente, retornando à posição inicial. Alterne a perna"]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abaixamento unilateral de perna com peso', 'ABS', '', NULL, NULL, 'forca', 'LEG_RAISE', '', 'QUADS', NULL, NULL);
