INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento búlgaro com barra', 'QUADS', 'Barra, Banco', 'https://connect.garmin.com/images/exercises/images/BARBELL_BULGARIAN_SPLIT_SQUAT/heroImage_BBtOf71.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_090-A3.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS', 'The barbell Bulgarian split squat is a challenging single-leg strength exercise for the lower body with an emphasis on the quads and hamstrings. The exercise also improves balance and stability. The Bulgarian split squat is a great squat alternative for people who have lower back problems when they perform barbell squats.', '["Coloque uma barra com anilhas na parte superior das suas costas, com as palmas das mãos voltadas para a frente. Estique uma perna para trás, dobrando ligeiramente o joelho, e coloque os dedos do pé em um banco. Mantenha a perna de apoio esticada.","Empurre os quadris para baixo e para trás, à medida que dobra o joelho e se abaixa, realizando um agachamento com uma perna, usando a perna no banco para se equilibrar. Abaixe-se até que a coxa posicionada na frente fique paralela ao chão e empurre o pé que está no chão para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com cruzamento de barra', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento dividido frontal com barra', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo invertido com barra', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo lateral com barra', 'QUADS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_SIDE_LUNGE/heroImage_BBtOaa4.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_104-A3.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS', 'The barbell side lunge strengthens the legs while also engaging the core. Stepping to the side increases activity of the inner thigh and helps increase balance and stability on both sides.', '["Posicione uma barra de exercícios ou uma barra com pesos sobre a parte superior das costas, puxando a barra para baixo enquanto contrai suas omoplatas uma contra a outra para adquirir estabilidade.","Estufe seu peito e dê um passo largo para o lado.  Abaixe os quadris até o chão e flexione o joelho direito de forma que a coxa fique praticamente paralela ao chão.  Mantenha a perna direita estendida em linha reta. Mantenha o tronco firme e volte à posição inicial."]');
