INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo reverso com halteres', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_REVERSE_LUNGE/heroImage_BBtOcBk.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_186-A3.mp4', 'forca', 'LUNGE', 'Avançado', 'HAMSTRINGS', 'The dumbbell reverse lunge is a single-leg strength exercise that targets the glutes, hamstrings, and quads. The exercise also improves stability and balance on both sides of the body.', '["Segure um par de halteres. Fique em pé, mantenha os pés afastados e alinhados com os ombros.  Seus braços devem ficar suspensos nas laterais do corpo.","Estufe o peito e dê um passo largo para trás abaixando o joelho em direção ao chão. Mantenha a canela da frente o mais vertical possível. Impulsione-se e volte à posição inicial, faça o número de repetições desejadas e então alterne as pernas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo reverso com haltere para joelho no alto e elevação', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS, TRICEPS', NULL, NULL);
