INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo baixo com adução isométrica', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LOW_LUNGE_WITH_ISOMETRIC_ADDUCTION/heroImage_BBtOf7y.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_028-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Intermediário', 'HAMSTRINGS, ADDUCTORS', 'The low lunge with isometric adduction strengthens the inner thighs while increasing hip mobility and functionality.', '["Fique em pé em posição ereta, os pés posicionados na linha dos quadris e os braços soltos ao lado do corpo.","Dê um passo largo para a frente e assuma uma posição de afundo profunda, colocando suas mãos no chão no lado de dentro da sua perna da frente. Pressione o joelho da perna que está realizando o movimento contra seu corpo e o segure."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com uma perna para trás', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, BICEPS', NULL, NULL);
