INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com alcance dos braços', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LUNGE_WITH_ARM_REACH/heroImage_BBtOfcQ.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_030-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Iniciante', 'HAMSTRINGS, SHOULDERS', 'This exercise is a body-weight exercise used to increase mobility, flexibility, and strength throughout the hip and leg region.', '["Posicione-se em pé com os pés alinhados com os quadris e braços completamente estendidos nas laterais do corpo.","Dê passos largos para a frente e fique em posição de afundo, flexionando o joelho da frente a 90 graus. Estenda os braços completamente para baixo, em direção à ponta do pé frontal. Faça uma pausa, retorne ao início e repita com a outra perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com alcance diagonal', 'QUADS', '', NULL, NULL, 'forca,mobilidade', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS', NULL, NULL);
