INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento búlgaro acima da cabeça', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo invertido com halteres sobre a cabeça', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/OVERHEAD_DUMBBELL_LUNGE/heroImage_BBtO4QB.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_195-A4.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS, SHOULDERS', 'The overhead dumbbell lunge increases strength and stability in the shoulder, core, and lower body region. It''s a functional, full body exercise that will help in all areas of physical performance.', '["Fique em pé, mantenha os pés afastados e alinhados com os quadris. Segure um haltere em cada mão, com os braços estendidos, sobre sua cabeça.","Dê um passo largo para frente. Flexione os joelhos a 90 graus enquanto realiza o afundo, mantendo os pesos acima da cabeça. Mantenha o equilíbrio, o abdômen firme e contraído e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo invertido com halteres sobre a cabeça', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo invertido contrabalanceado com haltere', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, TRAPS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com haltere pernas alternadas', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/OVERHEAD_DUMBBELL_SPLIT_SQUAT/heroImage_BBtOcwH.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_196-A4.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS, SHOULDERS', 'The overhead dumbbell split squat helps increase strength and stability in the shoulder, core, and lower body. It''s a functional, full body exercise that will help in all areas of physical performance.', '["Fique em pé em posição de pernas alternadas com um pé na frente do outro. Segure um haltere em cada mão, acima da cabeça.","Flexione seus joelhos a 90 graus enquanto desce em direção ao chão. Traga o joelho de trás para perto do chão. Mantenha o equilíbrio, o abdômen firme e contraído e os braços acima da cabeça. Cuidado para não se inclinar demais para frente. Retorne à posição inicial em pé."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com rotação e mãos acima da cabeça', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS, OBLIQUES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com barra sobre a cabeça', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, SHOULDERS', NULL, NULL);
