INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo reverso deslizante com step', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS, CALVES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo invertido com peso acima da cabeça', 'QUADS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_372-Cam1.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS, SHOULDERS', 'O avanço com halter acima da cabeça aumenta a força e a estabilidade na região dos ombros, do core e da parte inferior do corpo. É um exercício funcional de corpo inteiro, que ajudará em todas as áreas de desempenho físico.', '["Fique de pé com os pés afastados na largura do quadril e pressione a mochila com ambas as mãos e os braços totalmente estendidos acima da cabeça.","Dê um passo para trás e faça o afundo, dobrando os joelhos em aproximadamente 90 graus enquanto mantém a mochila estável acima da cabeça. Empurre o chão com o pé de trás para retornar à posição inicial e repita o movimento no lado oposto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Retrocesso ou afundo reverso', 'QUADS', 'Discos deslizantes', 'https://connect.garmin.com/images/exercises/images/REVERSE_SLIDING_LUNGE/heroImage_BBtO7EG.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_256-A3.mp4', 'forca', 'LUNGE', 'Iniciante', 'HAMSTRINGS, CALVES', 'The reverse sliding lunge improves strength and endurance throughout the lower body while increasing hip flexibility and mobility. This exercise builds stability in the core and hip flexors throughout the range of motion.', '["Em pé, coloque um pé sobre um disco deslizante. Apoie as mãos nos quadris firmemente e mantenha os pés alinhados com os ombros. Esta é a sua posição inicial","Deslize o pé que está no disco para trás e abaixe os quadris para que seu outro joelho fique flexionado em um ângulo de 90 graus. Faça uma pausa e inverta a direção de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com barra nas costas', 'QUADS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_371-Cam1.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS', 'O avanço com halter acima da cabeça aumenta a força e a estabilidade na região dos ombros, do core e da parte inferior do corpo. É um exercício funcional de corpo inteiro, que ajudará em todas as áreas de desempenho físico.', '["Fique de pé com os pés afastados na largura do quadril e posicione a mochila bem firme na parte superior das costas. Coloque os braços em uma posição relaxada nas laterais.","Dê um passo para trás e faça o afundo, abaixando os joelhos em aproximadamente 90 graus. Empurre o chão com o pé de trás para retornar à posição inicial e repita o movimento no lado oposto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo de corredor para equilíbrio', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/RUNNERS_LUNGE_TO_BALANCE/heroImage_BBtOiK4.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_025-A3.mp4', 'forca,mobilidade', 'LUNGE', 'Intermediário', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS', 'The runner''s lunge to balance is a strength and conditioning exercise. It helps improve hip mobility, stability, overall function of the lower body, and emphasizes building strength in the backs of the legs.', '["Partindo da posição em pé, dê um passo para trás com uma perna, dobrando o joelho da frente e abaixando o de trás em direção ao chão, em posição de afundo. Mantenha a canela da frente o mais vertical possível.","Levante-se pressionando o calcanhar da frente contra o chão, e simultaneamente erga a perna de trás e leve os quadris à frente da linha da coxa, inclinando a parte superior do corpo em direção ao chão. Mantenha as costas estendidas, fique nessa posição durante o tempo desejado e retorne à posição de afundo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Salto tesoura alternado', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo lateral', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/SHIFTING_SIDE_LUNGE/heroImage_BBtOhcH.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_179-A1.mp4', 'forca,mobilidade', 'LUNGE', 'Intermediário', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS', 'This dynamic multi-joint exercise targets the lower body, while increasing hip mobility and core stability.', '["Segure um haltere em cada mão, com os braços completamente estendidos. Empurre o tórax para fora, dê um passo largo para o lado, leve os quadris para trás e flexione o joelho da perna principal.  Mantenha a outra perna o mais estendida possível.","Enquanto assume a posição de afundo, incline os quadris para frente e leve os halteres para ambos os lados da perna que está realizando o movimento, evitando encurvar a região lombar. Flexione o joelho oposto, deslocando o peso para as duas pernas enquanto leva os halteres à sua frente, em linha reta para baixo.","Estique a perna que estava flexionada, deslocando seu peso para o lado oposto enquanto assume a posição de afundo, colocando os halteres em ambos os lados dessa perna. Impulsione a perna que está realizando o movimento, unindo os pés e retornando à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo cruzado e lateral', 'QUADS', '', NULL, NULL, 'forca,mobilidade', 'LUNGE', '', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Salto de afundo lateral', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/SIDE_LUNGE_JUMP_OFF/heroImage_BBtOh61.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_307-A4.mp4', 'forca', 'LUNGE', 'Intermediário', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS, CALVES', 'O salto de afundo lateral é um exercício explosivo e dinâmico que desenvolve a força da parte inferior do corpo com ênfase nos quadríceps, glúteos e isquiotibiais. O exercício também melhora a flexibilidade da parte inferior do corpo e a mobilidade do quadril.', '["Fique em pé com os pés afastados na largura dos quadris. Segure um haltere em cada mão. Dê um passo grande para o lado com uma perna. Empurre os quadris para trás, dobre o joelho e agache. Ao abaixar o corpo, leve os pesos em direção ao chão em ambos os lados da perna da frente.","Pule saindo do chão e indo na direção oposta, ao pousar volte para a posição de afundo lateral."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo lateral para toque de cruzamento', 'QUADS', '', NULL, NULL, 'forca,mobilidade', 'LUNGE', '', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo lateral cruzado', 'QUADS', '', NULL, NULL, 'forca,mobilidade', 'LUNGE', '', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS, HIPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo lateral com golpes', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SIDE_TO_SIDE_LUNGE_CHOPS/heroImage_BBtOaaf.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_021-A4.mp4', 'forca,mobilidade', 'LUNGE', 'Iniciante', 'HAMSTRINGS, ADDUCTORS, ABDUCTORS, OBLIQUES, ABS', 'Side-to-side lunge chops are a total-body exercise that strengthens the inner thighs, quads, hamstrings, and glutes while engaging the core.', '["Fique em pé, com as costas retas, os pés juntos e o braços entrelaçados acima da cabeça. Dê um passo grande para um dos lados enquanto abaixa os quadris e dobra o joelho da perna que está realizando o movimento, mantendo a perna de apoio o mais reto possível. Abaixe ambos os braços em linha reta em direção ao pé que está realizando o movimento.","Impulsione a perna principal para retornar à posição inicial."]');
