INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com barra e deslocamento para frente', 'QUADS', '', NULL, NULL, 'forca', 'LUNGE', '', 'HAMSTRINGS', NULL, NULL);
