INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Estocada ambulante', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/WALKING_LUNGE/heroImage_BBtOcIa.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_043-A3.mp4', 'forca', 'LUNGE', 'Iniciante', 'HAMSTRINGS', 'This exercise targets the thighs and hips, while increasing balance and stability throughout your lower body.', '["Posicione-se em pé com os pés juntos. Dê um passo largo para frente com uma das pernas. Abaixe-se em um movimento de afundo flexionando ambos os joelhos a um ângulo de 90 graus. Mantenha o tronco ereto, enquanto permanece com o tórax elevado e os ombros para trás. Mantenha-se equilibrado.","Dê um passo para frente com o pé de trás, unindo ambos os pés. Siga em frente, alternando as pernas."]');
