INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Power Clean com barra', 'QUADS', '', NULL, NULL, 'forca', 'OLYMPIC_LIFT', '', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento olímpico com barra', 'GLUTES', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_SNATCH/heroImage_BBtOa2M.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_312-A4.mp4', 'forca', 'OLYMPIC_LIFT', 'Avançado', 'ABS, BICEPS, HAMSTRINGS, LOWER_BACK, TRAPS, TRICEPS, CALVES, ADDUCTORS', 'O snatch com barra é um movimento complexo multiarticular que cria força explosiva, velocidade e força em todo o corpo, melhorando a coordenação e a estabilidade do core. O snatch requer não apenas força na parte inferior do corpo, mas também mobilidade dos ombros para elevar a barra completamente acima da cabeça.', '["Pegue uma barra com uma pegada mais larga do que a largura dos ombros, quadris e joelhos levemente dobrados e as costas retas. Empurrando os pés no chão, puxe a barra para cima, logo acima dos joelhos, para descansar.","Estendendo os joelhos e pressionando os quadris, empurre com explosão a barra em direção ao teto. Encolha os ombros ao mesmo tempo, gerando impulso para empurrar a barra.","Estenda os braços sobre a cabeça e trave os cotovelos enquanto abaixa os quadris para colocar o corpo embaixo da barra. Empurre os pés no chão e estenda os quadris para ficar de pé. Inverta o movimento para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de barra com explosão', 'SHOULDERS', '', NULL, NULL, 'forca', 'OLYMPIC_LIFT', '', 'ABS, QUADS, TRICEPS, HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Clean com barra', 'QUADS', '', NULL, NULL, 'forca', 'OLYMPIC_LIFT', '', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Hang Clean com agachamento com barra', 'QUADS', '', NULL, NULL, 'forca', 'OLYMPIC_LIFT', '', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK, ADDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Limpeza da barra', 'QUADS', 'Barra', 'https://connect.garmin.com/images/exercises/images/CLEAN/heroImage_BBtOcCL.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_313-A4.mp4', 'forca', 'OLYMPIC_LIFT', 'Avançado', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK, ADDUCTORS', 'O clean é um exercício multiarticular que desenvolve potência e força em todo o corpo. O exercício também ajuda a criar força do core e na coordenação atlética. O movimento requer força na parte inferior e superior do corpo para puxar o peso para cima e trazer seu corpo para baixo do peso para “pegá-lo”. O movimento é uma combinação de extensão de quadril e puxada alta, e depois termina com um agachamento de um quarto.', '["Fique em pé com os pés afastados na largura dos ombros e as canelas a cerca de cinco centímetros de distância de uma barra carregada. Mantendo a coluna reta, empurre os quadris para trás e pegue a barra com as duas mãos na largura dos ombros.","Mantendo o core firme, levante a barra em direção aos calcanhares. Quando a barra passar pelos joelhos, estenda com explosão os tornozelos, joelhos e quadris ao mesmo tempo. À medida que a barra sobe, encolha os ombros e continue a puxar a barra para cima.","Quando a barra atingir a altura do ombro, gire os cotovelos por baixo para criar uma plataforma na frente dos ombros para a barra descansar. Faça uma pausa e, em seguida, retorne a barra ao chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Clean & Jerk', 'QUADS', '', NULL, NULL, 'forca', 'OLYMPIC_LIFT', '', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK, ADDUCTORS, TRICEPS', NULL, NULL);
