INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha de 45 graus', 'ABS', 'Banco', 'https://connect.garmin.com/images/exercises/images/_45_DEGREE_PLANK/heroImage_BBtO57R.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_082-B1.mp4', 'forca', 'PLANK', 'Iniciante', 'HIPS', 'The 45-degree plank is a core-strengthening exercise that targets the entire core as well as the upper body. The 45-degree angle enables beginners to progressively adapt to the demand placed on the core before performing a standard plank.', '["Apoie os antebraços sobre um banco e abaixe-se em posição de flexão de modo que os braços e o tronco formem um ângulo de 90 graus e o corpo forme uma linha reta dos ombros aos tornozelos. Mantenha o tronco firme e encaixado, contraia os glúteos e permaneça nessa posição pelo máximo de tempo possível."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Posição estática a 90 graus', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'HIPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alternância de pernas cruzada', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/CROSS_BODY_MOUNTAIN_CLIMBER/heroImage_BBtOl77.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_004-A1.mp4', 'forca', 'PLANK', 'Intermediário', 'HIPS, SHOULDERS, CHEST, TRICEPS', 'The cross-body mountain climber is a core strengthening exercise that targets the entire abdominal region. The cross-body movement more actively engages the obliques and hip flexors. The exercise also improves upper body strength and stability in the chest, shoulders, and triceps.', '["No chão, fique em posição de exercício de flexão. Certifique-se de posicionar as mãos um pouco mais afastadas que a largura dos ombros. Seu corpo deverá formar uma linha reta entre os pés e a cabeça.","Contraia o abdômen e o mantenha contraído durante todo o exercício. Leve um joelho em direção ao cotovelo oposto. Retorne à posição inicial para repetir o movimento no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com movimento de pernas no topo', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com os pés elevados', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal elevador', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/ELEVATOR_ABS/heroImage_BBtOhl6.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_005-B1.mp4', 'forca', 'PLANK', 'Intermediário', 'SHOULDERS, LOWER_BACK', 'This exercise is a unique core-strengthening exercise that targets your abs and obliques, while increasing mobility in the shoulder and upper back regions.', '["Coloque-se em posição de flexão de braços com suas mãos alinhadas com os ombros e posicionadas diretamente abaixo deles. Conduza um joelho em direção ao cotovelo e apoie-o firmemente contra o braço.","Mantenha o tronco firme e encaixado e deslize o joelho para baixo, passando pelo antebraço e em direção ao pulso. Pause. Permaneça com o tronco firme, puxe o joelho de volta pelo antebraço até que alcance o cotovelo. Retorne a perna à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha estendida', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, LOWER_BACK', NULL, NULL);
