INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Caminhada de urso', 'ABS', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_008_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_008_CamA.mp4', 'forca,mobilidade', 'WARM_UP', 'Iniciante', 'HIPS, QUADS, SHOULDERS, CHEST, TRICEPS', '', '["Fique na posição de quatro apoios, com os pés e as mãos no chão.","Caminhe lentamente para frente, movendo o braço esquerdo para a frente com a perna direita e, em seguida, o braço direito com a perna esquerda."]');
