INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Escalador e extensão modificados', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'HIPS, SHOULDERS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Escalador de montanha', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/MOUNTAIN_CLIMBER/heroImage_BBtOla0.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_024-A1.mp4', 'forca,mobilidade', 'PLANK', 'Intermediário', 'HIPS, SHOULDERS, TRICEPS', 'The mountain climber is a dynamic exercise that increases core strength and stability through repeated lower body motion while the upper body works to stabilize the rest of the body. The movement may also be used for improving cardiovascular endurance.', '["Comece na posição de flexão com os braços completamente retos e diretamente embaixo dos ombros. Seu corpo deve formar uma linha reta dos tornozelos aos ombros.","Contraia seu abdômen, levante uma perna do chão e traga seu joelho em direção ao tórax enquanto mantém o corpo o mais reto possível. Retorne à posição inicial e repita o movimento com a perna oposta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alternância de pernas sobre discos deslizantes', 'ABS', 'Discos deslizantes', 'https://connect.garmin.com/images/exercises/images/MOUNTAIN_CLIMBER_ON_SLIDING_DISCS/heroImage_BBtOlcj.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_255-A1.mp4', 'forca', 'PLANK', 'Intermediário', 'HIPS, QUADS, SHOULDERS, TRICEPS', 'Mountain climbers on sliding discs are a dynamic core strengthening exercise that targets the entire abdominal region including the obliques. The exercise also improves strength in the chest, shoulders, and triceps. Performing the exercise at higher repetitions also improves cardiovascular endurance.', '["Coloque-se em posição de flexão, com os pés apoiados em um par de discos deslizantes. Deslize uma perna para frente com um joelho avançando em direção ao corpo o mais alto possível.","Deslize essa perna de volta enquanto desliza o outro joelho para frente e para cima em direção ao tórax.","Em seguida, contraia o abdômen e deslize ambos os joelhos até o tórax, simultaneamente."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Escalador com pés no Bosu® Balance Trainer', 'ABS', 'Bola suíça', 'https://connect.garmin.com/images/exercises/images/MOUNTAIN_CLIMBER_WITH_FEET_ON_BOSU_BALL/heroImage_BBtOcOA.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_258-A1.mp4', 'forca', 'PLANK', 'Intermediário', 'HIPS, SHOULDERS, TRICEPS', 'The mountain climber with feet on Bosu ball builds strength and stability in the core and shoulders. This exercise also improves cardiovascular endurance. Performing the exercise on a Bosu ball increases the difficulty of the move.', '["Coloque-se em posição de flexão com os pés sobre uma bola Bosu e as mãos apoiadas no chão, mantendo o corpo reto. Estenda os braços completamente, encaixe os cotovelos e mantenha o tronco firme.","Levante um dos pés da bola e traga o joelho em direção ao tórax. Mantenha-se nessa posição por um momento com a postura firme. Retorne à posição inicial para repetir o movimento com a perna oposta."]');
