INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com saltos', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, QUADS, HIPS, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com levantamento de braço', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/PLANK_WITH_ARM_RAISE/heroImage_BBtO52U.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_017-A1.mp4', 'forca', 'PLANK', 'Intermediário', 'SHOULDERS, LOWER_BACK', 'The plank with arm raise is a multi-functional exercise that improves shoulder and spinal stability while developing strength in the core and lower back regions.', '["Comece na posição de prancha com seu peso apoiado sobre os antebraços e seu corpo completamente em linha reta desde os ombros até os tornozelos.","Contraia o abdômen e, sem deixar os quadris se moverem, eleve um braço e o estendido à sua frente. Faça uma pausa e, em seguida, abaixe o braço de volta à posição inicial."]');
