INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com joelho ao cotovelo', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, QUADS, GLUTES, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com elevação da perna', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/PLANK_WITH_LEG_LIFT/heroImage_BBtOnpr.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_063-A2.mp4', 'forca,yoga,pilates', 'PLANK', 'Avançado', 'GLUTES, LOWER_BACK', 'This exercise emphasizes full-body strength while adding an extra challenge of balance.', '["Comece na posição de prancha.","Levante a perna direita e abaixe-a até o chão.","Levante a perna esquerda e abaixe-a até o chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com abdominal oblíquo', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/PLANK_WITH_OBLIQUE_CRUNCH/heroImage_BBtOiTe.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_018-A1.mp4', 'forca', 'PLANK', 'Intermediário', 'LOWER_BACK, HIPS', 'The plank with oblique crunch is a multi-functional exercise that improves core strength with an emphasis on the obliques. The exercise also develops stability throughout the lower back and spine.', '["Comece na posição de prancha, com o corpo em linha reta e com as mãos diretamente embaixo dos ombros.","Flexione uma perna e traga um joelho em direção ao ombro do mesmo lado, comprimindo assim os músculos oblíquos.  Mantenha o tronco imóvel durante o movimento. Faça uma pausa e retorne a perna à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral pliométrica', 'OBLIQUES', '', NULL, NULL, 'forca', 'PLANK', '', 'ABS, LOWER_BACK', NULL, NULL);
