INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral rotatória', 'ABS', '', NULL, NULL, 'forca', 'PLANK', '', 'SHOULDERS, LOWER_BACK, ADDUCTORS, ABDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral', 'OBLIQUES', '', 'https://connect.garmin.com/images/exercises/images/SIDE_PLANK/heroImage_BBtOlhK.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_019-A3.mp4', 'forca,yoga,pilates', 'PLANK', 'Intermediário', 'ABS, SHOULDERS', 'Esta postura muitas vezes é chamada de "postura do sábio" porque "vasistaha" é um termo que é traduzido como "o melhor ou o mais excelente sábio."', '["Comece na posição de prancha frontal, apoiado sobre as mãos e dedos dos pés.","Impulsione-se com sua mão esquerda e gire o corpo para sua direita. Empilhe os pés um sobre o outro.","Empurre o quadril em direção ao teto conforme estende seu braço direito para a mesma direção.","Retorne para a posição de prancha frontal e repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral e remada', 'OBLIQUES', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/SIDE_PLANK_AND_ROW/heroImage_BBtOlbt.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_141-A2.mp4', 'forca', 'PLANK', 'Intermediário', 'ABS, BICEPS, LOWER_BACK, ADDUCTORS, ABDUCTORS', 'The side plank and row is a variation and progression of the side plank. This exercise increases strength and stability throughout the core and back region.', '["Posicione-se próximo a um aparelho de cabo de polia baixa e fique em posição de prancha lateral sobre seu antebraço, de frente para o cabo. Segure o cabo com sua mão livre e a palma voltada para o chão. O braço deverá estar totalmente estendido.","Mantenha o tronco firme e flexione o cotovelo, ultrapassando a linha das costas enquanto puxa simultaneamente a alça para sua lateral. Faça uma pausa e contraia os músculos em volta de sua escápulas. Retorne lentamente sua mão à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral com elevação', 'OBLIQUES', '', NULL, NULL, 'forca', 'PLANK', '', 'ABS, GLUTES, SHOULDERS, LOWER_BACK, ADDUCTORS, ABDUCTORS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral com pés no banco', 'OBLIQUES', 'Caixa', 'https://connect.garmin.com/images/exercises/images/SIDE_PLANK_WITH_FEET_ON_BENCH/heroImage_BBtO50Z.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_270-A2.mp4', 'forca', 'PLANK', 'Intermediário', 'SHOULDERS, ABS', 'The side plank with feet on bench is a progression from a normal side plank that targets the core, with an emphasis on the obliques. Performing with feet elevated also increases the resistance on the shoulders and triceps.', '["Deite-se no chão, posicione um cotovelo embaixo de seu corpo e empilhe os pés sobre um banco de forma que seu corpo esteja voltado para o lado.","Levante os quadris do chão para que seu corpo forme uma linha reta desde os tornozelos até os ombros. Mantenha-se nessa posição com o tronco firme e encaixado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha lateral com cotovelo no Bosu® Balance Trainer', 'OBLIQUES', '', NULL, NULL, 'forca', 'PLANK', '', 'GLUTES, SHOULDERS', NULL, NULL);
