INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha isométrica com peso', 'ABS', 'Anilhas', 'https://connect.garmin.com/images/exercises/images/WEIGHTED_PLANK/heroImage_BBtOfg0.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_264-A1.mp4', 'forca', 'PLANK', 'Avançado', 'SHOULDERS', 'The weighted plank is a more difficult progression of the bodyweight plank by adding a weight plate. This exercise will increase strength and stability throughout the core, chest, shoulders, and triceps.', '["Instrua seu colega a colocar a anilha cuidadosamente sobre suas costas. Cuidado para não deixar que seus quadris caiam com este peso adicional. Mantenha essa posição durante o tempo recomendado."]');
