INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Salto afundo alternado com pliometria', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_JUMP_LUNGE/heroImage_BBtOf70.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_001-A3.mp4', 'forca', 'PLYO', 'Avançado', 'HAMSTRINGS', 'The jump lunge helps increase explosive power in the lower body. This unilateral exercise also improves stability and balance throughout the body.', '["Comece com uma perna na frente da outra, com as mãos em seus quadris, o tronco ereto e os joelhos dobrados a 90 graus. Empurre o tórax para fora e abaixe o joelho de trás em direção ao chão, em posição de afundo, mantendo a canela da perna da frente mais vertical o possível.","Saia do chão com um forte impulso, pulando e trocando a posição das pernas enquanto estiver no ar. Atinja o chão em posição de afundo, com a perna oposta para a frente. Repita alternando a posição das pernas em cada salto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha com abertura ampla e elevação de braço e perna intercalados', 'SHOULDERS', '', NULL, NULL, 'forca', 'PLANK', '', 'LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com salto e barra', 'QUADS', 'Barra, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/BARBELL_JUMP_SQUAT/heroImage_BBtOiEa.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_102-A3.mp4', 'forca', 'PLYO', 'Avançado', 'HAMSTRINGS, HIPS', 'The barbell jump squat increases lower body explosiveness with a focus on the quads, hamstrings, glutes, and calves. This exercise also improves core stability.', '["Coloque uma barra sobre a parte superior de suas costas com uma pegada pronada, da mesma forma que em um agachamento com a barra atrás. Posicione seus pés alinhados com os ombros, com as pontas dos pés apontados para frente ou ligeiramente para fora.  Esta é a sua posição inicial","Abaixe os quadris até a posição de agachamento de um quarto, como se estivesse fazendo um salto vertical.","Eleve os quadris explosivamente e pule o mais alto possível, enquanto mantém a barra estável. Aterrisse suavemente sobre as pontas dos pés, pois isso amortecerá o impacto. Retorne à posição inicial."]');
