INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com salto e com peso corporal', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/BODY_WEIGHT_JUMP_SQUAT/heroImage_BBtOl2P.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_010-A3.mp4', 'forca', 'PLYO', 'Intermediário', 'HAMSTRINGS, HIPS', 'This exercise increases explosive lower-body power and strength throughout the legs while also improving core stability.', '["Posicione os dedos atrás da cabeça e puxe os cotovelos para trás de forma que fiquem alinhados com o corpo.  Coloque-se em pé com os pés afastados e alinhados com os ombros e abaixe-se assumindo uma posição de agachamento.","Mantenha o tronco firme e, explosivamente, impulsione os quadris para cima, pulando o mais alto que puder. Certifique-se de tomar impulso com os calcanhares, não com os dedos dos pés. Ao aterrissar, agache-se imediatamente e pule novamente."]');
