INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Bater a bola de exercício', 'ABS', 'Bola medicinal', 'https://connect.garmin.com/images/exercises/images/MEDICINE_BALL_SLAM/heroImage_BBtO7HX.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_250-A4.mp4', 'forca', 'PLYO', 'Iniciante', 'LATS, SHOULDERS, QUADS', 'O exercício com bola medicinal é dinâmico e complexo, e desenvolve potência e força em todo o corpo com ênfase no core.', '["Pegue uma bola medicinal e segure-a acima da cabeça. Seus braços devem estar levemente flexionados e os pés afastados na largura dos ombros.","Atire a bola no chão à sua frente o mais forte que puder. Pegue a bola depois que ela quicar ou pegue a bola e retorne à posição inicial."]');
