INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com saltos e inclinação lateral', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SIDE_TO_SIDE_SHUFFLE_JUMP/heroImage_BBtOa3C.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_022-A3.mp4', 'forca', 'PLYO', 'Intermediário', 'GLUTES, HAMSTRINGS, ABDUCTORS, ADDUCTORS', 'The side-to-side shuffle jump drill develops strength, power, and agility in the lower body. This drill also improves cardiovascular endurance, athletic coordination, and balance.', '["Fique em pé com os pés afastados e alinhados com os ombros e com os braços ao lado do corpo. Efetue o agachamento, estendendo uma mão em direção ao lado externo do pé.","Dê um salto lateral em direção ao lado oposto. Ao voltar ao chão, estenda a outra mão em direção ao lado externo do outro pé."]');
