INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Burpee com barra fixa pronada', 'ABS', '', NULL, NULL, 'forca', 'PULL_UP', '', 'SHOULDERS, TRICEPS, HAMSTRINGS, BICEPS, FOREARM', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Barra fixa supinada', 'BICEPS', 'Barra fixa para flexão', 'https://connect.garmin.com/images/exercises/images/CHIN_UP/heroImage_BBtOhfQ.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_147-A3.mp4', 'forca', 'PULL_UP', 'Iniciante', 'TRAPS, FOREARM, SHOULDERS', 'The chin-up is a bodyweight exercise that trains the back and biceps. The exercise places more emphasis on the forearms and biceps vs. a traditional pull-up.', '["Segure-se em uma barra fixa com uma pegada supinada, mantendo as mãos alinhadas com os ombros.  Suspenda-se ao comprimento do braço e puxe as escápulas para baixo e para trás, de modo que os ombros fiquem o mais longe possível das orelhas.","Puxe o tórax contra a barra enquanto contrai as escápulas, uma contra a outra. Faça uma pausa e então abaixe o corpo de volta à posição inicial."]');
