INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Puxada pela frente na polia alta (Lat Pulldown)', 'LATS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/LAT_PULLDOWN/heroImage_BBtOl22.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_144-A1.mp4', 'forca', 'PULL_UP', 'Iniciante', 'BICEPS, TRAPS, SHOULDERS', 'The lat pulldown is a basic upper body strength exercise that targets the upper back. The exercise also improves stability in the lower back and core.', '["Sente-se num aparelho de puxada pela frente e pegue a barra em pronação, apenas um pouco além da largura dos ombros. Os braços devem ficar completamente esticados e o tronco ereto.","Puxe as omoplatas dos ombros para baixo e para trás e traga a barra até seu peito.  Faça uma pausa e retorne lentamente à posição inicial."]');
