INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Barra fixa pronada com pegada neutra', 'LATS', '', NULL, NULL, 'forca', 'PULL_UP', '', 'BICEPS, FOREARM', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Barra fixa supinada com pegada neutra', 'LATS', '', NULL, NULL, 'forca', 'PULL_UP', '', 'BICEPS, FOREARM, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Barra fixa pronada', 'LATS', 'Barra fixa para flexão', 'https://connect.garmin.com/images/exercises/images/PULL_UP/heroImage_BBtO551.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_145-A3.mp4', 'forca', 'PULL_UP', 'Intermediário', 'BICEPS, FOREARM, SHOULDERS', 'The pull-up is a challenging bodyweight movement that develops the entire back while strengthening the biceps, forearms, and core. The pull-up also increases stability throughout the shoulders. To ensure full back engagement, start each rep from a dead hang (arms fully extended) and pull your elbows into your ribcage and squeeze your lats as you pull your body up.', '["Segure-se em uma barra fixa com uma pegada pronada e com as mãos alinhadas com os ombros, certificando-se de que seus braços estejam completamente retos e seus pés não estejam tocando o chão.  Esta é a sua posição inicial","Eleve o corpo até que o queixo ultrapasse a barra. Lembre-se de contrair ativamente as costas, puxando os cotovelos para trás. Mantenha a cabeça em posição neutra e os olhos fixos em algum ponto adiante. Abaixe o corpo até que os ombros e os braços estejam completamente estendidos e de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pulldown com pegada invertida', 'LATS', '', NULL, NULL, 'forca', 'PULL_UP', '', 'TRAPS, ABS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pulldown de braços retos', 'LATS', '', NULL, NULL, 'forca', 'PULL_UP', '', 'ABS, CHEST, SHOULDERS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pullover no cabo em pé', 'LATS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/STANDING_CABLE_PULLOVER/heroImage_BBtOl1T.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_140-B4.mp4', 'forca', 'PULL_UP', 'Iniciante', 'ABS, CHEST, SHOULDERS, TRAPS', 'The standing cable pullover is an isolation movement that builds size and strength in the back and chest while improving core stabilization.', '["Fique em pé de frente para um aparelho de cabo ajustável com  barra reta anexada em uma posição alta. Segure a barra com as mãos em pronação e alinhadas com os ombros.","Com os braços retos, puxe a barra para baixo, formando um arco, enquanto aproxima as escápulas, mantendo seu tronco firme. Quando a barra atingir suas coxas, faça uma pausa e retorne à posição inicial."]');
