INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Puxada pela frente com pegada pronada aberta (lat pulldown)', 'LATS', 'Aparelho de cabo, Puxador, Banco', 'https://connect.garmin.com/images/exercises/images/WIDE_GRIP_LAT_PULLDOWN/heroImage_BBtOf5C.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_138-A4.mp4', 'forca', 'PULL_UP', 'Iniciante', 'TRAPS, SHOULDERS', 'The wide-grip lat pulldown is an upper body strength exercise and variation to the traditional pulldown that targets the back. The wide-grip position targets the outer lats and reduces the resistance placed on the biceps and forearms.', '["Sente-se em um banco de frente para um aparelho de cabo ajustável, com uma barra de puxada pela frente em posição alta. Com as costas retas, segure a barra em pronação, braços totalmente estendidos e as mãos separadas uma da outra pelo dobro da largura do ombro.","Puxe as escápulas para baixo e para trás, aproximando a barra do tórax. Faça uma pausa e retorne à posição inicial."]');
