INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de braços explosiva', 'CHEST', '', 'https://connect.garmin.com/images/exercises/images/EXPLOSIVE_PUSH_UP/heroImage_BBtOf7f.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_306-A1.mp4', 'forca', 'PUSH_UP', 'Avançado', 'ABS, SHOULDERS', 'A flexão explosiva é um exercício para a parte superior que aumenta a força no peito, nos ombros e nos tríceps. Este exercício também melhora a resistência muscular e a estabilização do tronco.', '["Assuma uma posição de flexão de braço com as mãos ligeiramente mais abertas em relação aos ombros. Seu corpo deve formar uma linha reta dos tornozelos até a cabeça. Esta é a sua posição inicial.","Dobre os cotovelos e a parte inferior do corpo até que o peito quase toque o chão.","Empurre seu corpo para cima dando impulso e tirando suas mãos do chão. Em seguida, desça o corpo com os braços estendidos e volte para a posição inicial."]');
