INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de braços', 'CHEST', '', 'https://connect.garmin.com/images/exercises/images/PUSH_UP/heroImage_BBtO7xT.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_026-A2.mp4', 'forca', 'PUSH_UP', 'Iniciante', 'ABS, SHOULDERS, TRICEPS', 'The push-up is basic upper body strength-building exercise with an emphasis on the chest. The exercise also strengthens the shoulders and triceps.', '["Posicione-se sobre os quatro apoios, com as mãos levemente mais afastadas que a largura dos ombros. Seu corpo deve formar uma linha reta com os tornozelos e ombros. Contraia o abdômen o mais firmemente possível e mantenha-o contraído durante todo o exercício.","Abaixe o corpo até que o peito esteja bem próximo do chão. Certifique-se de direcionar os cotovelos para perto do tronco de forma a evitar que se desviem para fora. Faça uma pausa e, em seguida, impulsione-se de volta à posição inicial."]');
