INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de braços Homem-Aranha', 'CHEST', '', 'https://connect.garmin.com/images/exercises/images/SPIDERMAN_PUSH_UP/heroImage_BBtOhcq.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_308-A1.mp4', 'forca', 'PUSH_UP', 'Avançado', 'ABS, SHOULDERS, TRICEPS, OBLIQUES, ABDUCTORS', 'A flexão Homem-Aranha é uma progressão avançada de flexão de braço que treina o peito, os tríceps e os ombros. O movimento também fortalece o tronco e melhora o equilíbrio.', '["Posicione-se sobre os quatro apoios, com as mãos levemente mais afastadas que a largura dos ombros. Seu corpo deve formar uma linha reta com os tornozelos e ombros. Contraia o abdômen o mais firmemente possível e mantenha-o contraído durante todo o exercício.","Enquanto você abaixa na flexão, puxe um joelho para cima e em direção ao cotovelo do mesmo lado. Faça uma pausa e, em seguida, empurre seu corpo para trás e retorne a perna levantada para a posição inicial. Alterne os lados."]');
