INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de braços em T', 'CHEST', '', 'https://connect.garmin.com/images/exercises/images/T_PUSH_UP/heroImage_BBtOf7Q.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_038-A2.mp4', 'forca', 'PUSH_UP', 'Avançado', 'SHOULDERS, TRICEPS, ABS', 'This is an upper body exercise and advanced progression of the standard push-up that targets the chest, shoulders, and triceps. The T push-up also develops core strength with an emphasis on the obliques.', '["Coloque-se na posição de flexão, com as mãos levemente mais afastadas que a largura dos ombros, e os cotovelos totalmente travados.  O corpo deve formar uma linha reta.","Mantenha o tronco firme e abaixe-se lentamente até o chão. Lembre-se de manter os cotovelos juntos às suas laterais para que formem um ângulo de 45 graus com o tronco. Quando o peito tocar no chão, pause e então retorne à posição inicial.","Então, tire uma das mãos do chão e a leve em direção ao teto, girando a parte superior do corpo na mesma direção até que seu corpo adquira a forma de um T. Retorne à posição inicial."]');
