INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada alternada com halteres', 'LATS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_ROW/heroImage_BBtOiNm.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_168-A3.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'The alternating dumbbell row increases strength throughout the back and shoulders. Performing the exercise with dumbbells and in an alternating manner ensures muscular balance on both sides of the body.', '["Posicione-se em pé, mantenha os pés afastados e alinhados com os ombros e segure um haltere em cada mão com uma pegada pronada. Incline-se para frente na altura dos quadris e estenda os braços completamente de forma que cada haltere fique logo acima do chão. Esta é a sua posição inicial","Contraia as escápulas e puxe um cotovelo para trás, ultrapassando a altura das costas, até que o haltere fique ao lado do tronco. Faça uma pausa por um instante no topo e abaixe lentamente o braço enquanto puxa o outro cotovelo simultaneamente em sua direção. Continue alternando para frente e para trás."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão com os braços afastados verticalmente e com peso', 'CHEST', '', NULL, NULL, 'forca', 'PUSH_UP', '', 'ABS, SHOULDERS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada no banco', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, FOREARM, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Face pulls com faixa elástica', 'SHOULDERS', '', NULL, NULL, 'forca', 'ROW', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com barra', 'LATS', '', 'https://connect.garmin.com/images/exercises/images/BARBELL_ROW/heroImage_BBtO7rP.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_310-A4.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'A remada com barra, também conhecida como remada inclinada, é um dos melhores exercícios de fortalecimento muscular para a parte superior das costas. Embora se concentre nos músculos da parte superior das costas, também requer assistência da parte inferior das costas, músculos do core e do braço para que o exercício seja realizado de forma segura e correta.', '["Segure a barra com as duas mãos e fique ereto. Incline o tronco para a frente até que fique quase paralelo ao chão.","Puxe a barra em direção ao umbigo retraindo as omoplatas e levando os cotovelos para trás do corpo. Toque seu corpo com a barra, faça uma pausa e, em seguida, abaixe a barra lentamente até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento terra com perna reta com supino para remada', 'HAMSTRINGS', '', NULL, NULL, 'forca', 'ROW', '', 'GLUTES, BICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada inclinada com barra', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada inclinada com halteres', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada em pé', 'LATS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/CABLE_ROW_STANDING/heroImage_BBtO4TF.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_133-A4.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'A remada em pé com elástico tem como alvo a parte superior das costas e os ombros, enquanto aumenta a força e a estabilidade na parte inferior do corpo e no core.', '["Fique na frente de um equipamento com os pés afastados na largura dos ombros e os joelhos levemente dobrados. Segure um acessório de barra reta com uma pegada ampla com configuração baixa.","Puxe a barra em direção ao tronco, mantendo o peito para a frente e as costas retas. Faça uma pausa e, em seguida, retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com halteres no suporte no peito', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada declinada na argola', 'TRAPS', '', NULL, NULL, 'forca', 'ROW', '', 'SHOULDERS, CHEST', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com halteres', 'LATS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_ROW/heroImage_BBtOh8f.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_187-A3.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'The dumbbell row is a basic exercise that strengthens the back, shoulders, and biceps while actively engaging the core throughout the movement. Utilizing dumbbells creates balance and stability on both sides of the body.', '["Fique em pé com os pés afastados na largura dos ombros e segure um haltere em cada mão. Dobre os joelhos ligeiramente e incline-se na altura da cintura com as costas retas. Deixe os halteres pendurados na frente do corpo com os braços totalmente estendidos.","Contraia as costas, flexione os braços e eleve ambos os halteres em direção ao tórax.  Permaneça por um momento na posição superior e, em seguida, abaixe os halteres até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada invertida com pés elevados', 'TRAPS', '', NULL, NULL, 'forca', 'ROW', '', 'SHOULDERS, CHEST', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Face Pull', 'SHOULDERS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/FACE_PULL/heroImage_BBtOl1i.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_136-B1.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LATS', 'The face pull is a dynamic exercise increases strength in the shoulders, more specifically the rear regions of the shoulder. This exercise also develops strength in the forearms.', '["Fique em pé na frente de uma polia de altura média e segure ambas as extremidades do puxador corda. Afaste-se do equipamento até que seus braços fiquem completamente estendidos à sua frente. Seus pés devem ficar ligeiramente mais afastados do que a largura dos seus ombros, e os joelhos levemente flexionados.","Mantenha o tronco firme e flexione os cotovelos, passando da linha das costas e trazendo o puxador corda até aproximadamente a altura das orelhas. Aproxime e mantenha as escápulas unidas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada elevada na argola', 'TRAPS', '', NULL, NULL, 'forca', 'ROW', '', 'SHOULDERS, CHEST', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remo em local fechado', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Face pull com rotação externa', 'SHOULDERS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LATS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada invertida', 'TRAPS', 'Barra, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/INVERTED_ROW/heroImage_BBtOiO2.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_259-A3.mp4', 'forca', 'ROW', 'Intermediário', 'SHOULDERS, CHEST', 'The inverted row is a bodyweight exercise that increases upper body strength in the back, biceps, and forearms. This exercise also improves core stability. This exercise improves horizontal pulling strength, and is an effective starting point if you struggle to perform chin-ups or pull-ups.', '["Deite-se de costas debaixo de uma barra no aparelho de smith. Segure a barra com uma pegada pronada, com as mãos alinhadas com os ombros.","Puxe o tórax para cima contra a barra, enquanto contrai as escápulas uma contra a outra no topo. Abaixe o corpo lentamente de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada invertida com os pés na bola suíça', 'TRAPS', '', NULL, NULL, 'forca', 'ROW', '', 'SHOULDERS, CHEST, ABS', NULL, NULL);
