INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada invertida modificada', 'TRAPS', '', NULL, NULL, 'forca', 'ROW', '', 'SHOULDERS, CHEST', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada inclinada unilateral', 'LATS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ONE_ARM_BENT_OVER_ROW/heroImage_BBtOiH2.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_193-A1.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'The one-arm bent-over row is a multi-joint movement that targets the back, arms and core. By working each side of the body separately, this exercise improves muscle imbalances while increasing the challenge to the core.', '["Segure um haltere com uma mão e posicione-se em pé com um pé na frente do outro. Flexione os quadris e os joelhos e abaixe o tronco até que o mesmo esteja quase paralelo ao chão.  Deixe o haltere suspenso no comprimento do braço a partir do ombro.","Sem mover o tronco, puxe o haltere para a lateral do mesmo, mantendo o cotovelo fixo à lateral. Pause e contraia na parte superior do movimento. Baixe o haltere de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada alternada com pegada neutra com halteres', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com prancha', 'LATS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/RENEGADE_ROW/heroImage_BBtOhkp.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_197-A1.mp4', 'forca', 'ROW', 'Intermediário', 'CHEST, ABS', 'The renegade row is a multi-purpose, multi-joint exercise that increases strength in the back, shoulders, triceps, and biceps. This two-in-one exercise will also actively engage the core throughout the range of motion.', '["Posicione dois halteres no chão, alinhados aproximadamente com os ombros.  Coloque-se na posição superior do exercício de flexão de braços, com as mãos sobre os pesos.","Execute o movimento de remada, trazendo um peso para cima em direção à lateral do corpo enquanto se equilibra sobre os pés e sobre a outra mão. Espere por um momento no topo e retorne o peso lentamente à posição inicial para repetir com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada em uma perna com halter', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com pegada reversa em barra', 'LATS', 'Barra', 'https://connect.garmin.com/images/exercises/images/REVERSE_GRIP_BARBELL_ROW/heroImage_BBtO4Rz.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_110-A1.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'The reverse-grip barbell row builds strength in the back, shoulders, arms, and core. Using a reverse grip places more emphasis on the upper-back muscles.', '["Fique em pé com os pés alinhados à largura dos ombros. Segure a barra com uma pegada supinada e as mãos levemente mais abertas do que a largura dos ombros. Deixe a barra pendurada a partir dos ombros. Mantendo a coluna lombar naturalmente arqueada e os ombros para trás, curve os quadris e joelhos e abaixe o tronco até que fique quase paralelo ao chão.","Sem mover o tronco, puxe a barra para baixo até os abdominais superiores.  Mantenha os cotovelos fixos às laterais do corpo e contraia as escápulas uma contra a outra. Pause e depois retorne a barra lentamente à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada com cabo de corda', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'BICEPS, LOWER_BACK, SHOULDERS, CHEST', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada sentada na polia baixa', 'LATS', '', NULL, NULL, 'forca', 'ROW', '', 'CHEST, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada curvada com peso', 'LATS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_367-Cam1.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS', 'The one-arm bent-over row is a multi-joint movement that targets the back, arms and core. By working each side of the body separately, this exercise improves muscle imbalances while increasing the challenge to the core.', '["Fique de pé com os pés afastados na largura dos ombros e segure a mochila com ambas as mãos. Dobre o tronco a partir dos quadris e flexione ligeiramente os joelhos, até que o seu tronco esteja quase paralelo ao chão.","Puxe a mochila em direção ao seu tronco, mantendo os cotovelos próximos ao seu corpo. Pause brevemente no topo e, em seguida, abaixe a mochila de volta à posição inicial de maneira controlada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada sentada com halteres', 'SHOULDERS', '', NULL, NULL, 'forca', 'ROW', '', 'LATS, BICEPS', NULL, NULL);
