INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada unilateral e rotação com pegada neutra', 'LATS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/SINGLE_ARM_NEUTRAL_GRIP_DUMBBELL_ROW_AND_ROTATION/heroImage_BBtOhhn.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_200-A3.mp4', 'forca', 'ROW', 'Intermediário', 'BICEPS, LOWER_BACK, SHOULDERS, OBLIQUES', 'The single-arm neutral-grip dumbbell row and rotation improves upper body strength in the back, biceps, arms, and shoulders. The rotation at the top of the movement will actively engage the core, more specifically the obliques.', '["Posicione-se com as pernas alternadas e mantenha os joelhos levemente flexionados. Incline-se para a frente com as costas retas e segure um haltere em uma mão com o polegar voltado para cima.","Puxe o haltere em direção a sua lateral, girando o mesmo lado do tronco para cima. Faça uma pausa por um segundo no topo e então inverta a rotação, abaixando o peso e o levando à posição inicial."]');
