INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide com haltere alternado', 'SHOULDERS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_SHOULDER_PRESS/heroImage_BBtO7q0.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_170-A3.mp4', 'forca', 'SHOULDER_PRESS', 'Intermediário', 'TRICEPS, CHEST, TRAPS', 'The alternating dumbbell shoulder press increases muscular strength through the entire shoulder region. Performing the exercise in an alternating manner will create balance and stability on both sides of the body while actively engaging the core.', '["Fique em pé, mantenha os pés afastados e alinhados com os quadris. Segure um haltere em cada mão logo acima da altura dos ombros com as palmas das mãos voltadas para frente e os braços flexionados.","Eleve um haltere acima da cabeça sem mover o outro. Permaneça em posição ereta com o peito para cima e os ombros para trás. Retorne à posição inicial para realizar o movimento no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento de saco de areia até o ombro', 'GLUTES', '', NULL, NULL, 'forca', 'SANDBAG', '', 'ABS, BICEPS, HAMSTRINGS, LOWER_BACK, SHOULDERS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento Arnold', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'TRICEPS, CHEST, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento frontal com barra para elevação', 'QUADS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_FRONT_SQUAT_TO_PUSH_PRESS/heroImage_BBtOiLc.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_100-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Avançado', 'ABS, CALVES, CHEST, HAMSTRINGS, HIPS, LOWER_BACK, TRAPS, TRICEPS', 'The barbell front squat to push press is a full body strength exercise that targets the shoulders and legs. This exercise also greatly increases core strength and stability.', '["Segure uma barra na altura do ombro, com uma pronação ligeiramente maior que a largura dos ombros. Gire seus cotovelos para baixo da barra, de forma que as palmas das mãos voltem-se para cima e a barra fique no topo dos ombros. Segure a barra, dê um passo para trás e mantenha seus pés ligeiramente mais afastados do que a largura dos ombros.","Mantenha o tronco contraído e o tórax ereto, agache bem para equilibrar o peso do corpo com a planta do pé. Uma vez que você atingir a parte mais baixa, pause, e então suba rapidamente de volta à posição inicial.","À medida que fica em pé, eleve repentinamente a barra acima da cabeça, usando um impulso mecânico para ajudar a estender totalmente os braços Segure a barra com firmeza e depois abaixe o peso lentamente e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com desenvolvimento com barra', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'HIPS, CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento pela frente com barra', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'CHEST, TRICEPS, TRAPS', NULL, NULL);
