INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide alternado com haltere e rotação', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'TRICEPS, CHEST, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento frontal com halteres', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide com haltere', 'SHOULDERS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_PUSH_PRESS/heroImage_BBtOcz2.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_185-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Avançado', 'HIPS, CHEST, TRICEPS, TRAPS', 'The dumbbell push press is a multi-joint exercise that increases strength and power throughout the entire body, with an emphasis on the shoulders and triceps. The use of dumbbells improves balance and stability on each side.', '["Em pé, com os pés afastados e alinhados com a largura dos quadris, segure um par de halteres em frente ao tórax, mantenha os cotovelos apontados para baixo e as palmas das mãos voltadas para fora. Leve seus joelhos para a frente e agache ligeiramente. Mantenha seus calcanhares no chão e os ombros para trás.","Levante-se repentinamente para empurrar os halteres acima da cabeça, travando seus braços e seu tronco. Abaixe lentamente os pesos, levando-os à posição inicial."]');
