INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Zercher', 'GLUTES', '', NULL, NULL, 'forca', 'SANDBAG', '', 'BICEPS, CHEST, FOREARM, HAMSTRINGS, ABS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de ombros com halteres', 'SHOULDERS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_SHOULDER_PRESS/heroImage_BBtOiFF.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_188-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Intermediário', 'CHEST, TRICEPS, TRAPS', 'The dumbbell shoulder press is an effective exercise for building strength and stability throughout the shoulder complex, while also targeting the triceps and upper back.', '["Pegue um par de halteres e segure-os na altura dos ombros com ambos os braços flexionados e as palmas voltadas para frente.","Fique em pé e com postura reta,  mantenha os pés alinhados à largura dos quadris.  Segure os halteres o mais firme possível e eleve-os acima da cabeça até que os cotovelos fiquem completamente travados. Faça uma pausa e abaixe-o lentamente e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de ombros invertido no solo', 'CHEST', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'TRICEPS', NULL, NULL);
