INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento militar', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento ajoelhado no landmine', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'ABS, CHEST, OBLIQUES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento com barra', 'SHOULDERS', 'Barra', 'https://connect.garmin.com/images/exercises/images/OVERHEAD_BARBELL_PRESS/heroImage_BBtOhdz.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_314-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Iniciante', 'CHEST, TRICEPS, TRAPS', 'O supino com barra acima da cabeça aumenta a força da parte superior do corpo, especificamente nos ombros e tríceps. O movimento também melhora a estabilidade do core.', '["Pegue uma barra usando uma pegada dorsal com as mãos um pouco mais afastadas do que a largura dos ombros. Fique em pé com os pés afastados na largura do quadril e a barra abaixo do queixo, mas acima do peito com as palmas das mãos voltadas para o teto.","Pressione a barra acima da cabeça até que os cotovelos estejam completamente travados antes de retornar lentamente à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide no chão com um braço', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'HIPS, CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pressão no ombro sentado com barra', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Press com peso', 'TRICEPS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_374-Cam1.mp4', 'forca', 'SHOULDER_PRESS', 'Iniciante', '', 'O supino com barra acima da cabeça aumenta a força da parte superior do corpo, especificamente nos ombros e tríceps. O movimento também melhora a estabilidade do core.', '["Pegue a mochila nas laterais com as duas mãos. Fique de pé com os pés afastados aproximadamente na largura dos quadris e a mochila na altura do peito, com as palmas das mãos voltadas para dentro, em direção à mochila.","Pressione a mochila acima da cabeça até que seus cotovelos estejam completamente travados antes de retornar lentamente à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento com halteres acima da cabeça', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide com haltere sentado', 'SHOULDERS', '', NULL, NULL, 'forca', 'SHOULDER_PRESS', '', 'CHEST, TRICEPS, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de deltóide com haltere em um só braço', 'SHOULDERS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/SINGLE_ARM_DUMBBELL_SHOULDER_PRESS/heroImage_BBtOcvA.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_198-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Intermediário', 'CHEST, TRICEPS, TRAPS', 'The single-arm dumbbell shoulder press is a unilateral exercise that increases shoulder strength, stability, and symmetry. Performing the exercise with one arm at a time will actively engage the core throughout the range of motion.', '["Segure um haltere em uma mão e o leve até a altura dos ombros com a palma da mão voltada para o tórax e o braço flexionado. Em pé, mantenha o abdômen contraído e posicione seus pés alinhados com os ombros.","Segure o haltere o mais firme possível e o eleve acima da cabeça até que o braço esteja quase completamente estendido e encaixado. Faça uma pausa e abaixe-o lentamente e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão e step-up unilateral', 'QUADS', 'Caixa, Halteres', 'https://connect.garmin.com/images/exercises/images/SINGLE_ARM_STEP_UP_AND_PRESS/heroImage_BBtOaaD.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_267-A4.mp4', 'forca', 'SHOULDER_PRESS', 'Intermediário', 'HAMSTRINGS, CHEST, TRICEPS, TRAPS, HIPS', 'The single-arm step-up and press builds strength in the lower-body and shoulder area. Isolating one arm at a time also improves balance and stability.', '["Segure um haltere com uma das mãos na altura no ombro, com a palma voltada para dentro. Fique em pé em frente a um banco ou step e posicione um pé firmemente sobre ele.","Tomando impulso com a ponta do pé da frente, suba no step, endireitando as duas pernas. Quando chegar ao topo, eleve o haltere acima da cabeça. Abaixe o haltere de volta ao ombro e abaixe-o até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação acima da cabeça "Smith Machine"', 'SHOULDERS', 'Squat de agachamento, Banco', 'https://connect.garmin.com/images/exercises/images/SMITH_MACHINE_OVERHEAD_PRESS/heroImage_BBtOhfl.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_260-A3.mp4', 'forca', 'SHOULDER_PRESS', 'Iniciante', 'CHEST, TRICEPS, TRAPS', 'The Smith machine overhead press helps increase strength and muscle growth throughout the entire shoulder region. The range of motion of the Smith machine assists beginners with learning the movement pattern.', '["Sente-se em um banco com suporte para manter as costas eretas bem abaixo da barra de uma Smith machine. Agarre a barra com uma pegada pronada, levemente mais aberta que a largura dos ombros, apenas um pouco acima da altura dos ombros.","Segure a barra o mais firme possível e eleve-a acima da cabeça até que os braços estejam completamente estendidos e travados. Faça uma pausa no alto e lentamente abaixe de volta à posição original."]');
