INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Subida de ombro com barra', 'TRAPS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_SHRUG/heroImage_BBtOf2W.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_315-A4.mp4', 'forca', 'SHRUG', 'Avançado', 'SHOULDERS', 'O encolhimento de ombros com barra aumenta a força e o crescimento muscular na parte superior das costas e ombros, enquanto melhora a força nos punhos.', '["Em pé, com os pés afastados na largura dos ombros, coloque uma barra na frente das coxas, as mãos na largura dos ombros, as palmas das mãos voltadas para o corpo e os braços totalmente estendidos.","Com os braços retos, encolha os ombros o mais alto que puder. Faça uma pausa e, em seguida, abaixe até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remada em pé com barra', 'SHOULDERS', 'Barra', 'https://connect.garmin.com/images/exercises/images/BARBELL_UPRIGHT_ROW/heroImage_BBtO7rP.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_111-A3.mp4', 'forca', 'SHRUG', 'Avançado', 'BICEPS, FOREARM', 'The barbell upright row is an advanced upper body exercise that targets most of the back and shoulder region.', '["Segure uma barra com anilhas com uma pegada pronada e segure firmemente o peso na frente das coxas com as palmas das mãos voltadas para o corpo. Mantenha os pesos o mais próximo possível do corpo, puxe a barra em direção ao tórax.","Os cotovelos devem ser mantidos travados durante o movimento. Quando a barra estiver no nível do tórax (e não do queixo), faça uma pausa por um ou dois segundos e então abaixe a barra de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Encolhimento de ombros por trás', 'TRAPS', '', NULL, NULL, 'forca', 'SHRUG', '', 'SHOULDERS', NULL, NULL);
