INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com levantamento', 'ABS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/GET_UP_SIT_UP/heroImage_BBtOlb7.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_191-A1.mp4', 'forca', 'SIT_UP', 'Intermediário', 'GLUTES, OBLIQUES, LOWER_BACK, HIPS', 'The get up sit-up builds strength and stability throughout the core and upper body. The exercise also improves strength in supporting areas such as the hip flexors, hamstrings, and glutes.', '["Deite-se no chão e segure um haltere em uma mão diretamente acima de seu tórax com o braço estendido. Flexione uma das pernas e apoie o pé no chão.","Iniciando o movimento no abdômen, eleve o tronco mantendo o haltere acima da cabeça. Faça um pausa e então retorne ao chão."]');
