INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominais', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/SIT_UP/heroImage_BBtOaeE.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_037-A1.mp4', 'forca', 'SIT_UP', 'Iniciante', 'HIPS', 'The sit-up is a basic bodyweight exercise that strengthens the entire core region, more specifically the lower abdominals. The exercise also improves lower back strength.', '["Deite-se de costas com os joelhos flexionados e os pés apoiados no chão. Posicione as mãos atrás das orelhas com os cotovelos apontados para fora.","Sem levantar os pés do chão, curve o tronco para cima, em direção às coxas. Mantenha a cabeça alinhada com o corpo. De maneira controlada, reverta o movimento e encoste o tronco no chão."]');
