INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal em "V"', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/V_UP/heroImage_BBtOlc9.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_040-B1.mp4', 'forca', 'SIT_UP', 'Avançado', 'HIPS, QUADS', 'The V-up is an advanced core exercise that targets the abs, while effectively working your internal and external obliques.', '["Deite-se no chão com as pernas retas e os pés juntos. Leve ambos os braços para trás e posicione-os ao lado das orelhas.","Simultaneamente, levante as pernas e o tronco do chão. Leve os braços para frente em direção aos tornozelos, usando os quadris para se equilibrar. Inverta o movimento e retorne à posição inicial."]');
