INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino com trenó de carga', 'CHEST', '', NULL, NULL, 'forca', 'SLED', '', 'ABS, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento costas com barra', 'QUADS', 'Barra, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/BACK_SQUAT_WITH_BODY_BAR/heroImage_BBtO4Vp.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_120-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS', 'The back squat is a basic barbell strength exercise for the lower body with an emphasis on the quads, hamstrings, and glutes. The exercise also strengthens the entire core.', '["Em pé com os pés afastados na largura dos ombros e apontados ligeiramente para fora, coloque uma barra com anilhas na parte de trás dos ombros, segurando-a com uma pegada pronada.","Abaixe-se para uma posição de agachamento, empurrando os quadris para trás e flexionando os joelhos. Faça uma pausa na parte inferior do agachamento e, em seguida, mova os quadris para cima, de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento costas', 'QUADS', '', NULL, NULL, 'forca,mobilidade', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com barra nas costas', 'QUADS', 'Barra, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/BARBELL_BACK_SQUAT/heroImage_BBtOkZ1.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_094-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS', 'The back squat is a basic barbell strength exercise for the lower body with an emphasis on the quads, hamstrings, and glutes. The exercise also strengthens the entire core. The squat allows for heavy weights and overloads your entire body, which has been shown to increase testosterone and growth hormone, making it one of the best mass building exercises.', '["Em pé com os pés afastados na largura dos ombros e apontados ligeiramente para fora, coloque uma barra com anilhas na parte de trás dos ombros, segurando-a com uma pegada pronada.","Abaixe-se para uma posição de agachamento, empurrando os quadris para trás e flexionando os joelhos. Faça uma pausa na parte inferior do agachamento e, em seguida, mova os quadris para cima, de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com barra e caixa', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento frontal com barra', 'GLUTES', 'Barra, Squat de agachamento', 'https://connect.garmin.com/images/exercises/images/BARBELL_FRONT_SQUAT/heroImage_BBtOhnE.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_099-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'ABS, HAMSTRINGS', 'The barbell front squat is a multi-joint exercise that strengthens the legs. The upright position of the torso during the exercise also builds strength in the core. By loading the weight on the front of your body instead of your back, you''re able to activate more muscle in your quads using less weight. This form of the squat helps if you have limited range of motion in your shoulders or a previous shoulder injury.', '["Posicione-se em pé com os pés afastados na largura dos ombros e apontados para fora. Apoie a barra sobre o tórax. Utilize uma pegada pronada para segurar a barra firmemente com os dedos. O tríceps deve permanecer paralelo ao chão para sustentar o peso da barra.","Inspire e abaixe os quadris lentamente até que as coxas estejam paralelas ao chão, mantendo o peso imóvel. Faça uma pausa na parte inferior do agachamento e, depois, mova os quadris rapidamente de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Hack', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
