INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Step com barra', 'QUADS', 'Barra, Caixa', 'https://connect.garmin.com/images/exercises/images/BARBELL_STEP_UP/heroImage_BBtOhc4.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_105-A4.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS, CALVES', 'The barbell step-up is a multi-joint exercise that focuses on improving single-leg strength. The barbell step-up also improves balance and core strength.', '["Em pé, com os pés afastados na largura dos ombros , coloque uma barra com anilhas na parte de trás dos ombros, segurando-a com a mão pronada. Inspire, mantenha o tórax firme e coloque um pé na frente, sobre um caixote de 15 a 30 cm. Essa é a sua posição inicial.","Expire enquanto coloca seu pé sobre a caixa e move seus quadris para cima, levando seu pé traseiro de encontro ao dianteiro sobre a caixa.  Pause e volte à posição inicial."]');
