INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento frontal com halteres', 'GLUTES', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_FRONT_SQUAT/heroImage_BBtOcBd.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_182-A3.mp4', 'forca', 'SQUAT', 'Iniciante', 'ABS, HAMSTRINGS', 'The dumbbell front squat is a multi-joint, lower body strength exercise that targets the quads, hamstrings and glutes. The dumbbell front squat will also improve balance and stability throughout the core and on both sides of the body.', '["Fique em pé, mantenha os pés afastados e alinhados com os ombros e os dedos dos pés voltados para fora entre 10 e 30 graus. Eleve um par de halteres em direção aos ombros, apoiando uma das extremidades dos halteres sobre eles.","Mantendo o corpo reto e a parte superior dos braços paralelas ao chão, mantenha seu abdômen firme, abaixe-se até que as dobras dos quadris estejam abaixo do nível do joelho, empurrando os quadris para trás e flexionando os joelhos. Faça uma pausa na parte inferior do movimento e depois leve seus calcanhares até o chão, retornando à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Subida cruzada no step com haltere', 'QUADS', 'Caixa, Halteres', 'https://connect.garmin.com/images/exercises/images/CROSSOVER_DUMBBELL_STEP_UP/heroImage_BBtOcwm.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_266-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS, ABS', 'The crossover dumbbell step-up is a dynamic exercise that focuses on strengthening your glutes, quads, and hamstrings. The movement will also improve hip mobility and flexibility. The crossover element allows you to work your muscles from a different angle, which allows for more growth and can help with injury prevention.', '["Segure um haltere em cada mão com os braços suspensos ao lado do corpo. Posicione-se em pé, com um dos lados do corpo ao lado de um caixote. Esta é a sua posição inicial Coloque o pé do lado externo sobre o caixote, cruzando-o em frente à outra perna.","Mantenha o pé firme no caixote, impulsione o corpo até que ambas as pernas fiquem retas e fique em pé sobre o mesmo. Desça de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo com halteres', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_SPLIT_SQUAT/heroImage_BBtOkZG.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_189-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS', 'The dumbbell split squat is a multi-joint strength exercise that targets the legs with an emphasis on the glutes and hamstrings. This move also improves hip mobility and core stability. Utilizing dumbbells will ensure muscular balance on both sides of the body.', '["Segure um par de halteres nas laterais com as palmas voltadas uma para a outra. Fique em pé, com uma perna à frente da outra, com o pé da frente a uma distância de 70 a 140 cm em relação ao pé de trás. Apoie-se na ponta do pé de trás.  Esta é a sua posição inicial","Abaixe os quadris até que a coxa da frente esteja pelo menos paralela ao chão. Tome impulso com o calcanhar da frente e estenda os quadris e os joelhos para retornar à posição inicial e repita o exercício do lado oposto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com haltere suspenso em um braço', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS, ABS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com halteres', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_SQUAT/heroImage_BBtOl2X.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_190-A3.mp4', 'forca', 'SQUAT', 'Iniciante', 'HAMSTRINGS', 'The dumbbell squat is a compound exercise that strengthens the lower body including the quads, hips and hamstrings. The exercise also improves stability throughout the core.', '["Pegue um par de halteres, mantenha os braços totalmente estendidos nas laterais do corpo e as palmas das mãos voltadas uma para a outra. Posicione seus pés alinhados com os ombros, com as pontas dos pés apontadas para fora.","Contraia o abdômen, empurre os quadris para trás e flexione os joelhos, abaixando o corpo em posição de agachamento, mantendo as mãos próximas às laterais do corpo. Pause na parte inferior do movimento e depois volte à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Clean com halter', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'CALVES, SHOULDERS, TRAPS, BICEPS, FOREARM, LOWER_BACK', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento snatch com halteres', 'GLUTES', '', NULL, NULL, 'forca', 'SQUAT', '', 'ABS, BICEPS, HAMSTRINGS, LOWER_BACK, TRAPS, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Step-up com halteres', 'QUADS', 'Banco, Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_STEP_UP/heroImage_BBtOiJm.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_269-A3.mp4', 'forca', 'SQUAT', 'Iniciante', 'HAMSTRINGS, CALVES, HIPS', 'The dumbbell step-up is a multi-joint, single-sided strength movement for the lower body, emphasizing the quads, hamstrings, and glutes. The exercise also improves core strength and stability.', '["Segure um haltere de cada lado do corpo e coloque um pé sobre um banco ou caixa, com o joelho dobrado a 90 graus. Mantendo a outra perna reta e firme no chão, empurre seus ombros para trás e o tórax para fora.","Empurre com o pé da frente para subir na plataforma, sua perna  de trás deverá ficar suspensa no ar. Empurre os quadris para abaixar sua perna de apoio de volta ao chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com desenvolvimento com halteres', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'ABS, CALVES, CHEST, HAMSTRINGS, HIPS, LOWER_BACK, TRAPS, TRICEPS, FOREARM', NULL, NULL);
