INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento unilateral em forma de 4', 'GLUTES', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Goblet', 'GLUTES', 'Halteres', 'https://connect.garmin.com/images/exercises/images/GOBLET_SQUAT/heroImage_BBtOf3h.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_192-A3.mp4', 'forca,mobilidade', 'SQUAT', 'Iniciante', 'ABS, HAMSTRINGS', 'O agachamento cálice é um exercício para a parte inferior do corpo que aumenta a força nas pernas. Devido à posição do peso, o exercício também fortalece os ombros e o core, melhorando a postura e a mobilidade do quadril.', '["Em pé, com os pés afastados na largura dos ombros, pegue a cabeça de um haltere com as duas mãos e segure-o verticalmente na frente do peito.","Mantendo as costas retas, agache-se até que a dobra do quadril caia abaixo do joelho e a parte superior das coxas fique paralela ao chão. Estenda os quadris e os joelhos para retornar à posição inicial."]');
