INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento do prisioneiro', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/PRISONER_SQUAT/heroImage_BBtOf60.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_023-A3.mp4', 'forca,mobilidade', 'SQUAT', 'Iniciante', 'HAMSTRINGS', 'The prisoner squat is a lower-body exercise with an emphasis on the quads, hamstrings, and glutes. The exercise also improves upper body mobility. By pulling your elbows back, the exercise helps improve upper back mobility and assists with correct posture.', '["Posicione-se com os pés alinhados com os ombros, com os dedos apontados ligeiramente para fora. Mantendo o tronco ereto, coloque as mãos atrás da cabeça, puxando seus ombros e cotovelos para trás.","Abaixe-se para uma posição de agachamento, empurrando os quadris para baixo e dobrando os joelhos até que os quadris fiquem abaixo do nível do joelho. Faça uma pausa na parte mais baixa do movimento e estenda os quadris e os joelhos para cima, voltando  à posição inicial com um forte impulso."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com barra de segurança', 'GLUTES', '', NULL, NULL, 'forca', 'SQUAT', '', 'ABS, HAMSTRINGS, LOWER_BACK, TRAPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com barra nas costas', 'QUADS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_366-Cam1.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS', 'The back squat is a basic barbell strength exercise for the lower body with an emphasis on the quads, hamstrings, and glutes. The exercise also strengthens the entire core. The squat allows for heavy weights and overloads your entire body, which has been shown to increase testosterone and growth hormone, making it one of the best mass building exercises.', '["Fique de pé com os pés afastados na largura dos ombros e coloque a mochila bem firme na parte superior das costas. Estique os dois braços na altura dos ombros ou acima da cabeça.","Desça em um agachamento empurrando os quadris para trás e os joelhos para fora, dobrando os joelhos e mantendo o peito ereto. Faça uma pausa embaixo e, em seguida, dê um impulso com os calcanhares para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com peso acima da cabeça', 'QUADS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_373-Cam1.mp4', 'forca', 'SQUAT', 'Avançado', 'HAMSTRINGS, ABS, TRICEPS', 'O agachamento com peso acima da cabeça melhora a força e a mobilidade tanto na parte superior quanto na parte inferior do corpo. Devido à posição da barra e ao padrão de movimento, a força do core é outro benefício do agachamento com barra acima da cabeça. Se você não consegue agachar com a barra acima da cabeça, um core fraco, pouca mobilidade dos ombros, dorsais fracos ou isquiotibiais fracos podem ser o motivo. Fortalecer essas áreas ajudará a melhorar seu agachamento com peso acima da cabeça.', '["Fique de pé com os pés afastados na largura dos ombros. Levante a mochila com as duas mãos, com os braços completamente estendidos, mantendo os bíceps próximos às orelhas e as mãos firmemente posicionadas nas laterais da mochila.","Contraia o core e desça em um agachamento, mantendo a mochila estável acima da cabeça e o tronco ereto. Faça uma pausa embaixo e, em seguida, dê um impulso com os calcanhares para retornar à posição em pé."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com barra frontal', 'QUADS', 'Peso da mochila', 'https://connect.garmin.com/images/exercises/images/TBD', 'https://connectvideo.garmin.com/msn-workout/Strength/S_370-Cam1.mp4', 'forca', 'SQUAT', 'Intermediário', 'HAMSTRINGS, ABS', 'O agachamento frontal com barra é um exercício de múltiplas articulações que fortalece as pernas. A posição ereta do tronco durante o exercício também aumenta a força no core. Ao carregar o peso à frente de seu corpo em vez de às suas costas, você consegue ativar mais músculos em seus quadris usando menos peso. Esta forma de agachamento é útil se você tiver uma amplitude limitada de movimento nos ombros ou se tiver sofrido uma lesão no ombro anteriormente.', '["Fique de pé com os pés afastados na largura dos ombros e segure a mochila próxima ao peito com os dois braços.","Abaixe-se em um agachamento dobrando os joelhos e os quadris, mantendo a mochila estável e o peito ereto. Faça uma pausa embaixo e, em seguida, empurre os calcanhares contra o chão para retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento unilateral do banco', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento unilateral no banco', 'QUADS', '', NULL, NULL, 'forca', 'SQUAT', '', 'HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento e chute lateral', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT_AND_SIDE_KICK/heroImage_BBtOiCr.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_032-A3.mp4', 'forca', 'SQUAT', 'Iniciante', 'HAMSTRINGS', 'The squat and side kick strengthens the lower body. The wide stance targets the inner thighs, while helping to increase flexibility and mobility throughout the hip region.', '["Posicione-se em pé com os pés mais afastados que a largura dos ombros e com a ponta dos pés ligeiramente viradas para fora, o suficiente para permitir que os joelhos fiquem na mesma direção que os dedos. Flexione os braços e posicione as mãos fechadas em punhos abaixo do queixo. Agache-se de que forma que os joelhos formem um ângulo de 90 graus, mantendo o tórax reto.","Contraia o tronco e, em seguida, dê um chute com uma perna enquanto mantém o equilíbrio com a outra. Retorne à posição inicial."]');
