INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Squat dentro e fora', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT_JUMPS_IN_N_OUT/heroImage_BBtOa9B.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_034-A3.mp4', 'forca', 'SQUAT', 'Intermediário', 'ADDUCTORS, HIPS, HAMSTRINGS', 'Squat jumps in ''n out increase lower body power and coordination. The movement targets the quads, hamstrings, glutes, and calves.', '["Posicione-se com os pés juntos, coloque as mãos na sua frente, sobre as coxas.","Dobre as pernas, pule e separe os pés enquanto estiver no ar.","Atinja o chão com os pés mais afastados do que a largura dos ombros e abaixe, agachando. Saia da posição de agachamento dando um salto e volte à posição inicial, mantendo os pés juntos no momento em que tocarem novamente o chão."]');
