INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento Goblet com postura ampla', 'QUADS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/WIDE_STANCE_GOBLET_SQUAT/heroImage_BBtO4Vo.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_204-A3.mp4', 'forca', 'SQUAT', 'Iniciante', 'HAMSTRINGS, ABS', 'The wide-stance goblet squat increases strength throughout the lower body and legs. The wide stance targets the inner thighs while also improving hip mobility and core stability.', '["Segure um haltere posicionado verticalmente em frente ao tórax, com ambas as mãos formando a figura de uma taça, segurando uma extremidade do haltere. Seus pés devem estar afastados duas vezes a largura dos quadris.","Empurre os quadris para trás e baixe o corpo em um agachamento até que as coxas estejam pelo menos paralelas ao chão. Mantenha as costas retas, o queixo para a frente e o peso firme no peito. Faça uma pausa e então volte à posição inicial."]');
