INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha invertida com fita de suspensão', 'GLUTES', '', NULL, NULL, 'forca', 'SUSPENSION', '', 'ABS, HAMSTRINGS, OBLIQUES', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca para isquiotibiais com fita de suspensão', 'HAMSTRINGS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_070-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_070-A3.mp4', 'forca,yoga,pilates', 'MOVE', 'Iniciante', 'ADDUCTORS, GLUTES', '', '["Comece de pé com os braços relaxados ao lado do corpo.","Inspire enquanto leva os braços acima da cabeça, emoldurando o rosto.","Ao expirar, puxe o umbigo em direção à coluna e mergulhe sobre as pernas com as costas retas.","Posicione as mãos no chão ligeiramente na frente ou ao lado dos pés. Pressione os quatro cantos dos pés contra o chão e eleve os ossos ísquios em direção ao teto. Relaxe a cabeça e o pescoço. Respire profundamente pelo menos três vezes nessa posição."]');
