INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Burpee com barra', 'QUADS', '', NULL, NULL, 'forca', 'TOTAL_BODY', '', 'TRAPS, BICEPS, FOREARM, LOWER_BACK, TRICEPS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Burpee', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/BURPEE/heroImage_BBtOfh6.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_013-A3.mp4', 'forca', 'TOTAL_BODY', 'Intermediário', 'SHOULDERS, TRICEPS, HAMSTRINGS', 'The burpee is a dynamic full body strengthening and conditioning exercise that targets your quadriceps, glutes and hamstrings.', '["Fique em pé com os pés afastados na largura dos ombros e com as mãos nas laterais. Abaixe rapidamente os quadris e coloque as mãos na frente dos pés. Depois chute os pés de volta para a posição de flexão.","Faça uma flexão.","Salte para trás sob os quadris, expanda o corpo em direção ao teto enquanto pula e toca as mãos atrás da cabeça.","Continue em um ritmo constante para o número prescrito de repetições."]');
