INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com prancha (subida e descida)', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT_THRUSTS/heroImage_BBtOf8v.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_042-A3.mp4', 'forca', 'TOTAL_BODY', 'Intermediário', 'SHOULDERS, TRICEPS, HAMSTRINGS', 'The squat thrust builds strength and explosiveness in the lower body with an emphasis on the quads, glutes, and hamstrings. The squat thrust will also improve hip mobility and cardiovascular endurance. The exercise is commonly used in metabolic workouts to improve conditioning and fat loss. It requires less upper body strength than a burpee, which includes a push-up in the bottom position.', '["Fique em pé e em posição ereta, pés alinhados com os ombros e os braços soltos ao lado do corpo.","Abaixe-se e coloque as mãos no chão antes de levar as pernas  para trás em posição de flexão.","Rapidamente, traga as pernas à frente para posição de um agachamento e salte de volta para a posição inicial."]');
