INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps deitado alternado com halteres', 'TRICEPS', 'Halteres, Banco', 'https://connect.garmin.com/images/exercises/images/ALTERNATING_DUMBBELL_LYING_TRICEPS_EXTENSION/heroImage_BBtOa9S.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_167-A2.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', '', 'The alternating dumbbell triceps extension is an isolating single-joint exercise used to increase size and strength throughout the triceps.', '["Deite de costas em um banco com um  haltere em cada mão e braços totalmente estendidos acima da cabeça. Mantendo um haltere parado, abaixe o outro flexionando o cotovelo até um  pouco acima do ombro.","Faça uma pausa e, em seguida, estenda  o braço para a posição de inicial, contraindo o tríceps."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tríceps na barra paralela (dips)', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'CHEST, SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Repulsão entre dois bancos', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Cabo tríceps kick-back', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Coice ou kickback com halteres', 'TRICEPS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_KICKBACK/heroImage_BBtOiIN.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_184-A1.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', '', 'This is a single-joint isolating exercise that targets the back of the upper arm while developing stability throughout the hand and wrist region.', '["Ajoelhe-se sobre um lado de um banco para supino, posicionando um joelho e uma mão sobre o mesmo. Posicione a perna que está no chão ligeiramente para trás e para o lado, com o pé firmemente apoiado no chão. O tronco deverá ficar paralelo ao chão. Pegue um haltere com a mão livre com uma pronação e posicione o cotovelo à lateral do corpo de forma que a parte superior do braço fique paralela ao chão.","Mantendo a parte superior do braço imóvel, estenda o braço para trás contraindo o tríceps. Pause por um momento no topo e retorne para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão do tríceps acima da cabeça com cabo', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps deitado com polia baixa', 'TRICEPS', 'Aparelho de cabo, Puxador, Banco', 'https://connect.garmin.com/images/exercises/images/CABLE_LYING_TRICEPS_EXTENSION/heroImage_BBtOf9U.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_143-A4.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', '', 'The cable lying triceps extension is an isolation exercise that strengthens the triceps.', '["Posicione um banco de exercício em frente a uma polia baixa equipada com um puxador reto. Deite-se no banco com a cabeça próxima ao aparelho. Segure a barra com as palmas das mãos voltadas para fora. Estenda os braços totalmente para que eles formem um ângulo de 90 graus com o tronco.","Flexione os cotovelos para baixar o peso enquanto mantém a parte superior do braço fixa. A barra voltará para a posição de repouso, logo acima da testa. Faça uma pausa por um momento e, em seguida,  flexione os tríceps retornando o peso para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento com prancha e com peso (Subida e descida)', 'ABS', '', NULL, NULL, 'forca', 'TOTAL_BODY', '', 'SHOULDERS, TRICEPS, HAMSTRINGS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps deitado com halteres', 'TRICEPS', 'Halteres, Banco', 'https://connect.garmin.com/images/exercises/images/DUMBBELL_LYING_TRICEPS_EXTENSION/heroImage_BBtOf1K.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_163-A2.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', '', 'Dumbbell lying triceps extensions increase strength in the triceps. Performing the exercise with dumbbells will achieve muscular balance on both sides of the body.', '["Deite-se sobre um banco com um haltere em cada mão e com os braços estendidos sobre o peito.","Flexione os cotovelos e abaixe os halteres, até que estes fiquem um pouco acima dos ombros.  Não  mova a parte superior do braço. Pause e, em seguida, contraia o bíceps e estenda os halteres de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Paralela inclinada', 'CHEST', 'Estação de mergulho', 'https://connect.garmin.com/images/exercises/images/INCLINE_DIP/heroImage_BBtO7vG.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_123-A4.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', 'SHOULDERS, TRICEPS', 'The incline dip is a variation of the body-weight dip that strengthens the chest, shoulders, and triceps with less strain placed on the shoulder joints.', '["Segure os apoios da barra paralela e se levante até que seus braços fiquem travados e seu corpo suba a e desça em linha reta. Flexione os joelhos ligeiramente.","Flexione os cotovelos e se abaixe até que a parte superior dos seus braços fiquem paralelos ao chão. Mantenha o tronco inclinado até que o tórax fique quase paralelo ao chão.","Use o tórax, ombros e braços para se levantar e assuma a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps acima da cabeça com barra EZ', 'TRICEPS', 'Puxador', 'https://connect.garmin.com/images/exercises/images/EZ_BAR_OVERHEAD_TRICEPS_EXTENSION/heroImage_BBtOfac.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_091-A3.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', '', 'The EZ-Bar overhead triceps extensions increase strength in the triceps while building stability in the shoulders. The EZ-Bar provides favorable hand positioning for easing strain on the wrists and elbows. It also allows for a greater range of motion on the lower portion, which stretches the triceps and allows for more muscle growth.', '["Fique em pé e mantenha os pés afastados e alinhados com os ombros. Com os joelhos semiflexionados, segure uma barra EZ com peso, usando uma pegada pronada média.   Levante a barra diretamente acima da cabeça com os braços totalmente estendidos e os tríceps contraídos. Esta é a sua posição inicial","Contraia o abdômen e flexione os cotovelos para baixar a barra atrás de sua cabeça até que o antebraço tenha passado de um ângulo de 90 graus. Faça uma pausa e, em seguida, retorne os braços para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão do tríceps deitado com barra EZ inclinada', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pullover com extensão de halteres em posição deitada', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão do tríceps deitado com barra EZ', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'SHOULDERS', NULL, NULL);
