INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento com o tríceps reclinado', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'SHOULDERS', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino com pegada reversa', 'TRICEPS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/REVERSE_GRIP_PRESSDOWN/heroImage_BBtOf4X.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_134-A2.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', '', 'The reverse-grip pressdown is a single-joint exercise that targets your triceps while strengthening your upper back and rear shoulder muscles.', '["De frente para um aparelho de cabo ajustável, segure uma barra reta na posição alta com uma pegada invertida. Segurando a barra, posicione os cotovelos ao lado do corpo, mantendo os antebraços paralelos ao chão.","Estenda os antebraços para baixo, contraindo o tríceps.  Faça uma pausa, depois levante os antebraços de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tríceps na polia alta com pegada invertida', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tríceps na polia alta com corda', 'TRICEPS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/ROPE_PRESSDOWN/heroImage_BBtOiGN.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_135-B4.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', 'FOREARM', 'The rope pressdown is a single-joint isolation exercise that builds strength and muscular endurance through the triceps muscle.', '["De frente para um aparelho de cabo ajustável, segure a corda na posição alta, com os polegares para cima. Posicione os cotovelos nas laterais do corpo para que os antebraços fiquem paralelos ao chão.","Estenda os antebraços para baixo enquanto torce a corda para dentro a fim de que as juntas dos dedos fiquem voltadas para o chão quando os braços estiverem completamente estendidos. Faça uma pausa e retorne a barra até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps com barra sentado', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão unilateral com haltere sobre a cabeça sentado', 'TRICEPS', 'Halteres, Banco', 'https://connect.garmin.com/images/exercises/images/SEATED_SINGLE_ARM_OVERHEAD_DUMBBELL_EXTENSION/heroImage_BBtOf2q.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_166-A3.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', '', 'The seated single-arm overhead dumbbell extension is an isolation exercise that strengthens the triceps. This exercise also improves shoulder stability and mobility. The seated, overhead position ensures maximum isolation on the target area.', '["Sente-se em um banco segurando um haltere em uma mão. Estenda seus braços completamente e eleve o haltere para cima da cabeça. Mantenha a outra mão sobre a sua coxa.","Flexione os cotovelos para baixar o haltere, sem mover a parte superior do braço. Estenda bem o tríceps e pare pouco antes do haltere encostar no pescoço. Faça uma pausa, em seguida, retorne à posição inicial."]');
