INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps em posição estática', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mergulho com uma perna', 'TRICEPS', '', 'https://connect.garmin.com/images/exercises/images/SINGLE_LEG_DIP/heroImage_BBtO7F5.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_035-A1.mp4', 'forca', 'TRICEPS_EXTENSION', 'Intermediário', 'ABS, SHOULDERS, QUADS, HIPS', 'The single-leg dip is a more difficult variation to the standard dip. Using only one leg for support increases the resistance placed on the upper body during the movement. The movement specifically targets the chest, shoulders and triceps.', '["Sente-se no chão com os joelhos flexionados e os pés apoiados no chão. Posicione as mãos no chão atrás de você. Eleve os quadris e apoie-se sobre suas mãos e pés. Em seguida, levante uma perna do chão.","Flexione os cotovelos e abaixe o corpo em direção ao chão. Toque o chão com seus glúteos e então volte para cima, alinhando os braços. Retorne à posição inicial e alterne as pernas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mergulho suspenso', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'CHEST, SHOULDERS', NULL, NULL);
