INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Desenvolvimento de tríceps', 'TRICEPS', '', 'https://connect.garmin.com/images/exercises/images/TRICEPS_PRESS/heroImage_BBtO58Z.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_109-B1.mp4', 'forca,yoga,pilates', 'TRICEPS_EXTENSION', 'Intermediário', '', 'This exercise is designed to strengthen the triceps and open the chest.', '["Sente-se no tapete com as pernas estendidas à sua frente, mãos apoiadas no tapete atrás de você, dedos voltados para dentro.","Pressione as mãos para levantar os quadris do tapete, formando uma linha reta dos ombros aos dedos dos pés.","Dobre os cotovelos.","Em seguida, endireite os braços.","Abaixe os quadris até o tapete."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de tríceps no chão', 'TRICEPS', 'Puxador, Anilhas', 'https://connect.garmin.com/images/exercises/images/TRICEPS_EXTENSION_ON_FLOOR/heroImage_BBtO4Yu.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_095-A2.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', '', 'This exercise increases strength and muscle growth in the triceps. Positioning yourself on the floor allows for increased stability throughout the movement.', '["Deite-se de costas no chão com os joelhos flexionados e os pés firmemente apoiados no chão. Estenda seus braços para trás da cabeça e segure a barra com uma pegada pronada, com as mãos aproximadas. Levante a barra, estendendo os braços e posicionando a barra diretamente acima do tórax.","Mantendo a parte superior dos braços na mesma posição, abaixe a barra atrás da cabeça, em direção ao chão. Faça uma pausa e abaixe de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Supino para tríceps', 'TRICEPS', 'Aparelho de cabo, Puxador', 'https://connect.garmin.com/images/exercises/images/TRICEPS_PRESSDOWN/heroImage_BBtOcA5.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_135-B4.mp4', 'forca', 'TRICEPS_EXTENSION', 'Iniciante', '', 'Triceps pressdown is an isolation exercise that increases the strength and size of the triceps while also engaging the front of the shoulders.', '["Com o puxador em V na posição alta, fique de frente para o aparelho de cabo ajustável e segure-o, mantendo as mãos alinhadas com os ombros, com uma pegada pronada. Leve os cotovelos para as laterais do corpo para que os antebraços fiquem paralelos ao chão.","Estenda os antebraços para baixo contraindo o tríceps, gire levemente a barra, para as juntas dos dedos fiquem voltadas para o chão. Quando os braços estiverem completamente estendidos, faça uma pausa e retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mergulho no banco com peso', 'TRICEPS', '', NULL, NULL, 'forca', 'TRICEPS_EXTENSION', '', 'SHOULDERS', NULL, NULL);
