INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento para isquiotibiais em pé', '', 'Banco', 'https://connect.garmin.com/images/exercises/images/STANDING_HAMSTRING_STRETCH/heroImage_BBtOfcC.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_305-A4.mp4', 'aquecimento,mobilidade', 'WARM_UP', 'Iniciante', '', 'Esse alongamento aumenta a flexibilidade e a mobilidade nas regiões dos isquiotibiais e do quadril.', '["Fique ao lado de um banco de exercícios. Coloque uma perna no banco. Fique em pé e mova os ombros para baixo.","Incline levemente a perna esticada e curve-se na altura da cintura. Depois de sentir um alongamento atrás da coxa levantada, pare e mantenha essa posição pelo tempo recomendado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento dos ombros e peito na parede', 'CHEST', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotações com o pescoço', '', '', 'https://connect.garmin.com/images/exercises/images/NECK_ROTATIONS/heroImage_BBtO4WF.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_304-A4.mp4', 'aquecimento,mobilidade', 'WARM_UP', 'Iniciante', '', 'As rotações do pescoço são um exercício de pré-habilitação que aquece o pescoço e a parte superior dos ombros.', '["Fique em pé com os braços soltos ao lado do corpo e a cabeça inclinada para um lado.","Gire suavemente o pescoço em movimento de círculo em uma única direção antes de retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotação do tornozelo', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Dorsiflexão de tornozelo com faixa', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotação interna de tornozelo', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento de bíceps', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_024_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_024_CamA.mp4', 'aquecimento,mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Fique com o corpo reto com os pés afastados na largura dos ombros. Coloque ambos os braços atrás das costas e entrelace os dedos com os nós dos dedos voltados para baixo.","Curve-se bem para a frente na altura da cintura, abaixando a sua cabeça em direção ao chão e deixando seus braços acima de você. Sinta o alongamento ao longo de seus braços e bíceps. Pause e, em seguida, retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Movimento de inclinação e extensão', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
