INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Círculos com os braços', '', '', 'https://connect.garmin.com/images/exercises/images/ARM_CIRCLES/heroImage_BBtOcCZ.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_003-A3.mp4', 'aquecimento,mobilidade,yoga,pilates', 'LATERAL_RAISE', 'Iniciante', '', 'O movimento circular com os braços é um ótimo exercício de aquecimento dinâmico para ajudar a preparar o corpo para um treino. Ele também aumenta a estabilidade multiplanar no core e nos ombros.', '["Fique em pé e levante os braços para os lados para que fiquem paralelos ao chão.","Estique os dedos para fora e faça pequenos círculos rápidos com os braços."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Balanço de braço e perna opostos', '', '', 'https://connect.garmin.com/images/exercises/images/OPPOSITE_ARM_AND_LEG_BALANCE/heroImage_BBtOla7.jpg', 'https://connectvideo.garmin.com/msn-workout/Strength/S_015-A1.mp4', 'aquecimento,mobilidade', 'WARM_UP', 'Intermediário', '', 'The opposite arm and leg balance increases strength and stability in the glutes, hamstrings, core, and shoulder. This exercise also improves coordination.', '["Posicione-se com as mãos no chão completamente estendidas e abaixo dos ombros. Os joelhos devem flexionar-se em um ângulo de 90 graus, colocando-os bem abaixo dos quadris.","Contraia o abdômen e estenda um braço para a frente de forma que seu ombro fique próximo à orelha. Ao mesmo tempo, estenda completamente a perna oposta atrás de você, trazendo-a até a altura dos quadris. Retorne à posição inicial e repita com o braço e a perna opostos."]');
