INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Caminhada com elevação dos joelhos', '', '', NULL, NULL, 'aquecimento', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abraços nos joelhos com deslocamento', '', '', NULL, NULL, 'aquecimento', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Extensão de braços e pernas nos joelhos', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/ARM_AND_LEG_EXTENSION_ON_KNEES/heroImage_BBtOhs2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_002-A1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'GLUTES', 'Esse exercício estabiliza e equilibra o tronco enquanto melhora a mobilidade das articulações.', '["Apoie-se sobre suas mãos e joelhos. Alinhe os joelhos embaixo dos quadris e posicione as mãos embaixo dos ombros.","Contraia o abdômen para estabilizar o tronco, ao mesmo tempo estendendo sua mão direita e o pé esquerdo para fora até que estejam em linha reta.","Levante o braço direito e a perna esquerda o mais alto que puder enquanto mantém o tronco estável.","Abaixe o braço e a perna, retornando-os à posição inicial.","Troque de lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Deslocamento com perna dobrada', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Caminhada quatro apoios', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Ponte com deslocamento frontal', '', '', NULL, NULL, 'aquecimento,mobilidade', 'WARM_UP', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Gato-vaca', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/CAT_COW/heroImage_BBtOj0b.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_015-A1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'SHOULDERS, HIPS', 'Esse exercício é focado em como associar melhor a respiração com o movimento da coluna. Esse movimento ajuda a re-equilibrar a coluna.', '["Apoie-se sobre suas mãos e joelhos. Alinhe os joelhos embaixo dos quadris e posicione as mãos embaixo dos ombros.","Expire e enrijeça o abdômen para arredondar e curvar sua coluna, aproximando a cabeça do cóccix.","Inspire e empurre o tórax e o cóccix para longe um do outro, enquanto arqueia sua coluna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Dobras com o joelho', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/KNEE_FOLDS/heroImage_BBtO58K.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_039-B1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'HIPS', 'Esse exercício ajuda a desenvolver estabilidade na pelve movimentando as articulações dos quadris enquanto deixa a região lombar e os quadris em uma posição neutra.', '["Deite-se de costas com a pelve em uma posição neutra, com os joelhos flexionados e os pés apoiados.","Expire e contraia o abdômen para levantar a perna direita em linha reta até 90 graus.","Abaixe a perna direita enquanto ainda expira.","Inspire, depois expire e levante a perna esquerda em linha reta até 90 graus.","Abaixe a perna esquerda até o chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Levantamento inferior', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/LOWER_LIFT/heroImage_BBtO58R.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_047-B1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Intermediário', 'LOWER_BACK, HIPS', 'This exercise challenges the lower abdominals and engages the pelvis. The legs act as weight and can increase the challenge to the abs. This movement also teaches breath control and strengthens the connection between breathing and the abdominals.', '["Deite-se de costas com a pélvis estável e ligeiramente inclinada e coloque as mãos atrás do pescoço.","Levante a cabeça e os ombros do tapete enquanto estica as pernas em direção ao teto.","Inspire enquanto abaixa as pernas.","Expire e levante as pernas em direção ao teto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento do pescoço', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/NECK_PULL/heroImage_BBtOnoS.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_053-A1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Intermediário', '', 'Esse exercício trabalha os músculos abdominais e alonga a coluna e os músculos posteriores das coxas.', '["Sente-se ereto, com as pernas estendidas em linha reta. Entrelace os dedos por trás do pescoço.","Incline-se para trás o máximo que puder, mantendo a coluna reta. Espere por um segundo.","Encaixe o cóccix embaixo e curve-se para baixo em direção ao colchonete.","Assim que sua cabeça tocar o colchonete, curve o tronco para frente.","Curve e leve a cabeça até os joelhos.","Empilhe a coluna até que fique reta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Círculos de uma perna', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/SINGLE_LEG_CIRCLES/heroImage_BBtOlh0.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_089-A1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'QUADS, HAMSTRINGS', 'Este exercício ensina como segurar uma pélvis neutra. Também alivia as articulações dos quadris.', '["Deite-se de costas com a pélvis em uma posição neutra e os braços ao seu lado. Estenda sua perna direita em linha reta em direção ao teto, enquanto a perna esquerda fica reta no chão.","Inspire ao abaixar a perna direita ao lado do corpo.","Expire enquanto gira a perna para a esquerda e para cima em direção ao centro. Repita quatro vezes.","Depois, inverta a direção dos círculos. Repita quatro vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolagem', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/ROLLING/heroImage_BBtOcPt.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_074-A1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'LOWER_BACK, HIPS', 'This exercise helps teach proper breathing and balance. To benefit from this move, make sure to keep the abdominals engaged throughout the motion.', '["Sente-se com os joelhos dobrados e os pés apoiados. Coloque as mãos sob os joelhos e abra os cotovelos para os lados.","Expire ao levantar os pés do tapete e curvar a coluna, trazendo a cabeça o mais próximo possível dos joelhos.","Inspire e role para trás no tapete.","Expire enquanto você rola para se sentar."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento de uma perna', 'ABS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_090-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_090-B1.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'QUADS', '', '["Deite-se de costas com as pernas dobradas a 90 graus e com a pélvis em uma posição neutra.","Expire enquanto curva a cabeça e os ombros para a frente e para longe do chão.","Leve as mãos até o joelho direito enquanto estica o joelho esquerdo.","Em seguida, mova as mãos para o joelho esquerdo enquanto estica a perna direita."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Natação', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/SWIMMING/heroImage_BBtOpZY.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_103-A2.mp4', 'mobilidade,yoga,pilates', 'CORE', 'Iniciante', 'ABS, QUADS, SHOULDERS', 'Esse exercício concentra-se no fortalecimento do core enquanto incorpora movimentos opostos dos braços e pernas.', '["Deite-se de bruços no colchonete com os braços e as pernas retos e o abdômen contraído.","Simultaneamente, levante o braço direito e a perna esquerda do chão enquanto mantém os quadris estáveis.","Abaixe a perna e o braço.","Levante o braço esquerdo e a perna direita do chão.","Abaixe a perna e o braço.","Levante ambos os braços e ambas as pernas e sustente-os no ar.","Alterne os braços e a pernas, remando rapidamente como se estivesse nadando.","Abaixe o corpo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotações de braço', 'SHOULDERS', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ARM_ROTATIONS/heroImage_BBtOhrJ.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_005-A1.mp4', 'mobilidade,yoga,pilates', 'FLYE', 'Iniciante', 'TRAPS', 'Este exercício ajuda a melhorar a estabilidade ao atingir áreas específicas do corpo, uma de cada vez.', '["Sente-se com as pernas cruzadas em posição de lótus. Enrole uma faixa de elástico em torno das costelas, envolvendo as extremidades com pesos de 1 a 3 kg. Segurando os pesos, estique a faixa e levante os braços para os lados na altura dos ombros, com as palmas das mãos voltadas para baixo.","Feche os braços, juntando as mãos na frente do peito, com as palmas voltadas para baixo.","Abra os braços de volta para os lados.","Em seguida, gire as mãos para fora para ficar de frente para o teto.","Feche os braços, juntando as mãos na frente do peito, com as palmas voltadas para cima.","Abra os braços para os lados."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abrace uma árvore', 'CHEST', 'Halteres', 'https://connect.garmin.com/images/exercises/images/HUG_A_TREE/heroImage_BBtOpZL.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_036-A1.mp4', 'mobilidade,yoga,pilates', 'FLYE', 'Iniciante', 'TRAPS', 'Este exercício ajuda a melhorar a estabilidade ao atingir áreas específicas do corpo, uma de cada vez.', '["Sente-se com as pernas cruzadas em posição de lótus. Enrole uma faixa de elástico ao redor de suas costelas e enrole as extremidades em torno de pesos de 1 a 3 kg. Segurando os pesos, estique a faixa para juntar os nós dos dedos na frente do peito, com os cotovelos abertos para os lados.","Abra os braços e aperte os ombros.","Junte os nós dos dedos ao abrir os ombros."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Borboleta', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/CLAMS/heroImage_BBtOcQb.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_016-A1.mp4', 'mobilidade,yoga,pilates', 'HIP_RAISE', 'Iniciante', 'ABS', 'As séries de pernas laterais o desafiam a manter uma pélvis neutra e equilibrada enquanto estiver de lado e lutando contra a gravidade.', '["Deite-se de costas com os ossos dos quadris alinhados e suas pernas a 90 graus. Pressione os calcanhares um contra o outro.","Levante o joelho superior o mais alto que puder enquanto estabiliza a pélvis e mantém os calcanhares unidos.","Abaixe o joelho novamente. Em seguida, alterne os lados."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Movimento circular com as pernas', 'ABS', '', 'https://connect.garmin.com/images/exercises/images/LEG_CIRCLES/heroImage_BBtOj07.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_042-B1.mp4', 'mobilidade,yoga,pilates', 'HIP_RAISE', 'Iniciante', 'ABS, QUADS, LOWER_BACK, OBLIQUES, GLUTES', 'As séries de pernas laterais o desafiam a manter uma pélvis neutra e equilibrada enquanto estiver de lado e lutando contra a gravidade.', '["Deite-se de lado com os ossos dos quadris alinhados um sobre o outro e suas pernas empilhadas uma sobre a outra. Incline suas pernas um pouco para a frente de forma que estejam ligeiramente na frente do tronco. Aponte os dedos dos pés.","Levante a perna superior até a altura dos quadris e realize pequenos círculos com sua perna.","Inverta a direção dos círculos.","Abaixe a perna até a perna inferior. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de perna', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/LEG_LIFT/heroImage_BBtOhrS.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_043-A1.mp4', 'mobilidade,yoga,pilates', 'HIP_RAISE', 'Iniciante', 'ABS, QUADS, HAMSTRINGS, LOWER_BACK, OBLIQUES', 'As séries de pernas laterais o desafiam a manter uma pélvis neutra e equilibrada enquanto estiver de lado e lutando contra a gravidade.', '["Deite-se de lado com os ossos dos quadris alinhados um sobre o outro e suas pernas empilhadas uma sobre a outra. Incline suas pernas um pouco para a frente de forma que estejam ligeiramente na frente do tronco.","Estenda e eleve a perna superior com o pé flexionado.","Abaixe essa perna.","Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Elevação de perna em rotação externa', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/LEG_LIFT_IN_EXTERNAL_ROTATION/heroImage_BBtO59d.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_044-A1.mp4', 'mobilidade,yoga,pilates', 'HIP_RAISE', 'Iniciante', 'ABS, OBLIQUES', 'As séries de pernas laterais o desafiam a manter uma pélvis neutra e equilibrada enquanto estiver de lado e lutando contra a gravidade.', '["Deite-se de lado com os ossos dos quadris alinhados um sobre o outro e suas pernas empilhadas uma sobre a outra. Incline suas pernas um pouco para a frente de forma que estejam ligeiramente na frente do tronco. Gire sua perna superior para fora, unindo os calcanhares e separando as pontas dos pés.","Levante a perna superior até a altura dos quadris.","Contraia a perna e abaixe-a para tocar no calcanhar inferior. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Cobra', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/COBRA/heroImage_BBtOlht.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_017-A2.mp4', 'mobilidade,yoga,pilates', 'HYPEREXTENSION', 'Iniciante', 'ABS, TRICEPS, GLUTES', 'Este exercício melhora a postura e contrabalança a tendência do tronco de se enrolar para a frente.', '["Deite-se de bruços no colchonete com as mãos apoiadas ao lado das costelas e as pontas dos pés pressionando o chão.","Pressione as mãos contra o chão, imaginando que o está empurrando em direção à ponta dos pés, enquanto empurra o tórax para frente e o levanta do chão.","Abaixe-se e repita."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Arch and Curl', 'LOWER_BACK', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_001-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_001-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece sobre os quatro apoios com as mãos embaixo dos ombros e os joelhos embaixo dos quadris.","Expire e contraia o abdome enquanto arqueia a coluna para cima. Retorne à posição inicial após três respirações profundas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Arm Stretch', 'SHOULDERS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_006-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_006-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se com as pernas cruzadas no chão. Segure uma faixa elástica com as duas mãos e estenda os braços em forma de V na frente do corpo.","Inspire enquanto levanta os braços sobre a cabeça, esticando-os o máximo que puder.","Expire e retorne lentamente os braços à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Bridge (with ball)', 'ABS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_012-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_012-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'QUADS, ADDUCTORS, HAMSTRINGS', '', '["Deite-se de costas com os joelhos dobrados e os pés apoiados no chão. Coloque uma bola medicinal entre os joelhos.","Levante o quadril lentamente e segure."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abertura de ombros em oito pontos', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/EIGHT_POINT_SHOULDER_OPENER/heroImage_BBtOsD8.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_026-A2.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Avançado', 'TRAPS, LOWER_BACK', 'Diz-se que este profundo abridor de ombros alivia dores nos ombros e na garganta. Também inclui uma rotação, e portanto, acredita-se que desintoxica o corpo.', '["Comece deitado de bruços.","Posicione o braço esquerdo em um ângulo de 90 graus do corpo com a palma da mão voltada para cima.","Apoie firmemente a mão direita debaixo do ombro direito e dobre o joelho direito.","Coloque os dedos do pé direito atrás do joelho esquerdo no chão, enquanto gira o corpo.","Movimente o braço direito em direção ao teto, flexione a palma da mão, e deixe a mão cair no chão em direção ao solo com a gravidade. Respire nessa posição.","Se houver espaço suficiente, entrelace a mão direita com a esquerda e respire profundamente pelo menos três vezes nessa posição e, então, desfaça a postura no mesmo ritmo lento em que se colocou nela. Repita o movimento com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Forward Fold', 'SHOULDERS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_028-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_028-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'LOWER_BACK, HIPS', '', '["Comece sentado com as pernas cruzadas.","Estique os braços acima da cabeça. Em seguida, abaixe lentamente os braços e a parte superior do corpo em direção ao chão.","Mantenha o alongamento por três respirações profundas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Hamstring Stretch', 'HAMSTRINGS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_035-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_035-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição sentada.","Estenda sua perna direita e posicione o pé esquerdo na parte interna da coxa direita.","Apoie-se sobre os dedos abertos e esticados posicionados em ambos os lados da perna direita e torça o tronco para a direita.","Inspire profundamente para alongar a coluna, e expire para contrair o úmbigo para dentro junto à coluna e inclinar o tronco para frente sobre a perna direita. Caminhe suas mãos para frente enquanto se inclina, e relaxe a cabeça em direção à perna. Respire fundo nessa posição por pelo menos três vezes. Repita com sua perna esquerda alongada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Hip Stretch', 'HIPS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_078-A5.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_078-A5.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece deitando-se no chão.","Abrace o joelho direito, puxando-o até o peito.","Coloque sua mão esquerda na parte exterior da coxa direita e leve o joelho direito para a esquerda.","Estenda o braço direito para a direita no chão. Você pode manter o pescoço fixo ou, se quiser, pode olhar para a direita. Você pode manter a mão esquerda na coxa direita para permitir que seu peso apoie a perna direita ou, se preferir, estique o braço esquerdo para a esquerda, de modo que seus braços formem uma única linha reta. Mantenha essa posição por pelo menos cinco respirações profundas e faça o mesmo do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Leg Stretch (with Band)', 'HAMSTRINGS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_045-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_045-B1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'CALVES', '', '["Deite-se de costas. Coloque uma faixa de elástico ao redor do pé direito enquanto a segura com as mãos.","Estique a perna direita em direção ao teto.","Abaixe a perna direita sobre a perna esquerda e mantenha o alongamento.","Repita com a perna esquerda."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Leg Stretch with Leg Circles', 'HAMSTRINGS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_046-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_046-B1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, OBLIQUES, CALVES', '', '["Deite-se de costas e estenda uma perna até o teto.","Faça pequenos círculos com o pé estendido, mantendo os dedos do pé esticados. Inspire enquanto sua perna se aproxima do corpo e expire enquanto ela se afasta.","Repita com a outra perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mermaid Stretch', 'SHOULDERS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_058-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_058-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', 'Esse exercício de quadris flexionado para trás e de abertura de ombros é uma versão intermediária da Postura completa do pombo real. O nome Postura da sereia deriva-se da semelhança da perna traseira com uma cauda de sereia.', '["Comece na posição do cão.","Estenda sua perna direita para cima para a posição do cachorro embaixo com três pernas, abra os quadris e flexione o joelho.","Arraste a canela direita para frente em direção à frente do tapete, com a qual sua perna ficará o mais paralela possível. Abaixe os quadris ao chão para a posição do pombo com a perna estendida.","Flexione o joelho esquerdo e segure o pé direito, posicionando-o na dobra do cotovelo esquerdo. Em seguida, tente alinhar os quadris.","Estique o braço direito para o teto pela lateral do rosto e, em seguida, flexione o cotovelo direito estendendo a mão direita atrás para entrelaçá-la com a esquerda. Use uma faixa se suas mãos não alcançarem a posição desejada. Respire profundamente pelo menos três vezes nessa posição. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Piriformis Stretch', 'GLUTES', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_060-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_060-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', '', '["Deite-se de costas. Posicione uma perna com o joelho dobrado e o pé apoiado no chão e cruze a outra perna sobre ela.","Puxe as pernas em direção à parte superior do corpo com os braços e alcance os tornozelos."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Roll Down', 'ABS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_070-A4.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_070-A4.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Fique de pé com os braços sobre a cabeça.","Desça lentamente o torso em direção ao chão, curvando as costas. Expire pela boca durante o movimento.","Alcance o chão e segure."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento afundo de psoas', 'HIPS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_038-A4.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_038-A4.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição “cachorrinho” para baixo.","Leve o joelho direito em direção ao nariz.","Coloque o pé direito entre as mãos, ficando em na postura equestre.","Transfira seu peso para os pés e eleve os braços em direção ao teto, deixando-os ao lado do rosto. Mantenha o joelho direito flexionado em um ângulo de 90 graus. Não deixe o joelho sair da linha do tornozelo. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Saw', 'OBLIQUES', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_079-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_079-A2.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'LOWER_BACK, HIPS, ABS', '', '["Sente-se com as pernas estendidas em forma de V e os pés flexionados.","Estenda os braços para os lados.","Inspire pelo nariz e gire para olhar para a direita, movendo apenas o tronco.","Expire pela boca enquanto estica a mão esquerda além do pé direito.","Inspire e retorne os braços para a posição de giro lateral.","Expire e retorne à posição inicial.","Repita o exercício do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento do quadril sentado', 'ADDUCTORS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_084-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_084-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se com as pernas ligeiramente dobradas e os pés apoiados no chão.","Cruze a perna direita sobre a perna esquerda e estenda-a para fora com o pé direito flexionado. Mantenha o alongamento.","Retorne à posição inicial e repita o movimento usando a perna esquerda desta vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Seated Twist', 'ADDUCTORS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_085-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_085-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'LOWER_BACK, SHOULDERS, CHEST', '', '["Sente-se com as pernas estendidas à sua frente.","Cruze a perna direita sobre a perna esquerda e aproxime-a do tronco, com o pé apoiado no chão.","Gire o tronco para a direita enquanto mantém o alongamento.","Retorne à posição inicial e repita o movimento usando a perna esquerda desta vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Spinal Twist', 'GLUTES', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_078-A5.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_078-A5.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', '', '["Comece deitando-se no chão.","Abrace o joelho direito, puxando-o até o peito.","Coloque sua mão esquerda na parte exterior da coxa direita e leve o joelho direito para a esquerda.","Estenda o braço direito para a direita no chão. Você pode manter o pescoço fixo ou, se quiser, olhe para a direita. Você pode manter a mão esquerda na coxa direita ou, se preferir, estender o braço esquerdo para a esquerda, de modo que seus braços formem uma linha longa. Mantenha a posição por pelo menos cinco respirações profundas e repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento de torção da coluna vertebral', 'GLUTES', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_093-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_093-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', '', '["Comece deitando-se no chão.","Abrace o joelho direito, puxando-o até o peito.","Coloque sua mão esquerda na parte exterior da coxa direita e leve o joelho direito para a esquerda.","Estenda o braço direito para a direita no chão. Você pode manter o pescoço fixo ou, se quiser, olhe para a direita. Você pode manter a mão esquerda na coxa direita ou, se preferir, estender o braço esquerdo para a esquerda, de modo que seus braços formem uma linha longa. Mantenha a posição por pelo menos cinco respirações profundas e repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Spine Stretch Forward', 'GLUTES', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_060-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_060-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', '', '["Comece na posição sentada com as costas e as pernas retas e as palmas das mãos no chão voltadas para a frente.","Inspire profundamente para alongar e expire para trazer o umbigo para a coluna e incline a parte superior do corpo para a frente, estendendo as mãos para a frente o máximo que for confortável para as pernas e a parte inferior das costas.","Deixe a cabeça relaxar em direção às pernas. Faça pelo menos três respirações profundas nesta posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Standing Side Stretch', 'OBLIQUES', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_072-A4.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_072-A4.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece de pé com os braços relaxados ao lado do corpo.","Estenda os braços para o lado e acima da cabeça para emoldurar o rosto.","Segure o pulso direito com a mão esquerda.","Respire fundo para alongar e expire para se inclinar para a esquerda, dobrando o lado esquerdo da cintura e relaxando o cotovelo esquerdo.","Incline-se ligeiramente para trás para abrir o peito em direção ao teto. Faça pelo menos três respirações profundas nesta posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tick-Tock (Side Roll)', 'ABS', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_108-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_108-A2.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'HIPS', '', '["Deite-se de costas com os joelhos puxados até ao peito e os pés cruzados.","Com a coluna fixa, inspire e abaixe os joelhos para um lado do corpo.","Expire e traga os joelhos de volta ao centro.","Continue alternando os lados."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Suspensão em pé', 'GLUTES', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_070-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_070-A3.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS', '', '["Postura de curvatura para a frente em pé. Comece ficando de pé com os braços relaxados contra a lateral do corpo.","Inspire profundamente para estender os braços para cima da cabeça, enquadrando o rosto.","Expire para contrair o umbigo junto à costela e mergulhe a cabeça sobre as pernas com as costas retas.","Posicione as mãos no chão ligeiramente na frente ou ao lado dos pés. Pressione os quatro cantos dos pés contra o chão e eleve os ossos ísquios em direção ao teto. Relaxe a cabeça e o pescoço. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento lateral intenso com abertura da banda iliotibial', 'GLUTES', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/STANDING_SINGLE_LEG_FORWARD_BEND_WITH_IT_BAND_OPENER/heroImage_BBtOnrf.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_074-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Intermediário', 'SHOULDERS', 'This pose targets the IT bands, making it suitable for those who need a stretch in this area such as runners, cyclists and even people with desk jobs.', '["Comece em pé inclinado para frente, com as pernas bem abertas, e virado para a direita.","Mantendo as mãos apoiadas no chão, leve-as para a direita em direção à borda de trás do tapete, girando o corpo e os pés.","Continue levando as mãos para a direita até que sua perna direita fique cruzada com a esquerda e você esteja pisando com as laterais dos pés.","Empurre a parte de dentro do pé contra o chão para que o pé inteiro fique apoiado. Relaxe a cabeça e o pescoço. Respire profundamente pelo menos três vezes nessa posição, relaxe, e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Twist', 'OBLIQUES', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_110-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_110-A1.mp4', 'mobilidade,yoga,pilates', 'MOVE', 'Iniciante', 'ABS, LOWER_BACK', '', '["Sente-se com as pernas estendidas e os pés flexionados.","Com as mãos atrás da cabeça, vire lentamente o torso para um lado enquanto inspira pelo nariz.","Expire pela boca ao retornar ao centro.","Continue alternando os lados."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do tornozelo ao joelho', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/ANKLE_TO_KNEE/heroImage_BBtOfkk.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_002-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HIPS', 'Essa posição também é referida como "Postura do pombo dupla" e, traduz-se do sânscrito como "Postura da lenha". Irá ajudá-lo a soltar os quadris.', '["Comece sentado com as pernas amplamente afastadas uma da outra para os lados.","Flexione o joelho direito e posicione a canela direita no chão à sua frente, paralela à extremidade da frente do tapete.","Encaixe sua canela esquerda em cima da direita, de forma que seu tornozelo esquerdo esteja no topo do joelho direito e o tornozelo direito esteja no topo do joelho esquerdo.","Flexione os dois pés para proporcionar estabilidade estática e assim proteger os joelhos.","Posicione as mãos no chão na frente das canelas. Inspire puxando o umbigo de encontro à coluna, e expire  alongando-se para frente.","Deixe que sua cabeça relaxe e respire profundamente por pelo menos três vezes. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da meia-cobra', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/BABY_COBRA/heroImage_BBtOhv0.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_003-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'BICEPS, TRICEPS, SHOULDERS, CHEST', 'A postura da meia-cobra é um meio-termo entre a postura da esfinge e da cobra. Aumenta a flexibilidade da coluna e é frequentemente usada no lugar da cobra como um substituto da forte retroflexão da coluna.', '["Comece deitado de bruços com os pés levemente separados.","Posicione as palmas das mãos sob os ombros.","Alongue-se encaixando o cóccix e comece a empurrar o tórax para frente. Os cotovelos devem ficar próximos ao corpo e flexionados. Olhe levemente para cima. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da ponte', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/BRIDGE/heroImage_BBtOnsF.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_009-A5.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'BICEPS, CHEST, TRAPS, CALVES, HAMSTRINGS', 'Esse movimento de retroflexão básica da coluna é normalmente dada como uma alternativa à postura da roda nas aulas de ioga. Essa postura fortalece e alonga as costas e a musculatura abdominal, e, por fazer isso, melhora a postura e a confiança.', '["Comece deitado de costas.","Flexione os joelhos e coloque os pés no chão, alinhados com largura dos quadris. Deixe os braços ao lado do corpo e próximos dos calcanhares. As laterais de fora dos pés devem estar paralelas.","Pressione os pés contra o chão (especialmente a articulação do dedão do pé), encaixe o cóccix e eleve os quadris.","Junte as mãos atrás de você e, se possível, aproxime os ombros um do outro, um de cada vez. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do gato', 'HIPS', '', 'https://connect.garmin.com/images/exercises/images/CAT/heroImage_BBtOfkx.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_011-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'SHOULDERS', 'Essa posição recebe esse nome devido a seu aspecto: a aparência de um gato enfurecido.', '["Comece sobre os quatro apoios com as mãos embaixo dos ombros e os joelhos embaixo dos quadris.","Expire para puxar o umbigo para dentro junto à coluna e pressione o chão com as mãos e os joelhos, curvando a coluna como um gato bravo. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cadeira', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/CHAIR/heroImage_BBtOj2S.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_012-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ADDUCTORS, CALVES', 'Also referred to as "Fierce or Powerful" pose(the Sanskrit translation) or "Awkward" pose, this pose is most commonly referred to as "Chair pose" since it looks like you''re sitting down in a chair.', '["Comece na posição em pé, na Postura da montanha.","Flexione os joelhos, empurre os quadris para baixo e para trás como se estivesse se sentando em uma cadeira, e eleve os braços para o alto até que fiquem nas laterais do rosto.","Olhe para frente e certifique-se de poder enxergar os dedos do pé. Se não conseguir, sente-se mais para trás até que possa.","Abaixe os ombros, distanciando-os das orelhas, e olhe levemente para cima. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da criança', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/CHILDS/heroImage_BBtOliY.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_013-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'LOWER_BACK, HIPS', 'A Postura da criança é a posição obrigatória de descanso para os momentos em que se precisa de uma pausa durante uma sequência de ioga.  A posição acalma e relaxa o corpo e a mente.', '["Comece na posição ajoelhada com os joelhos ligeiramente afastados um do outro.","Engatinhe suas mãos adiante, com os braços alongados e à sua frente.","Deixe que seu tronco relaxe sobre as coxas e que a testa se apoie no chão. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do golfinho', 'SHOULDERS', 'Faixa', 'https://connect.garmin.com/images/exercises/images/DOLPHIN/heroImage_BBtOsCu.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_019-D1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'GLUTES, QUADS, HAMSTRINGS', 'A postura do crocodilo é uma alternativa à postura do cachorro olhando para baixo com apoio dos antebraços para aqueles com sensibilidade nos punhos.', '["Inicie o movimento apoiando-se sobre suas mãos e joelhos.","Segure os cotovelos opostos para alinhá-los com a distância da largura dos ombros, e mantendo os cotovelos nessa distância, coloque os antebraços paralelos um ao outro no chão, com as palmas viradas para baixo.","Firme os dedos dos pés e eleve os quadris para o alto.","Solte a cabeça e jogue o peito para trás com os braços na direção dos pés para melhorar a abertura de ombros.","Coloque os calcanhares para trás. Respire fundo nessa posição cinco vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da vaca', 'LOWER_BACK', '', 'https://connect.garmin.com/images/exercises/images/COW/heroImage_BBtOj1a.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_016-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'SHOULDERS, HIPS', 'This pose is named for its shape — when you arch your spine, it looks like a cow''s udders', '["Comece sobre os quatro apoios com as mãos embaixo dos ombros e os joelhos embaixo dos quadris.","Ao inspirar, curve os ombros para longe das orelhas, olhe para cima e arqueie a coluna. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para baixo', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/DOWNWARD_FACING_DOG/heroImage_BBtSAwB.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_023-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ADDUCTORS, OBLIQUES', 'Provavelmente a postura mais comumente reconhecida no ioga, o Cachorro Olhando Para Baixo alonga ou abre a maior parte do corpo.
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para baixo com perna elevada', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/DOWN_DOG_SPLIT/heroImage_BBtOq33.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_021-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ADDUCTORS, OBLIQUES', 'Essa variação com uma perna da Postura do cachorro olhando para baixo é bastante utilizada como uma postura transitória ao mover cada perna para frente em uma sequência de ioga.', '["Comece na Postura do cachorro olhando para baixo.","Eleve a perna direita para o alto, alinhada com o corpo. Os dedos do pé devem estar voltados para baixo e os quadris, paralelos ao chão. Continue empurrando o calcanhar esquerdo contra o chão e mantenha os ombros alinhados. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para baixo com perna elevada, quadris abertos e joelho flexionado', 'SHOULDERS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_022-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_022-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ADDUCTORS, OBLIQUES', '', '["Comece na Postura do cachorro olhando para baixo.","Eleve a perna direita para o alto, alinhada com o corpo.","Abra os quadris e flexione o joelho. Continue empurrando o calcanhar esquerdo contra o chão. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Cachorro olhando para baixo para a postura da cobra', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_009_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_009_CamA.mp4', 'mobilidade', 'POSE', 'Iniciante', '', '', '["Fique na posição de quatro apoios, com os pés e as mãos no chão e seus glúteos suspensos no ar.","Gire o corpo lentamente para baixo, movendo os braços superiores para a frente até que os joelhos toquem o chão.","Pause e mantenha o alongamento e, em seguida, retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cancela', 'OBLIQUES', '', 'https://connect.garmin.com/images/exercises/images/GATE/heroImage_BBtOsAW.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_032-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS', 'This pose stretches the side of the torso which may create space for the lungs to take deeper breaths.', '["Comece posicionado sobre as mãos e os joelhos.","Com o dorso do pé direito apoiado no chão, abra a canela direita para a direita até que fique perpendicular à canela esquerda.","Apoie o calcanhar esquerdo no chão para que o pé fique plano e com o lado de dentro paralelo à borda de trás do tapete, alinhado com o joelho direito.","Transfira seu peso para a canela direita e para o pé esquerdo, e levante o tronco deixando-o reto acima dos quadris.","Apoie a mão esquerda na canela esquerda, eleve o braço direito em direção ao teto e solte o ar dobrando o lado esquerdo da cintura e se inclinando para a esquerda.","Gire levemente o tórax para abri-lo em direção ao teto e respire profundamente pelo menos três vezes nessa posição. Repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro estirado', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/EXTENDED_PUPPY/heroImage_BBtOlj0.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_027-B1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'GLUTES, HAMSTRINGS', 'Embora essa posição possa se assemelhar à Postura da criança, é na realidade uma variação dos joelhos da Postura do cão olhando para baixo. Acredita-se que a postura reduza o estresse e acalma a mente.', '["Comece sobre os quatro apoios.","Caminhe suas mãos alguns centímetros para frente com os dedos abertos e as palmas firmemente apoiadas no chão.","Projete os dedos dos pés para frente e deixe os quadris caírem para trás a meio caminho dos calcanhares.","Deixe a testa cair ao chão. Contraia as escápulas uma contra a outra para dentro. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de alongamento em ângulo lateral', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/EXTENDED_SIDE_ANGLE/heroImage_BBtOcSE.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_028-A4.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'CHEST, LOWER_BACK, ABS, ABDUCTORS', 'A tradução do nome sânscrito é algo como "postura do "alongamento em ângulo lateral. Essa postura abre todo o corpo e fortalece as pernas assim como o guerreiro II, além de abrir e alongar o tronco.', '["Comece na postura do guerreiro II, com a perna direita para frente.","Dobre o lado direito da cintura e apoie o antebraço direito na coxa direita.","Eleve o braço esquerdo em direção ao teto e, então, em direção à borda da frente do tapete. Deixe o ombro esquerdo distante da orelha.","Abra o tórax em direção ao teto.Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Variação da postura do guerreiro I', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/HIGH_LUNGE/heroImage_BBtOcS7.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_038-A4.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS', 'Um dos movimentos da sequência básica da saudação ao sol, essa postura não tem um nome sânscrito, mas é incorporada em quase todos os estilos de ioga.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz.","Coloque o pé direito entre as mãos, ficando em na postura equestre.","Transfira seu peso para os pés e eleve os braços em direção ao teto, deixando-os ao lado do rosto. Mantenha o joelho direito flexionado em um ângulo de 90 graus. Não deixe o joelho sair da linha do tornozelo. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cabeça no joelho', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/HEAD_TO_KNEE/heroImage_BBtOsAu.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_035-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'SHOULDERS', 'Janu significa "joelho" e sirsa refere-se à "cabeça". Você irá mais longe na postura para centralização relaxando e não forçando a si mesmo a se aprofundar na posição. A respiração lenta é o que irá aumentar a amplitude de movimento.', '["Comece na posição sentada.","Estenda sua perna direita e posicione o pé esquerdo na parte interna da coxa direita.","Apoie-se sobre os dedos abertos e esticados posicionados em ambos os lados da perna direita e torça o tronco para a direita.","Inspire profundamente para alongar a coluna, e expire para contrair o úmbigo para dentro junto à coluna e inclinar o tronco para frente sobre a perna direita. Caminhe suas mãos para frente enquanto se inclina, e relaxe a cabeça em direção à perna. Respire fundo nessa posição por pelo menos três vezes. Repita com sua perna esquerda alongada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do lagarto', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LIZARD/heroImage_BBtOhtN.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_040-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS', 'Esta é uma postura versátil que abre os quadris e pode ser modificada de várias formas e adaptada para a maioria dos corpos. Prepara o corpo para alongamentos de quadris maiores como a postura do pombo. A postura lembra um lagarto — a perna de trás representa o rabo.', '["Comece na posição do cão.","Eleve a perna direita para o alto na postura do cachorro olhando para baixo com perna elevada, abra os quadris e flexione o joelho.","Coloque o pé direito do lado de fora da mão direita.","Leve o joelho esquerdo ao chão e abaixe os antebraços, um de cada vez, até o chão.","Empurre o tórax para frente tentando ir além dos braços e deixe a cabeça relaxar, alinhada com a coluna. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura equestre', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LOW_LUNGE/heroImage_BBtOhtJ.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_042-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS', 'A Postura equestre é comum nos exercícios e um dos movimentos da sequência básica da saudação ao sol.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos.","As mãos devem estar nos dois lados do pé da frente, com a ponta dos dedos pressionando o chão ou apoiada em blocos. Mantenha o pescoço reto e alinhado com a coluna.  Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura equestre com rotação de tronco', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LOW_LUNGE_TWIST/heroImage_BBtOsAT.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_043-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS, ABS, OBLIQUES', 'Low Lunge Twist is a variation of several poses, but the varying schools of yoga disagree on the exact pose. This posture improves spinal flexibility, and is thought to help stimulate digestion.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos.","Leve o joelho de trás ao chão.","Apoie a palma da mão esquerda no chão, alinhada com seu pé direito e abaixo do ombro, e eleve o braço direito para o teto. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da lua crescente', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/LOW_LUNGE_WITH_KNEE_DOWN/heroImage_BBtOnr8.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_044-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS', 'The derivation of the Sanskrit name of this pose comes  from Anjani, the mother of the Monkey God, Hanuman. It is said that she was praying in this pose with her arms raised, asking to have a child when she was divinely blessed and became pregnant. This pose is also sometimes referred to as "Crescent Lunge", due to its shape.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos.","Abaixe o joelho de trás.","Apoie as mãos na coxa direita, elevando a coluna em linha reta. Respire nessa posição.","Levante os braços ao lado do rosto e eleve o tórax para cima e para trás, com uma leve retroflexão da coluna. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura reclinada com o pé na mão', 'HIPS', 'Faixa', 'https://connect.garmin.com/images/exercises/images/RECLINED_HAND_TO_FOOT/heroImage_BBtOfnA.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_053-A2.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'LOWER_BACK', 'Enquanto a tradução da expressão seja postura" reclinada da mão ao dedão do pé", ela é normalmente chamada de Pé na Mão. Esta postura é uma forma suave de abrir e alongar as pernas.', '["Comece deitado de costas.","Puxe seu joelho direito em direção ao tórax.","Segure o dedão do pé direito com o polegar direito e os dedos indicador e médio, e segure o contorno externo do pé ou da coxa direita, ou coloque uma faixa ao redor do pé.","Alongue a perna, segure o calcanhar, e puxe seu pé na direção da cabeça gentilmente. Deixe o braço esquerdo alongado e relaxado do lado esquerdo do corpo, com a palma voltada para baixo. Respire profundamente pelo menos três vezes nessa posição e então repita com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para baixo com uma perna, quadril aberto e joelho dobrado', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/ONE_LEGGED_DOWNWARD_FACING_DOG_POSE_OPEN_HIP_BENT_KNEE/heroImage_BBtSxYc.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_047-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ADDUCTORS, OBLIQUES', 'Essa variação de quadril aberto da Postura do Cachorro Olhando para Baixo com uma perna é frequentemente usada como uma transição para trazer uma perna para frente para uma postura de quadril aberta, ou para mudar para uma postura ereta ou sentada.', '["Comece com a posição do Cachorro Olhando para Baixo.","Atinja a altura com a perna direita alinhada com o corpo.","Abra o quadril e dobre o joelho e continue alcançando o calcanhar esquerdo em direção ao chão. Faça pelo menos três respirações profundas nessa posição e repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do corredor', 'QUADS', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/RUNNERS_LUNGE/heroImage_BBtOfkp.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_057-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABDUCTORS, ADDUCTORS', 'A tradução do sânscrito para essa posição é "Dividido ao meio", embora seja comumente referida por "Postura do corredor", por ser uma posição apropriada para corredores. Essa posição irá prepará-lo para executar um espacate ou abertura total das pernas.', '["Comece em uma posição baixa de afundo com o pé direito para frente.Se a posição for muito intensa para os músculos posteriores da coxa, flexione o joelho até que os músculos possam relaxar. Respire fundo nessa posição por pelo menos três vezes, em seguida repita com o outro pé.","Solte seu joelho esquerdo para baixo no chão.","Caminhe as mãos para trás enquanto empurra seus quadris para trás na direção do tornozelo esquerdo e alonga a perna direita.","Relaxe e flexione o tronco para frente sobre a coxa direita. Respire profundamente pelo menos três vezes nessa posição. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sentada fácil com torção', 'HIPS', '', 'https://connect.garmin.com/images/exercises/images/SEATED_EASY_TWIST/heroImage_BBtOhsp.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_059-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'SHOULDERS, LOWER_BACK', 'Acredita-se que essa torção sentada ajude a desitoxicar, melhorar a circulação sanguínea e aumentar a flexibilidade dos quadris e da coluna.', '["Comece na postura fácil sentada com os braços relaxados em ambos os lados.","Leve sua mão direita para trás ao chão, atrás do osso sacro, e sua mão esquerda para o joelho direito.","Inspire profundamente alongando a coluna, em seguida use suas mãos para torcer o tronco para a direita."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sentada inclinada para frente em ângulo aberto', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/SEATED_WIDE_LEG_FORWARD_BEND/heroImage_BBtOj1m.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_061-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS, SHOULDERS', 'O nome se traduz em postura "sentada em ângulo". Proporciona uma abertura suave para muitas articulações e pode exercer papel incrivelmente centralizador se sua testa estiver tocando o chão ou o bloco.', '["Comece sentado na Postura do bastão.","Afaste as pernas amplamente uma da outra.","Eleve seus quadris ligeiramente para encaixá-los mais à frente, se possível.","Solte as mãos no chão à sua frente, inspire profundamente para alongar a coluna e, ao expirar, engatinhe as mãos para frente, mantendo a coluna alongada.","Venha para frente o quanto seu corpo permitir com a coluna alongada, em seguida relaxe a cabeça embaixo em direção ao chão ou a um bloco. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de agachamento com rotação de tronco e braços abertos', 'HIPS', '', 'https://connect.garmin.com/images/exercises/images/SQUAT_OPEN_ARM_TWIST/heroImage_BBtOsBQ.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_066-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'LOWER_BACK, CALVES', 'Além do fortalecimento muscular que uma posição clássica de agachamento proporciona, essa variação provoca a abertura dos ombros e tem um componente energizante. Essa postura é recomendada para atletas.', '["Comece em pé inclinado para frente, com as mãos à sua frente no chão.","Separe os pés alternando o apoio na ponta dos pés e no calcanhar, e deixe os dedos projetados para fora para que os quadris fiquem abertos.","Flexione os joelhos, deixando os quadris irem em direção ao chão, e mantenha o tronco suspenso a qualquer altura que seja confortável. Mantenha os joelhos alinhados com os tornozelos.","Leve a mão direita à frente da canela direita, apoie a palma no chão com os dedos voltados para fora, na frente do pé direito.","Eleve o braço esquerdo em direção ao teto, fazendo uma linha reta com os braços, e olhe para cima em direção ao polegar esquerdo. Pressione levemente o braço direito contra a perna direita. Gire seu tórax para cima, abrindo-o em direção ao teto. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sentada em ângulo fechado (Postura da pinça)', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/SEATED_LONG_LEG_FORWARD_BEND/heroImage_BBtOhte.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_060-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', '', 'This pose is the fifth of the 12 Basic Hatha Yoga Postures. The Sanskrit translation is "Intense Stretch of the West" (west means your back). This grounding pose not only opens your back, but your hamstrings as well.', '["Comece sentado na Postura do bastão.","Inspire profundamente para se alongar e expire para contrair o úmbigo para dentro junto à coluna e inclinar o tronco para frente. Estenda as mãos para frente até onde as pernas e a região lombar ainda estiverm confortáveis.","Deixe que sua cabeça relaxe embaixo sobre as pernas. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da guirlanda', 'HIPS', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/SQUAT_PALM_PRESS/heroImage_BBtOhuW.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_067-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'LOWER_BACK, CALVES', 'Além de ser chamada de "guirlanda", essa postura tem alguns nomes menos convincentes: postura  da "excreção" ou "alívio". Acredita-se que essa postura estimula a digestão.', '["Comece em pé inclinado para frente, com as mãos à sua frente no chão.","Separe os pés alternando o apoio na ponta dos pés e no calcanhar, e deixe os dedos projetados para fora para que os quadris fiquem abertos.","Flexione os joelhos, deixando os quadris irem em direção ao chão, e mantenha o tronco suspenso a qualquer altura que seja confortável. Mantenha os joelhos alinhados com os tornozelos.","Posicione os cotovelos no lado de dentro das coxas, pressionando-os levemente para fora, e junte as mãos no centro do tórax, em gesto de saudação. Mantenha a coluna alongada. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Meia postura do alongamento intenso', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/STANDING_FORWARD_BEND_HALFWAY_UP/heroImage_BBtOj1B.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_071-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS', 'Essa flexão média frontal abre o tronco e acredita-se que alivie as dores estomacais. Essa pose é mais comumente vista na tradicional saudação ao sol versão "avançada".', '["Comece em pé, inclinado para frente.","Inspire profundamente para puxar o umbigo para dentro e deixar as costas retas.","Rotacione externamente as coxas. Deixe o pescoço reto e alinhado com o resto da coluna.Respire profundamente pelo menos três vezes nessa posição. Gire externamente as coxas. O pescoço ficará reto e alinhado com o resto da coluna.Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do alongamento intenso posterior e de flexão anterior', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/STANDING_FORWARD_BEND/heroImage_BBtOq1A.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_070-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS', 'Esse é a 11ª das 12 Posturas básicas da Hatha yoga. Nessa posição em pé flexionada para frente, a coluna é alongada e a cabeça é solta abaixo do coração, aumentando o fluxo sanguíneo para o cérebro.  Essa posição é conhecida por ajudar em diversas situações: desde estresse à depressão e sinusite.', '["Comece em pé na Postura da montanha.Comece na posição em pé, na Postura da montanha.","Inspire profundamente para estender os braços para cima da cabeça, enquadrando o rosto.","Expire para contrair o umbigo junto à costela e mergulhe a cabeça sobre as pernas com as costas retas.","Posicione as mãos no chão ligeiramente na frente ou ao lado dos pés. Pressione os quatro cantos dos pés contra o chão e eleve os ossos ísquios em direção ao teto. Relaxe a cabeça e o pescoço. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de abertura lateral em pé / Postura de rotação da cintura', 'OBLIQUES', '', 'https://connect.garmin.com/images/exercises/images/STANDING_SIDE_OPENER/heroImage_BBtOfkX.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_072-A4.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS', 'Essa posição recebe diferentes nomes em cada estilo de ioga. Kati significa "quadril", e chakrasana refere-se à "roda". Assim, essa abertura lateral em pé também pode ser entendida como uma flexão de quadril.', '["Comece em pé na Postura da montanha.","Estenda os braços para fora nas laterais e depois acima da cabeça, enquadrando o rosto.","Segure o pulso direito com a mão esquerda.","Inspire profundamente para se alongar, e expire para tombar o tronco para a esquerda, flexionando a cintura do lado esquerdo e suavizando o cotovelo esquerdo.","Incline-se ligeiramente para trás para abrir o tórax em direção ao teto. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura inclinada com pernas afastadas em pé', 'HAMSTRINGS', '', 'https://connect.garmin.com/images/exercises/images/STANDING_WIDE_LEG_FORWARD_BEND/heroImage_BBtOj1w.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_076-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ABS, LOWER_BACK', 'Essa posição traduz-se por "Extensão posterior do triângulo". Portanto, não seja enganado por essa posição fácil - trata-se de um movimento criado para desafiá-lo.', '["Comece se posicionando em pé e em postura reta. Com o pé direito, dê um passo largo para fora e posicione as bordas externas dos pés paralelamente.","Inspire profundamente para contrair o umbigo à coluna, depois estenda os braços para cima.","Mantendo a coluna alongada, expire para curvar-se para frente com os quadris até que as mãos cheguem ao chão.","Caminhe suas mãos para trás alinhando-as com as pontas dos pés. Deixe que sua cabeça relaxe em direção ao chão.Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do alongamento lateral intenso', 'GLUTES', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/STANDING_SINGLE_LEG_FORWARD_BEND/heroImage_BBtOsAY.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_073-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'SHOULDERS', 'O nome dessa postura é traduzido como "alongamento lateral intenso", e ela é também chamada de "postura da pirâmide".  Como o nome sugere, trata-se de um alongamento intenso especialmente para os músculos posteriores da coxa, e também acredita-se que acalme a mente.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos, ficando na postura equestre. Se a região posterior da coxa não for muito alongada, coloque blocos embaixo das mãos.","Eleve os quadris e estique as duas pernas. As mão devem ficar no chão nos dois lados da perna direita.","Gire o calcanhar de trás no chão até que o pé fique em um ângulo de 45 graus e paralelo aos quadris. Respire profundamente pelo menos três vezes nessa posição e então repita o movimento com o pé esquerdo para frente."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura inclinada com pernas afastadas em pé com torção', 'CHEST', '', 'https://connect.garmin.com/images/exercises/images/STANDING_WIDE_LEG_FORWARD_BEND_WITH_TWIST/heroImage_BBtOhtE.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_077-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'QUADS, ABS, LOWER_BACK', 'Acredita-se que essa torção estimule a digestão enquanto alonga a coluna e os músculos posteriores das coxas.', '["Comece na posição inclinada para frente com as pernas amplamente afastadas.","Leve a mão esquerda para o tornozelo ou canela direita.","Estenda o braço esquerdo para cima em direção ao teto.","Incline-se ligeiramente para trás com o tórax. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de torção da coluna deitada', 'GLUTES', '', 'https://connect.garmin.com/images/exercises/images/SUPINE_SPINAL_TWIST/heroImage_BBtOq4F.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_078-A5.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ABS, LOWER_BACK', 'Esta suave rotação feita deitado de costas é uma postura contrária à curvatura das costas. Tal como acontece com todas as torções, diz-se que esta postura desintoxica o corpo.', '["Comece deitado de costas.","Puxe o joelho direito para o peito.","Coloque sua mão esquerda na parte exterior da coxa direita e leve o joelho direito para a esquerda.","Estenda o braço direito para o lado direito no chão. O pescoço pode ficar em posição neutra, ou se for confortável, olhe para a direita. Você pode apoiar a mão esquerda na coxa direita para manter a perna direita no chão, ou se preferir, alongue o braço esquerdo para a esquerda, para que seus braços formem uma linha reta.Respire profundamente pelo menos cinco vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da mesa', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/TABLE_TOP/heroImage_BBtOlkF.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_079-A5.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', '', 'A postura da mesa é muitas vezes indicada como uma modificação mais fácil para iniciantes da postura do alongamento frontal.', '["Comece sentado com as pernas estendidas à sua frente e com os pés na distância da largura dos quadris.","Posicione as mãos em cada lado dos quadris, e comece a fazer força com os pés, flexionando os joelhos e elevando o tórax.","Se não causar desconforto no pescoço, deixe a cabeça cair para trás. Respire profundamente cinco vezes nessa posição e, em seguida, acomode os ossos dos glúteos no solo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da linha na agulha', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/THREAD_THE_NEEDLE/heroImage_BBtOcRJ.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_080-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'OBLIQUES, LOWER_BACK, HAMSTRINGS, QUADS, GLUTES', 'Essa posição calmante é ótima para abrir os ombros, tórax e pescoço. Acredita-se que a torção suave estimule a digestão.', '["Comece sobre os quatro apoios.","Estenda o braço direito embaixo do corpo, para a esquerda.","Solte o ombro e a têmpora direita no chão. Seus quadris deverão afundar um pouco para trás em direção aos calcanhares.","Permaneça com a mão esquerda onde estiver ou engatinhe a mão um pouco para a direita no chão acima da cabeça. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura vigorosa', 'QUADS', '', 'https://connect.garmin.com/images/exercises/images/THUNDERBOLT/heroImage_BBtO59V.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_082-A2.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HIPS', 'A postura vigorosa, também conhecida como "Postura diamante", é uma ótima alternativa para a Postura fácil sentada para fins de meditação, respiração e  centralização.', '["Comece ajoelhando-se sobre as canelas, com as mãos pressionadas contra as coxas.","Alongue-se desde o cóccix passando por todo o tronco até a ponta da cabeça, em seguida projete ligeiramente seu queixo para baixo em direção à clavícula."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Posição do diamante com alongamento dos braços', 'QUADS', '', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_083-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_083-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HIPS', '', NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do triângulo', 'QUADS', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/TRIANGLE/heroImage_BBtOhui.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_085-A3.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'HAMSTRINGS, ABS, LOWER_BACK, ADDUCTORS, ABDUCTORS', 'Essa é a décima segunda das doze posturas básicas da Hatha ioga. Acredita-se que a postura do triângulo (tradução literal do nome sânscrito) alivia o estresse e ansiedade ao mesmo tempo em que melhora o equilíbrio.', '["Comece na postura do guerreiro II, com a perna direita para frente.","Estique a perna direita para que as duas pernas fiquem retas.","Deixe o rosto virado para a esquerda e flexione o quadril enquanto eleva o braço direito para frente e para baixo, em direção à canela direita. Incline a lateral do tronco para frente, alinhando-a com a perna da frente. Mantenha os dois lados do tronco retos.","Apoie a mão direita na canela direita ou, se houver espaço, leve a ponta dos dedos até o chão no lado de dentro do pé da frente, ou deixe-as apoiadas em um bloco para aumentar a estabilidade. Tome cuidado para não apoiar a mão no joelho.","Estenda o braço esquerdo para o alto e acima dos ombros, em uma linha reta com o braço direito. Olhe para cima em direção ao polegar e respire profundamente pelo menos três vezes nessa posição. Repita o movimento com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da roda', 'SHOULDERS', '', 'https://connect.garmin.com/images/exercises/images/WHEEL/heroImage_BBtOj3z.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_091-B1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Avançado', 'BICEPS, CHEST, TRAPS, CALVES, HAMSTRINGS', 'Comumente chamada de "roda", o nome sânscrito dessa postura pode ser traduzido como "inclinação com o rosto para cima".  Acredita-se que essa postura que envolve o corpo inteiro estimula os sete chacras, o que ajuda a se manter em harmonia.', '["Comece deitado de costas com os joelhos flexionados e os pés apoiados no chão, alinhados com a largura dos quadris. As laterais externas dos pés deverão estar paralelas.","Flexione os cotovelos e coloque as mãos ao lado da cabeça, alinhadas com a largura dos ombros, e os dedos voltados para os ombros.","Pressionando os pés e mãos contra o chão com a mesma intensidade, eleve os quadris e estique os braços. Continue pressionando os pés contra o chão, usando os dedos maiores, e afaste o tórax dos pés. Permaneça nessa posição e respire profundamente pelo menos três vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Variação da postura do guerreiro II', 'QUADS', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/WIDE_SIDE_LUNGE/heroImage_BBtOljh.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_092-A1.mp4', 'mobilidade,yoga,pilates', 'POSE', 'Iniciante', 'ADDUCTORS', 'Scandasana is a warrior pose named after the Hindu God, Skandasana. In this variation, you lift your arms off the ground and stretch them as far as you can. This can create a very powerful feeling of expanse.', '["Comece em pé, inclinado para frente, com as pernas bem abertas, e as mãos apoiadas no chão.","Mantendo as mãos no chão, flexione o joelho direito enquanto estende a perna esquerda.O joelho direito deve estar alinhado com o tornozelo direito.","Flexione o pé esquerdo até que os dedos do pé se voltem para o teto.","Abra o tórax, respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotação de braço semi ajoelhado', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_001_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_001_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Ajoelhe-se com o joelho direito sobre uma superfície acolchoada e o pé esquerdo posicionado na sua frente. Mantenha os braços esticados na frente do corpo.","Balance o braço direito para trás e estenda-o totalmente atrás de você enquanto gira a cintura e o tronco. Mantenha o alongamento e retorne à posição inicial.","Mude a posição da perna para repetir o alongamento com o braço esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mobilização do tornozelo em três direções', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_002_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_002_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Ajoelhe-se com o joelho esquerdo sobre uma superfície acolchoada e o pé direito posicionado na sua frente. Estabilize a mão esquerda em uma bancada ou outra superfície a aproximadamente a altura do ombro e coloque sua mão direita em seu joelho direito.","Dobre o joelho ligeiramente para a direita e estique a perna e o tornozelo para a frente em direção aos dedos dos pés.","Centralize o joelho atrás do pé e repita o alongamento, dobrando a perna e o tornozelo para a frente em direção aos dedos dos pés.","Agora dobre o joelho ligeiramente para a esquerda e repita o alongamento, dobrando a perna e o tornozelo para a frente em direção aos dedos dos pés.","Mude as posições das pernas e dos braços para repetir o alongamento com a perna e o tornozelo esquerdos."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Mobilidade de quadril 90/90 com extensão', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_003_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_003_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Sente-se no chão com a perna direita com o joelho dobrado inteiramente encostada no chão à sua frente, e a perna esquerda com o joelho dobrado atrás de você.","Incline-se para a frente sobre a perna direita com os braços esticados. Em seguida, posicione o tronco na vertical. Coloque as mãos juntas enquanto gira a posição da perna, com a perna esquerda com o joelho dobrado inteiramente encostada no chão à sua frente, e a perna direita com o joelho dobrado atrás de você.","Incline-se para a frente sobre a perna esquerda com os braços esticados.","Repita os movimentos enquanto continua o alongamento para frente e para trás."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do sapo', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_004_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_004_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Posicione-se com os joelhos e cotovelos no chão, inclinando-se ligeiramente para a frente sobre os cotovelos.","Balance gentilmente o corpo para frente e para trás, dobrando os joelhos, a cintura e os cotovelos. Pause ligeiramente para sentir o alongamento a cada finalização do movimento."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Varredura de ombros', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_005_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_005_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Deite-se do lado direito com o braço direito à sua frente e a perna esquerda ligeiramente inclinada para a frente.","Coloque o braço esquerdo sobre o braço direito e, em seguida, gire-o para cima e sobre a cabeça em um movimento de 180 graus. Em seguida, traga-o para cima e por cima do seu corpo até que ele esteja sobre o braço direito novamente.","Deite-se sobre o lado esquerdo do corpo com o braço esquerdo na sua frente para repetir o alongamento com o braço direito."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('‌Rolamento de costas sobre rolo de espuma', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_007_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_007_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Deite-se com as costas em um rolo de espuma, os joelhos dobrados e os pés apoiados no chão. Seus braços devem estar estendidos acima da cabeça.","Dobre os joelhos suavemente para cima e para baixo enquanto rola as costas pelo rolo de espuma."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento do latíssimo do dorso com rolo de espuma', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_010_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_010_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Deite-se do lado esquerdo, com o braço esquerdo esticado acima da cabeça, o braço direito cruzado à frente do corpo e um rolo de espuma sob a axila esquerda.","Pause e mantenha o alongamento.","Repita o alongamento no lado direito com as posições dos braços invertidas para alongar o outro lado do corpo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Afundo de tornozelo', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_006_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_006_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Ajoelhe-se com o joelho direito sobre uma superfície acolchoada e o pé esquerdo no chão. Curve-se para a frente para que sua mão direita fique alinhada ao seu pé esquerdo no chão e sua mão esquerda esteja sobre o seu pé esquerdo.","Movimente o joelho ligeiramente para dentro e dobre-o para a frente para alongar o tornozelo.","Centralize o joelho atrás do pé e repita o alongamento, dobrando a perna e o tornozelo para a frente em direção aos dedos dos pés.","Agora dobre o joelho ligeiramente para a esquerda e repita o alongamento, dobrando a perna e o tornozelo para a frente em direção aos dedos dos pés.","Mude as posições das pernas e dos braços para repetir o alongamento com a perna e o tornozelo esquerdos."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abertura de quadril em T invertido', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_011_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/M_011_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Ajoelhe-se com o joelho esquerdo e o pé direito apoiados no chão. Agache com a mão direita apoiada no chão e o cotovelo esquerdo próximo ao chão perto dela.","Mova o braço esquerdo lentamente para cima e passe-o por cima do corpo, trazendo o tronco para cima junto com ele. Pause e mantenha o alongamento com o braço esquerdo bem esticado para cima.","Retorne à posição inicial. Mude as posições das pernas e dos braços para fazer o alongamento com o braço direito."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento dos tríceps', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_019_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_019_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Fique com o corpo reto com os pés afastados na largura dos ombros. Dobre o braço esquerdo no cotovelo e coloque-o atrás do pescoço. Segure o cotovelo esquerdo com a mão direita.","Ainda segurando o cotovelo esquerdo com a mão direita, dobre a cintura lentamente para a direita. Pause e retorne à posição inicial.","Mude as posições do braço e da mão (segurando o cotovelo direito com a mão esquerda) e repita o movimento, desta vez dobrando-se para a esquerda. Retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rotação de ombros', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_017_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_017_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Fique com o corpo reto com os pés afastados na largura dos ombros.","Role suavemente os ombros para trás em um movimento de encolhimento dos ombros."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Aberturas de peito', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_018_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_018_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Fique com o corpo reto com os pés afastados na largura dos ombros. Mantenha os braços esticados à sua frente com as mãos juntas.","Seguindo uma linha reta, abra suavemente os braços para fora para os dois lados. Pause e, em seguida, retorne os braços à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento da parte superior das costas', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_021_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_021_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Fique com o corpo reto com os pés afastados na largura dos ombros. Mantenha os braços estendidos à sua frente e junte as mãos de forma que os nós dos dedos fiquem voltados para você e os dedos entrelaçados.","Afaste os braços e as mãos do corpo, como se estivesse estalando os nós dos dedos. Dobre a parte superior das costas ligeiramente para a frente enquanto alonga. Em seguida, retorne à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento de tornozelo', '', '', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_025_CamA.jpg', 'https://connectvideo.garmin.com/msn-workout/Mobility/MA_025_CamA.mp4', 'mobilidade', 'WARM_UP', 'Iniciante', '', '', '["Sente-se com as costas retas. Mantenha a perna direita no chão enquanto estende a perna esquerda à sua frente.","Gire o pé movendo o tornozelo para frente e para trás, alinhado à perna. Pause e, em seguida, repita o movimento com a outra perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do barco', '', '', 'https://connect.garmin.com/images/exercises/images/BOAT/heroImage_BBtOcRf.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_004-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Boat pose strengthens your abdominals, back, hips, and thighs, and can help improve concentration and balance.', '["Comece sentado sobre o tapete com os joelhos flexionados à frente e os pés apoiados nos chão.","Com as palmas voltadas para cima, estenda os braços para frente de forma que as mãos relem nas laterais dos joelhos.","Incline-se para trás até que o tronco esteja a um ângulo de 45 graus em relação ao chão.","Levante lentamente os pés do chão ao mesmo tempo estendendo as pernas, formando um V.","Abra o tórax e contraia os músculos abdominal para se manter nessa posição.Permaneça assim respirando profundamente por pelo menos três vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura entrelaçada do ângulo', '', '', 'https://connect.garmin.com/images/exercises/images/BOUND_ANGLE/heroImage_BBtOfki.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_005-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa posição é conhecida por aumentar a fertilidade e aliviar o nervo ciático.', '["Comece sentado na Postura do bastão.","Flexione seus joelhos amplamente para os lados e una as solas dos pés aproximadamente de 30 a 60 cm à sua frente.","Segure seus tornozelos com as mãos. Inspire profundamente alongando sua coluna e, em seguida, curve o tronco para frente até onde ainda se sentir confortável.","Abaixe a cabeça e relaxe os ombros."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sentada em ângulo com uma perna', '', '', 'https://connect.garmin.com/images/exercises/images/BOUND_SEATED_SINGLE_LEG_FORWARD_BEND/heroImage_BBtOsAi.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_006-A1.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Essa é a posição dedicada ao sábio Marichi, conhecido como pai da humanidade.', '["Comece sentado na Postura do bastão.","Flexione o joelho direito e posicione o pé direito no chão o mais próximo possível do osso ísquio, enquanto estiver confortável.","Incline-se ligeiramente para frente e estenda o braço direito na frente da canela direita. Gire o braço para dentro de forma que o polegar se volte para baixo e a palma se volte para longe do você. Flexione o cotovelo direito para levar a mão atrás, apoiando-a nas costas.","Estenda o braço esquerdo atrás e, com a mão direita, segure o pulso da outra mão. Sua mão esquerda pode estar na forma de gyan mudra (polegar e dedo indicador unidos). Seu pé esquerdo pode estar flexionado ou ligeiramente apontado.","Incline-se para frente flexionando os quadris, alongando a coluna enquanto relaxa a cabeça em direção à perna. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do arco', '', '', 'https://connect.garmin.com/images/exercises/images/BOW/heroImage_BBtOlkn.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_007-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'This is the eighth of the 12 basic Hatha Yoga postures. Bow pose is so called because it resembles an archer''s bow. This backbend opens the front of the body.', '["Comece deitado de bruços.","Flexione os joelhos e segure os tornozelos com as mãos.","Empurre os pés para longe da cabeça, como os tornozelos nas mãos, mantendo os joelhos separados pela largura dos quadris, e tire o tórax do chão. Respire fundo nessa posição por pelo menos três vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cadáver', '', '', 'https://connect.garmin.com/images/exercises/images/CORPSE/heroImage_BBtOj4W.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_014-A5.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Corpse pose is traditionally performed at the end of an asana practice. Its stillness allows you to appreciate all of the space and openings that you created in your body and mind.', '["Deite-se de costas.","Deixe os pés separados na largura dos quadris ou na largura das bordas externas do colchonete. As pontas dos pés devem ficar relaxadas para fora.","Deixe os braços relaxados nas laterais do corpo, as palmas para cima em um gesto de receptividade. Respire fundo algumas vezes pelo nariz e expire pela boca para liberar até a última gota de esforço do seu corpo ou da sua mente. Respire profundamente pelo menos vinte vezes nessa posição, ou mais se preferir."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da meia-lua inclinada', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/BOWED_HALF_MOON/heroImage_BBtOsBq.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_008-A3.mp4', 'yoga,pilates', 'POSE', 'Avançado', '', 'Essa variação revigorante da postura da meia-lua desafia a habilidade para se equilibrar. Acredita-se que a retroflexão da coluna aumenta a habilidade de respirar profundamente.', '["Comece na Postura do guerreiro III, apoiado na perna direita e com as duas mãos no chão ou em blocos, alinhadas com os ombros.","Mantenha a ponta dos dedos da mão direita no chão, ou no bloco, bem abaixo do ombro direito.Abra o lado esquerdo do quadril até ficar acima do direito, girando o tronco para a esquerda. Eleve o braço esquerdo em linha reta e olhe para cima em direção aos dedos da mão esquerda.","Flexione o joelho esquerdo e segure o pé esquerdo com a mão esquerda, pressionando levemente o pé contra a mão para abrir as costas. Mantenha o joelho alinhado com os quadris.","Incline-se para trás e abra o tórax. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cabeça de vaca', '', '', 'https://connect.garmin.com/images/exercises/images/COW_FACE/heroImage_BBtOnpX.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_015-A1.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Diz-se que a tradução do sânscrito da postura da "Cabeça de vaca" recebeu esse nome por causa de seu aspecto: Os joelhos representam os lábios e os cotovelos representam as orelhas. Essa posição foi uma das 15 posturas incluídas no texto revolucionário de prática da yoga física, o Pradipika Hatha Yoga.', '["Comece posicionado sobre as mãos e os joelhos.","Cruze o joelho direito na frente do esquerdo, abrindo os pés para fora, nas laterais.","Utilize as mãos gentilmente para trazer os ossos ísquios ao chão, sentando-se entre os calcanhares.","Estenda o braço esquerdo para cima e flexione o cotovelo de forma que a mão esquerda caia sobre as costas, entre as escápulas.","Estenda a mão direita para trás e flexione o cotovelo direito entrelaçando as mãos.  Se suas mãos não alcançarem uma à outra, segure a parte de trás da camiseta ou utilize uma faixa.","Mantenha-se ereto e respire profundamente, em seguida curve-se para frente a partir dos quadris até dobrar o corpo. Respire profundamente por pelo menos três vezes, soltando os braços caso sinta os ombros começarem a tensionar. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sobre os quatro apoios', '', '', 'https://connect.garmin.com/images/exercises/images/ALL_FOURS/heroImage_BBtOq19.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_001-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa postura básica é um ponto de partida para ajudá-lo a desenvolver força e controle e assim poder avançar para posturas mais desafiadoras.', '["Comece se ajoelhando com os joelhos na mesma distância dos quadris.","Caminhe suas mãos para frente até que estejam alinhadas com os ombros abaixo e os joelhos alinhados com os quadris.","Com o queixo ligeiramente projetado em direção à clavícula, mantenha o pescoço alinhado com a coluna. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de prancha de antebraços', '', '', 'https://connect.garmin.com/images/exercises/images/DOLPHIN_PLANK/heroImage_BBtOcTR.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_018-C2.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Conhecida como "prancha de antebraços", essa postura fortalece o core. Para aqueles com lesão no punho, é uma alternativa para a prancha tradicional, pois você descansa o peso nas palmas das mãos.', '["Comece sobre os quatro apoios.","Abaixe os antebraços no chão, para que os cotovelos fiquem alinhados com os ombros.Os antebraços podem ficar paralelos um ao outro, com as palmas das mãos viradas para baixo, ou você pode juntar as mãos.","Firme a ponta dos pés, eleve os joelhos e estique as pernas para trás. Leve os calcanhares para trás enquanto faz força para a frente com o topo da cabeça, mantendo a coluna alongada. Puxe o umbigo para dentro e respire fundo nessa posição por pelo menos três vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do guerreiro devocional', '', '', 'https://connect.garmin.com/images/exercises/images/DEVOTIONAL_WARRIOR/heroImage_BBtOq2o.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_017-A3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Não reconhecida como uma postura do guerreiro tradicional, essa variação do guerreiro é muito usada e seu nome deriva da posição de devoção.', '["Comece na postura do guerreiro II, com a perna direita para frente.","Deixe suas mãos cair para trás e junte-as atrás do sacro. Inspire profundamente para abrir o tórax.","Ao expirar, incline-se em volta do joelho direito.","Deixe a cabeça cair em direção ao chão, permitindo que a gravidade faça o trabalho. Mantenha os quadris encaixados e deixe o pescoço livre. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para baixo e joelho no nariz', '', '', 'https://connect.garmin.com/images/exercises/images/DOWN_DOG_KNEE_TO_NOSE/heroImage_BBtOj39.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_020-B1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa variação da Postura do cachorro olhando para baixo fortalece o core e também ajuda a desenvolver mobilidade, pois é preciso colocar um pé para frente entre as mãos.', '["Comece na Postura do cachorro olhando para baixo.","Eleve a perna direita para alto até a postura do cachorro olhando para baixo com perna elevada.","Flexione o joelho direito e leve-o até o nariz, empurrando a canela em direção à coluna. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da águia', '', '', 'https://connect.garmin.com/images/exercises/images/EAGLE/heroImage_BBtOsBG.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_024-A4.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Essa postura, cujo nome se deve ao rei dos pássaros, Garuda,  lembra o formato de uma águia alçando voo. Essa postura fortalece os membros inferiores, abre os ombros e melhora o equilíbrio e a concentração.', '["Comece com os joelhos semiflexionados, transfira seu peso para a perna esquerda e abrace o joelho direito contra o tórax.","Cruze a coxa direita na frente da esquerda, prendendo o pé direito na lateral do tornozelo ou da canela esquerda (cruze uma ou duas vezes, o que o joelho permitir), e projete os dedos do pé para baixo.","Enrole o braço direito atrás do esquerdo e junte as palmas das mãos, com as pontas dos dedos voltadas para cima.","Sente-se em posição baixa, mantendo os quadris encaixados, e corrija a postura com o apoio dos cotovelos e pontas dos dedos.","A parte de cima dos braços deverão estar paralelas ao chão, e as pontas dos dedos devem ficar distantes do rosto para que os ombros se abram. Respire profundamente cinco vezes nessa posição. Relaxe e então repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura fácil', '', '', 'https://connect.garmin.com/images/exercises/images/EASY_SEATED/heroImage_BBtSCR5.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_025-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'A Postura Confortável é recomendada para meditação.', '["Comece sentando-se na Postura do Bastão.","Cruze uma canela na frente da outra, joelhos bem separados e calcanhares embaixo dos joelhos opostos.","Deixe que suas mãos relaxem em suas coxas, com as palmas voltadas para cima para obter mais energia ou voltadas para baixo para imobilização.","Contraia e puxe as escápulas para baixo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do bastão em quatro apoios', '', '', 'https://connect.garmin.com/images/exercises/images/FOUR_LIMBED_STAFF/heroImage_BBtOq3H.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_030-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Also referred to as Plank Halfway Down, this pose assumes the same position as a Triceps Pushup. It builds upper body and core strength. Danda in Sanskrit means "staff," which refers to the spine, or support of the entire body. This pose is an essential part of the advanced Sun Salutation and often part of what is referred to as a "vinyasa" or "flow," which practitioners are often encouraged to practice on the way back to Down Dog.', '["Comece na posição de prancha.","Alongue as pernas para trás, puxe o umbigo para dentro e relaxe os cotovelos, colocando-os para trás até que seus antebraços toquem levemente as laterais da caixa torácica. Alongue a coluna e mantenha o queixo ligeiramente para baixo. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do peixe', '', '', 'https://connect.garmin.com/images/exercises/images/FISH/heroImage_BBtOq3r.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_029-B2.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa é a quarta das doze posturas básicas da Hatha ioga. A postura do peixe é geralmente incluída em uma sequência como uma postura oposta à da vela.', '["Comece sentado com as pernas estendidas à sua frente.","Leve as mãos — com as palmas no chão e pontas dos dedos voltadas para frente — atrás dos glúteos, aproximando os cotovelos um do outro.","Flexione os cotovelos, apoie os antebraços no chão e incline-se sobre eles, mantendo um paralelo ao outo.","Eleve o tórax em direção ao teto para que suas costas se arqueiem. Deixe sua cabeça descansar apoiada no chão.Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura de abertura total', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/FULL_SPLIT/heroImage_BBtOj11.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_031-A1.mp4', 'yoga,pilates', 'POSE', 'Avançado', '', 'Também referido como "Postura do macaco", essa posição é traduzida do sânscrito como "Postura dedicada a Hanuman, o deus Macaco". Hanuman é considerado como o devoto supremo que pulou de ilha em ilha para recuperar o amor dos devotados, explicando a posição das pernas.', '["Comece na posição baixa do afundo com seu pé direito para frente.","Libere o joelho esquerdo no chão.","Caminhe com as mãos para trás enquanto empurra os quadris para trás em direção ao calcanhar esquerdo e alongue a perna direita, como na postura do corredor. Os dedos das mãos, abertos e esticados, podem estar apoiados no chão ou suas mãos podem estar sobre blocos.","Respire nessa posição, em seguida deslize o calcanhar direito para frente até onde ainda esteja confortável. Mais à frente, seus quadris irão se soltar alinhadamente  sobre o chão.","Permaneça nessa posição respirando fundo por pelo menos três vezes, saia lentamente da posição, em seguida repita no lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cadeira com tornozelo no joelho', '', '', 'https://connect.garmin.com/images/exercises/images/HALF_CHAIR_HALF_ANKLE_TO_KNEE/heroImage_BBtOsBy.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_033-A3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa postura em pé que abre os quadris permite escolher sua amplitude de movimento, além de melhorar a estabilidade e equilíbrio.', '["Comece na posição em pé, na Postura da montanha.","Flexione os joelhos, empurre os quadris para baixo e para tr[as, como se estivesse se sentando em uma cadeira, e eleve os braços para o alto até que fiquem nas laterais do rosto.","Transfira seu peso para a perna direita e abrace a perna esquerda contra o tórax.","Cruze o tornozelo esquerdo com o joelho direito. Flexione o pé esquerdo para proteger seu joelho. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da meia-lua', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/HALF_MOON/heroImage_BBtOhun.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_034-A3.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', '"Chandra" significa "lua". Tanto o sol quanto a lua são importantes elementos simbólicos da ioga. A lua simboliza a energia feminina. A ioga busca equilibrar o feminino e o masculino. Essa é uma postura que exige certo equilíbrio e força.', '["Comece na postura do guerreiro III, apoiado na perna direita e com as duas mãos no chão, alinhadas com os ombros.","Mantenha a ponta dos dedos da mão direita no chão e abra o lado esquerdo do quadril até ficar acima do direito, girando o tronco para a esquerda.","Eleve o braço esquerdo em linha reta e olhe para cima em direção aos dedos da mão esquerda.Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do herói', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/HEROS/heroImage_BBtOfke.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_036-A2.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa posição aumenta a flexibilidade das pernas ao abrir as coxas e os joelhos. Caso se sinta confortável nessa posição, você pode utilizá-la como posição alternativa para a meditação.', '["Comece em uma posição sentado sobre os joelhos.","Posicione suas palmas no chão à sua frente e eleve seus quadris ligeiramente, de forma que você possa abrir os calcanhares levando-os para os lados.","Gentilmente, reposicione os ossos ísquios embaixo, de forma a se sentar sobre a parte interna dos calcanhares, com os dorsos dos pés no chão.","Alongue-se através da coluna e una as costelas da frente."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da garça', '', 'Faixa', 'https://connect.garmin.com/images/exercises/images/HERON/heroImage_BBtOlj2.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_037-A1.mp4', 'yoga,pilates', 'POSE', 'Avançado', '', 'Semelhante a seu homônimo, a garça, essa  posição é incrivelmente graciosa. Essa postura está inclusa em ambas as formas de ioga, Ashtanga e Bikram.', '["Comece sentado na Postura do bastão.","Flexione o joelho esquerdo e posicione o dorso do pé no chão bem do lado externo do glúteo esquerdo.","Flexione o joelho direito e segure as beiras do pé com ambas as mãos.","Empurre gentilmente o calcanhar para cima, alongando a perna direita.","Puxe os ombros para baixo e para trás, e eleve o tórax, inclinando-se ligeiramente para trás. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da saudação com oito apoios', '', '', 'https://connect.garmin.com/images/exercises/images/KNEES_CHEST_CHIN/heroImage_BBtOlkk.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_039-A2.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Tradução do nome sânscrito, a postura da saudação com oito apoios é usada às vezes como uma variação iniciante da postura dos quatro apoios. Essa postura é um dos movimentos com retroflexão da coluna da saudação ao sol.', '["Comece na Postura de prancha.","Em seguida, flexione os joelhos e leve-os suavemente para o chão.","Flexione os cotovelos para que eles se aproximem das laterais da caixa torácica. Arqueie a coluna e abaixe o tórax e o queixo, apoiando-os no chão. Deixe os ombros e tórax alinhados com as mãos, e os cotovelos projetados para cima. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do gafanhoto', '', '', 'https://connect.garmin.com/images/exercises/images/LOCUST/heroImage_BBtOcTh.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_041-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa é a décima sétima das doze posturas básicas da Hatha ioga. Essa retroflexão da coluna exige mais força do core que as outras, pois não há apoio de nenhum dos membros do corpo.', '["Comece deitado de bruços no tapete, com os pés juntos.","Segure as mãos atrás do sacro.","Inspire profundamente para tirar o tórax e os pés do chão. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da sereia', '', 'Faixa, Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/MERMAID/heroImage_BBtOlir.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_045-A1.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Esse exercício de quadris flexionado para trás e de abertura de ombros é uma versão intermediária da Postura completa do pombo real. O nome Postura da sereia deriva-se da semelhança da perna traseira com uma cauda de sereia.', '["Comece na posição do cão.","Estenda sua perna direita para cima para a posição do cachorro embaixo com três pernas, abra os quadris e flexione o joelho.","Arraste a canela direita para frente em direção à frente do tapete, com a qual sua perna ficará o mais paralela possível. Abaixe os quadris ao chão para a posição do pombo com a perna estendida.","Flexione o joelho esquerdo e segure o pé direito, posicionando-o na dobra do cotovelo esquerdo. Em seguida, tente alinhar os quadris.","Estique o braço direito para o teto pela lateral do rosto e, em seguida, flexione o cotovelo direito estendendo a mão direita atrás para entrelaçá-la com a esquerda. Use uma faixa se suas mãos não alcançarem a posição desejada. Respire profundamente pelo menos três vezes nessa posição. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do pombo com uma perna estendida', '', '', 'https://connect.garmin.com/images/exercises/images/ONE_LEGGED_PIGEON/heroImage_BBtOnq1.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_048-B1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Traduzido do sânscrito, a Postura do pombo com uma perna estendida é a parte relacionada à perna na posição da: Postura do pombo real com uma perna. Auxilia de maneira fácil a abrir os quadris no caso de principiantes e é recomendada para atletas.', '["Comece na posição do cão.","Traga sua canela direita para frente, posicionando-a o mais próximo e paralelo à extremidade do tapete que puder. Seu joelho direito deverá estar voltado na direção do pulso direito e o tornozelo direito em direção ao pulso esquerdo.","Com sua perna traseira estendida atrás de você e os dedos dos pés alojados no tapete, abaixe os quadris ao chão.","Engatinhe as mãos para frente até que sua cabeça esteja no chão. Respire profundamente pelo menos três vezes nessa posição. Repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da montanha', '', '', 'https://connect.garmin.com/images/exercises/images/MOUNTAIN/heroImage_BBtOcRO.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_046-C1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Por ser utilizada em quase todo estilo de yoga como uma posição de trasição, a Postura da montanha parece ser simples. Entretanto, uma multiplicidade de ajustes nos alinhamentos torna essa posição complexa. O nome foi dado devido à forte robustez de uma montanha com a qual  a posição se assemelha.', '["Posicione-se em pé na frente do tapete com os dedões dos pés tocando-se um ao outro e as bordas externas dos pés paralelas. Seu peso deverá estar distribuído uniformemente, de forma que todos os quatro cantos dos pés estejam em contato com o chão.","Relaxe os braços e as mãos nas laterais com as palmas voltadas para fora em um gesto de receptividade.","Mantenha o pescoço alongado, a parte de trás do crânio levantada - como se um balão estivesse preso junto a ela - e o queixo nivelado com o chão.","Una as escápulas e as costelas frontais. O cóccix deve se alongar para baixo em direção ao chão.","Mantenha as pernas retas, mas com uma ligeira flexão para evitar a hiperextensão.Mantenha o rosto, as mandíbulas e os olhos suavizados. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do guerreiro da paz', '', '', 'https://connect.garmin.com/images/exercises/images/PEACEFUL_WARRIOR/heroImage_BBtOcSA.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_049-B3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Às vezes chamado de "guerreiro invertido", o nome "guerreiro da paz" deve-se à sua posição aberta e vulnerável. Essa postura é muito comum nas várias linhas de ioga. É um movimento que abre suavemente as laterais, e acredita-se que aumenta a capacidade dos pulmões permitindo respirações mais profundas.', '["Comece na postura do guerreiro II, com a perna direita para frente.","Vire as palmas das mãos em direção ao teto.","Incline-se para trás dobrando o lado esquerdo da cintura. Deixe o dorso da mão esquerda descansar na perna esquerda e eleve o braço direito em direção ao teto. Fixe o olhar no teto.","Abra o tórax levemente em direção ao teto.  Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Inversão sobre os ombros', '', '', 'https://connect.garmin.com/images/exercises/images/PLOW/heroImage_BBtOllg.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_051-A2.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa é a terceira das doze posturas básicas da Hatha ioga. Esta postura recebeu este nome devido a sua forma.  Esta postura é habitualmente praticada no final de uma série de ioga, e, muitas vezes junto com a postura da vela, quando acredita-se que as costas se beneficia da flexibilidade que a prática de ioga anterior trouxe consigo. No entanto, essa postura pode ser muito cansativa para o pescoço e ombros. Portanto, evite-a se tiver problemas de coluna ou sentir dor.', '["Comece deitado de costas com os joelhos flexionados, os pés apoiados no chão, e os braços nas laterais do corpo.","Solte os joelhos e faça força com os braços no chão para elevar os pés em direção ao teto.Respire nessa posição.","Deixe seus pés cairem para trás até onde for confortável para o seu pescoço.","Junte as mãos atrás de você no chão e encaixe os ombros por debaixo, um de cada vez.Apoie-se firmemente com os braços e alongue-se até os tonozelos. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da meia-lua com rotação de tronco', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/REVOLVED_HALF_MOON/heroImage_BBtOhuu.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_054-B3.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Essa postura que desafia o equilíbrio fortalece o corpo inteiro, aumenta a consciência corporal, e acredita-se que seja desintoxicante.', '["Comece em pé, inclinado para frente.","Eleve a perna esquerda para ficar com a perna direita na Postura do guerreiro III, com as duas mãos no chão.","Mantenha a ponta dos dedos da mão esquerda apoiada no chão e eleve e braço direito em direção ao teto.","Olhe para a mão de cima. Rotacione internamente a coxa esquerda e pressione os dedos do pé contra o chão. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da cabeça no joelho com torção', '', '', 'https://connect.garmin.com/images/exercises/images/REVOLVED_HEAD_TO_KNEE/heroImage_BBtOnqF.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_055-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'A postura da cabeça no joelho com torção abre os ombros, o tronco, os músculos posteriores das coxas e mais. A abertura do tórax que essa posição proporciona permite que uma respiração mais profunda e facilitada.', '["Comece na posição sentada.","Estenda sua perna esquerda e posicione o pé direito na parte interna da coxa esquerda.","Incline-se para a esquerda e solte o antebraço esquerdo ao chão no lado interno da canela, de forma que seu braço e a canela estejam alinhados e as pontas dos dedos estejam apontados para longe de você.","Inspire e estique o braço direito para cima em direção ao teto. Expire e tombe para a esquerda. Respire nessa posição.","Se houver mais espaço, leve a mão direita para a borda externa do pé direito, e a mão esquerda para a parte interna do pé direito.","Respire fundo nessa posição por três vezes: alongue a coluna cada vez que inspirar, e abra o tórax em direção ao teto um pouco mais cada vez que expirar."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do triângulo com rotação de tronco', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/REVOLVED_TRIANGLE/heroImage_BBtOsBp.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_056-A3.mp4', 'yoga,pilates', 'POSE', 'Avançado', '', 'Essa variação da postura do triângulo com rotação de tronco oferece os mesmos benefícios, além de se acreditar que melhora a digestão e a coordenação.', '["Comece com o corpo flexionado para frente e apoiado na perna direita à frente.","Apoie a mão esquerda no chão, no lado de dentro da perna direita, e alinhada com o ombro esquerdo. Eleve o braço direito em direção ao teto, fazendo uma linha reta com os braços.","Olhe para cima em direção ao polegar e gire o tronco para trás, abrindo o tórax  em direção ao teto. Estique a coluna a cada vez em que inspirar, e gire o tórax para trás a cada vez em que expirar. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura sentada fácil com inclinação lateral', '', '', 'https://connect.garmin.com/images/exercises/images/SEATED_EASY_SIDE_BEND/heroImage_BBtOj0G.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_058-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Esse movimento alonga e abre as laterais do tronco.', '["Comece na postura fácil sentada com os braços relaxados em ambos os lados.","Estenda seu braço esquerdo para o teto, ao lado do rosto.","Leve sua mão direita ao chão e avance lentamente para a direita, direcionando o antebraço para o chão. Em seguida, incline o tronco para a direita.","Gire seu tórax para cima, abrindo-o em direção ao teto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Invertida sobre os ombros', '', '', 'https://connect.garmin.com/images/exercises/images/SHOULDER_STAND/heroImage_BBtOj4I.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_062-A3.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Essa é a segunda das doze posturas básicas da Hatha ioga. A posição de invertida sobre os ombros é poderosa e diz-se que estimula a glândula da tireóide e rejuvenesce o corpo todo.', '["Deite-se de costas no chão com os joelhos flexionados, pés apoiados no chão e os braços em cada lado do corpo.","Solte os joelhos e faça força com os braços no chão para elevar os pés em direção ao teto, e depois atrás de você tão longe quanto for confortável para o seu pescoço.","Para ficar na postura, coloque as mãos na região lombar como suporte e tente manter os cotovelos na largura dos ombros.","Relaxe os joelhos e eleve os pés, um de cada vez, em direção ao teto, alongando as pernas quando se sentir confortável. Respire profundamente pelo menos três vezes nessa posição. Para sair da posição, relaxe os joelhos em direção a testa, volte a inversão, e, usando os braços como freios, lentamente desça as costas no colchonete vértebra por vértebra."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do barco lateral', '', '', 'https://connect.garmin.com/images/exercises/images/SIDE_BOAT/heroImage_BBtStuX.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_063-A2.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Esta variação do Postura do Barco é particularmente eficaz para atingir os oblíquos.', '["Comece na Postura do Barco.","Flexione os joelhos.","Mova os joelhos para a direita enquanto estende os braços para a esquerda.","Abaixe-se lentamente sobre a lateral do quadril.","Faça pelo menos três respirações profundas, depois suba pelo centro e repita do outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da esfinge', '', '', 'https://connect.garmin.com/images/exercises/images/SPHINX/heroImage_BBtOj3f.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_065-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'A postura da esfinge é uma suave retroflexão da coluna, que é uma alternativa à postura da cobra para aqueles que sofrem com dores no punho ou que não desejam hiperestender tanto a coluna. Essa postura permite uma respiração mais profunda e acredita-se que aumenta a confiança.', '["Comece deitado de bruços com os dedos dos pés juntos e os braços ao lado do corpo.","Alinhe os cotovelos bem abaixo dos ombros e deixe os antebraços paralelos um ao outro.","Empurre o tórax para frente entre os braços, empurrando os ombros para baixo e alinhados com as costas. Pressione levemente a pelve contra o chão. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura dos braços em cima', '', '', 'https://connect.garmin.com/images/exercises/images/STANDING_ARMS_UP/heroImage_BBtOq1w.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_069-A4.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'A tradução do sânscrito é "Postura das mãos para cima". Essa postura de abertura alonga e energiza o corpo desde a ponta dos pés até as pontas dos dedos das mãos elevadas. É ótima para despertar a mente e o corpo.', '["Comece na posição em pé, na Postura da montanha.","Inspire profundamente para estender os braços para fora nas laterais e depois acima da cabeça.","Pressione as palmas uma contra a outra e olhe para cima para os dedos polegares. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do bastão', '', '', 'https://connect.garmin.com/images/exercises/images/STAFF/heroImage_BBtOq0u.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_068-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'A postura do bastão é extremamente conectada aos fundamentos terrestres, sendo a base para muitas posições sentadas na ioga.', '["Comece em uma posição sentada com suas pernas estendidas e unidas à sua frente, flexionando os pés.","Pressione as palmas das mãos no chão nas laterais dos quadris, em seguida empurre seus ombros para baixo e para trás, longe da orelhas.","Sinta seus ossos ísquios, ou ossos para assento, firmemente em contato com o chão, e alongue completamente a coluna mantendo o queixo ligeiramente projetado para baixo em direção à clavícula."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do pé para o alto', '', 'Blocos de ioga', 'https://connect.garmin.com/images/exercises/images/STANDING_SPLIT/heroImage_BBtOhuN.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_075-A4.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Translating to "One Foot Extended Upward," this standing split pose lengthens the body from the ankle to the neck. It lengthens, strengthens, improves balance, and energizes.', '["Comece em pé, inclinado para frente, com as mãos apoiadas no chão.","Transfira seu peso para o pé esquerdo, eleve a perna direita para o alto e abra o lado direito dos quadris. Aponte com os dedos do pé para o teto.","Leve as mãos (no chão ou em blocos) para trás, juntando-as aos dedos do pé, e solte a cabeça. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura da árvore', '', '', 'https://connect.garmin.com/images/exercises/images/TREE/heroImage_BBtOsBs.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_084-A3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa postura de força e equilíbrio melhora tanto a postura quanto a concentração. Fica-se em pé e ereto como uma árvore. Mas as árvores se mexem e balançam com o vento, elas não são rígidas e estáticas, assim como não devem ser suas articulações. Controle o equilíbrio de forma leve e suave.', '["Comece na posição em pé, na Postura da montanha.","Transfira seu peso para o pé direito, flexione o joelho esquerdo e abra a perna para a esquerda desde o quadril.","Com o quadril aberto, apoie a planta do pé esquerdo no lado de dentro da coxa direita ou na canela (não no joelho).","Junte as mãos no centro do tórax, em gesto de saudação. Fique ereto encaixando o cóccix e abaixe os ombros alinhando-os com as costas. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do cachorro olhando para cima', '', '', 'https://connect.garmin.com/images/exercises/images/UP_DOG/heroImage_BBtOnsA.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_086-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Commonly confused with the Cobra pose, the main difference is that in the Up Dog pose, only your hands and the tops of your feet are touching the ground. Up Dog requires more strength than Cobra.', '["Comece deitado de bruços com o dorso dos pés apoiados no chão.","Posicione as mãos nos dois lados do tórax, flexionando os cotovelos e encostando-os nas laterais da caixa torácica.","Pressione as palmas das mãos contra o chão, eleve o tórax tentando ir além dos ombros. Pressione os pés contra o chão para elevar as coxas e joelhos até que apenas as mãos e o dorso dos pés estejam no chão. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do alongamento frontal', '', '', 'https://connect.garmin.com/images/exercises/images/UPWARD_FACING_PLANK/heroImage_BBtOnsP.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_087-A1.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'This pose translates to "Intense Stretch of the East;" East referring to the how it stretches, or ''opens'', the front of the body. It is the opposite of Pascimottanasana, "Intense Stretch of the West."', '["Comece sentado com as pernas unidas e estendidas à sua frente.","Coloque as mãos atrás de você, e os dedos apontando em direção ao corpo. Faça força com as palmas das mãos ao elevar os quadris.Mantenha os dedões dos pés juntos e coloque todo o pé no chão.","Levante-se usando o tórax e deixe a cabeça cair para trás se for confortável para o pescoço. Respire profundamente pelo menos três vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do guerreiro I', '', '', 'https://connect.garmin.com/images/exercises/images/WARRIOR_ONE/heroImage_BBtOfln.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_088-A3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Essa postura materializa a força e graça de um guerreiro espiritual. A postura do guerreiro é uma das primeiras aprendidas pelos inciantes na ioga, mas uma das últimas posturas a serem completamente dominadas até mesmo pelos praticantes mais experientes.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos, colocando-se na postura equestre.","Apoie o calcanhar esquerdo no chão com o pé levemente projetado para fora.","Pressione os pés contra o chão e eleve os braços em direção ao teto, deixando-os ao lado do rosto. Encaixe os quadris rotacionando internamente a coxa.","Olhe levemente para cima, abra o tórax e respire profundamente pelo menos três vezes nessa posição. Repita o movimento com o lado esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do guerreiro III', '', '', 'https://connect.garmin.com/images/exercises/images/WARRIOR_THREE/heroImage_BBtOljw.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_090-A3.mp4', 'yoga,pilates', 'POSE', 'Intermediário', '', 'Essa é a terceira das três posturas do guerreiro, e seu nome é em homenagem ao bravo guerreiro, Virabhadra. O movimento desafia o equilíbrio, gera força e melhora a concentração.', '["Comece em pé, inclinado para frente.","Caminhe as mãos no chão, levando-as para frente até se alinharem com os ombros.","Com os joelhos semiflexionados, transfira seu peso para o pé esquerdo e levante a perna direita para o alto atrás de você.","Empurre o calcanhar direito para trás (como se estivesse pressionando algo) e rotacione internamente a coxa direita para que o dedo do pé fique voltado para o chão.","Retire os braços do chão e eleve-os para frente, ficando ao lado do rosto. Respire fundo nessa posição por pelo menos três vezes, em seguida repita no outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Arm Circles (with ball, band and weight)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_004-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_004-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se ereto em uma Bola Suíça com os pés firmemente apoiados no chão. Enrole uma faixa de elástico em torno de suas costelas e enrole as extremidades em torno de halteres de 1 a 3 kg.","Levante os braços para os lados, para que fiquem paralelos ao chão.","Mantenha o corpo em uma posição fixa enquanto faz pequenos círculos rápidos com os braços."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Belly Breathing', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_008-C5.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_008-C5.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas e coloque a mão direita na barriga.","Inspire pelo nariz e expire pela boca lentamente."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Postura do guerreiro II', '', '', 'https://connect.garmin.com/images/exercises/images/WARRIOR_TWO/heroImage_BBtOnrD.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_089-A3.mp4', 'yoga,pilates', 'POSE', 'Iniciante', '', 'Virabhadrasana é o nome de um bravo guerreiro que seria a reencarnação do deus Shiva. Essa postura abre os quadris e, das três posturas do guerreiro, é a mais fácil de fazer.', '["Comece na posição do cão.","Leve o joelho direito em direção ao nariz e coloque o pé direito entre as mãos.","Apoie o calcanhar esquerdo no chão com o pé levemente projetado para fora.","Equilibre os braços no ar. Com as palmas das mãos voltadas para baixo, o braço esquerdo deve ir em direção à borda de trás do tapete e o direito em direção à parte da frente.  Mantenha o joelho direito flexionado em um ângulo de 90 graus, alinhado com o tornozelo direito.","Abaixe os ombros, distanciando-os das orelhas, encaixe o cóccix e acomode as costelas para dentro.Fixe o olhar para além do dedo médio da mão da frente. Respire profundamente pelo menos três vezes nessa posição e então repita com o outro lado."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Back Massage', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_007-C5.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_007-C5.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com uma bola de tênis colocada sob o ombro esquerdo.","Mova seu corpo para cima e para baixo lentamente para massagear as costas com a bola. Adicione peso corporal para aumentar a pressão da massagem."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Diamond Leg Lift', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_022-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_022-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os pés apoiados e com os calcanhares juntos. Os joelhos devem estar dobrados e se estender para fora para formar um formato de diamante com as pernas.","Aperte o abdome enquanto levanta as pernas do chão, mantendo o formato de diamante. Em seguida, abaixe-o lentamente até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal diamante', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_021-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_021-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os pés apoiados e com os calcanhares juntos. Os joelhos devem estar dobrados e se estender para fora para formar um formato de diamante com as pernas.","Aperte o abdome enquanto levanta a cabeça e os ombros do chão para fazer uma abdominal."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Footwork', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_026-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_026-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os pés apoiados e com os calcanhares juntos. Flexione os pés em forma de V.","Inspire e estique as pernas.","Expire e retorne as pernas à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Foot Rolling', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_025-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_025-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Fique em pé com uma bola de tênis embaixo de um pé.","Role a bola para frente e para trás e de um lado para o outro repetidamente.","Repita o processo com o outro pé."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Footwork (on disc)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_027-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_027-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os pés apoiados e com os calcanhares juntos. Coloque um disco de equilíbrio sob a parte inferior das costas e flexione os pés em forma de V.","Inspire e estique as pernas.","Expire e retorne as pernas à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Frog (with Band)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_030-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_030-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os joelhos pressionados em direção ao corpo e com os pés no ar. Coloque uma faixa elástica em torno de ambos os pés enquanto a segura com as mãos.","Expire enquanto estende as pernas para cima e para longe do corpo.","Inspire ao trazer as pernas de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Hug a Tree (with ball, band and weight)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_037-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_037-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se ereto em uma Bola Suíça com os pés apoiados no chão. Enrole uma faixa de elástico em torno de suas costelas e enrole as extremidades em torno de halteres de 1 a 3 kg.","Abra os braços e aperte os ombros.","Junte os nós dos dedos ao abrir os ombros."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Half Roll Up', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_031-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_031-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição sentada com as pernas esticadas e os braços estendidos para a frente.","Expire pela boca enquanto rola a parte superior do corpo lentamente para a frente sobre as pernas. Imagine que há uma bola entre seu estômago e suas pernas enquanto você rola.","Inspire pelo nariz enquanto rola de volta para a posição sentada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Knee Folds (on disc)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_040-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_040-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis em posição neutra, os joelhos dobrados e os pés apoiados. Coloque um disco de equilíbrio abaixo da parte inferior das costas.","Inspire e aperte o abdome para levantar a perna direita em direção ao corpo.","Expire enquanto abaixa a perna para a posição inicial.","Repita o exercício com a perna esquerda e continue trocando as pernas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Knee Circles', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_038-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_038-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas e puxe os joelhos para o corpo.","Com os joelhos juntos, gire as pernas em pequenos círculos para fora e depois em direção ao corpo.","Inspire enquanto seus joelhos se aproximam do corpo e expire enquanto eles se afastam."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Lateral Flexion', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_041-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_041-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os pés apoiados no chão. Estenda os braços para os lados.","Levante a cabeça e os braços ligeiramente do chão e alcance o tornozelo direito com a mão direita, alongando a coluna ao chegar.","Retorne à posição inicial e repita o movimento do lado esquerdo, inspirando e expirando lentamente pelo nariz enquanto continua."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamento afundo', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_050-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_050-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Fique em pé com os joelhos levemente dobrados e os braços acima da cabeça.","Expire enquanto dobra os joelhos e abaixa o corpo em uma posição de agachamento.","Inspire ao retornar à posição ereta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Lunges (with knee lift)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_051-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_051-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Fique em pé com os pés afastados na largura dos ombros e com as mãos na cintura.","Dê um grande passo para trás com o pé direito, entre 30 e 60 cm de distância do pé esquerdo. Assim que o pé tocar o chão, abaixe seus quadris no chão até que o joelho esquerdo forme um ângulo de 90 graus.","Pressione o pé direito e retorne à posição ereta. Levante o joelho direito até um ângulo de 90 graus. Em seguida, retorne à posição inicial. Repita com a outra perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Lower Lift (on disc)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_048-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_048-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis estável e levemente inclinada. Coloque um disco de equilíbrio sob a parte inferior das costas e as mãos atrás do pescoço.","Expire enquanto levanta a cabeça e os ombros do tapete e estica as pernas até o teto.","Inspire enquanto abaixa as pernas.","Expire e levante as pernas em direção ao teto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Neutral Pelvic Position', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_054-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_054-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os joelhos dobrados e os pés apoiados no chão.","Inspire, enchendo o peito de ar e expire enquanto contrai o abdome e pressiona a parte inferior da coluna no chão em uma dobra pélvica.","Inspire ao retornar à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pelvic Clocks (on disc)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_056-B2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_056-B2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Inverta a direção durante cada repetição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Pilates Plie Squats (Parallel, Turned Out, Flat, and Heels) (with chair)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_058-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_058-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Coloque uma cadeira atrás de você.","Dobre os joelhos e abaixe os quadris em direção à cadeira.","Pressione os pés e aperte os glúteos para retornar à posição ereta.","Levante os calcanhares.","Dobre os joelhos com os calcanhares levantados.","Estique as pernas.","Com os pés apoiados, gire os calcanhares externamente.","Flexione os joelhos.","Estique as pernas.","Gire as pernas para fora e levante os calcanhares.","Flexione os joelhos.","Estique as pernas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha: movimentos transversais dos joelhos', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_064-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_064-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição de prancha.","Dobre o joelho direito enquanto puxa o pé direito para a frente. Em seguida, gire o joelho em direção ao cotovelo esquerdo.","Retorne à posição de prancha.","Dobre o joelho esquerdo enquanto puxa o pé esquerdo para a frente. Em seguida, gire o joelho em direção ao cotovelo direito.","Retorne à posição de prancha."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Plank Up/Downs', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_062-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_062-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição de prancha.","Abaixe os calcanhares em direção ao chão (sem tocar) enquanto levanta os quadris em direção ao teto.","Volte lentamente para a posição de prancha.","Repita o exercício."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha: flexão de joelho', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_065-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_065-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Comece na posição de prancha.","Dobre o joelho direito enquanto puxa o pé direito para frente em direção ao peito.","Retorne à posição de prancha.","Dobre o joelho esquerdo enquanto puxa o pé esquerdo para frente em direção ao peito.","Retorne à posição de prancha."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Ribcage Breathing', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_069-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_069-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas.","Segure as laterais do corpo com as mãos enquanto lentamente inspira pelo nariz e expira pela boca."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Roll Up (with weight and band)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_073-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_073-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Enrole uma faixa elástica nas costas e enrole as extremidades em torno de halteres de 1 a 3 kg. Deite-se de costas com as pernas retas enquanto segura os halteres e a faixa. Pressione a parte interna das coxas.","Eleve os braços em direção ao teto e para trás nas laterais das orelhas sem mover as costelas.","Acene com a cabeça e levante os ombros para fora do tatame ao levar os braços em direção aos pés.","Encaixe o cóccix embaixo, desenrolando-se de volta ao tatame, uma vértebra de cada vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Scapular Stabilization', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_080-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_080-B1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os braços estendidos para cima.","Inspire enquanto levanta os ombros do chão e estica os braços acima da cabeça. Mantenha a posição.","Expire ao retornar os braços e ombros à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Scissors (on disc)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_082-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_082-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis estável e ligeiramente inclinada e as pernas dobradas a 90 graus. Coloque um disco de equilíbrio abaixo da parte inferior das costas.","Levante a cabeça e os ombros do tapete enquanto estica as pernas em direção ao teto.","Segure uma perna enquanto abaixa a outra.","Segure a outra coxa enquanto a outra perna desce em direção ao chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Shaving the Head (with ball, band and weight)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_087-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_087-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se ereto em uma Bola Suíça com os pés apoiados no chão. Enrole uma faixa de elástico em torno de suas costelas e enrole as extremidades em torno de halteres de 1 a 3 kg. Segurando os pesos, estique a faixa elástica e levante os braços até a altura dos ombros, com as palmas das mãos para baixo e os pesos se tocando.","Incline a coluna ligeiramente para a frente enquanto levanta os braços 5 a 7 cm para cima.","Dobre os cotovelos para o lado, puxando os pesos de volta para a cabeça.","Pressione os braços para cima, acima da cabeça."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Squats (with ball)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_096-A3.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_096-A3.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Fique em pé com uma Bola Suíça atrás das costas e pressionada contra uma parede. Seus pés devem estar ligeiramente à sua frente e na largura dos ombros.","Agache-se, mantendo os calcanhares e os joelhos para fora, deixando a Bola Suíça rolar pelas costas. Estenda os braços para manter o equilíbrio. Levante-se e volte à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Straight-leg Crunch with Leg Lift (with ball)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_101-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_101-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com as mãos atrás da cabeça, as pernas estendidas e os pés flexionados.","Inspire enquanto levanta a cabeça e os ombros do tapete e levante a perna direita do chão.","Expire ao retornar à posição inicial.","Repita o exercício com a perna esquerda."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com perna cruzada', '', '', NULL, NULL, 'yoga,pilates', 'MOVE', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com perna elevada', '', '', NULL, NULL, 'yoga,pilates', 'MOVE', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Straight-leg Crunch with legs crossed (with ball)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_100-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_100-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com as mãos atrás da cabeça, as pernas estendidas e cruzadas e os pés flexionados.","Inspire pelo nariz enquanto levanta a cabeça e os ombros do tapete.","Expire ao retornar à posição inicial.","Repita o exercício."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tailbone Curl', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_104-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_104-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com os joelhos puxados em direção ao peito e os pés cruzados.","Com a coluna fixa, inspire e levante os quadris do chão, aproximando os joelhos do peito.","Expire e retorne à posição inicial.","Continue a levantar e abaixar."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com perna estendida na diagonal', '', '', NULL, NULL, 'yoga,pilates', 'MOVE', '', '', NULL, NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Abdominal com perna estendida com bola', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_099-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_099-A2.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com as mãos atrás da cabeça, as pernas estendidas e cruzadas e os pés flexionados.","Expire enquanto levanta a cabeça e os ombros do tapete e gire o tronco para que o cotovelo direito aponte para o joelho esquerdo.","Inspire ao retornar à posição inicial.","Repita o exercício com o cotovelo esquerdo e continue alternando."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Fecho na garganta', '', '', 'https://connect.garmin.com/images/exercises/images/THROAT_LOCK/heroImage_BBtOllX.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_081-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', 'Conhecido como o destruidor da velhice e traduzido como "o fecho que controla a rede," este é um dos três principais fechos energéticos do corpo. Responsável por prevenir que o prana vaze do tronco através da garganta, também é frequentemente chamado de Fecho da garganta, e é utilizado em muitas posturas para proteger o pescoço.', '["Comece sentado com as pernas cruzadas e feche os olhos.","Levante o esterno e deixe o queixo cair levemente, levantando pela parte superior traseira do seu crânio, como se alguém tivesse uma corda na parte de trás do seu pescoço e estivesse lhe levantando. Alongue a parte de trás do pescoço e mantenha os ombros para baixo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('V Leg Crunches', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_111-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_111-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Deite-se de costas com as pernas para cima, os pés flexionados e as mãos estendidas entre as pernas.","Inspire pelo nariz enquanto levanta a cabeça e os ombros do tapete.","Expire pela boca ao retornar à posição inicial.","Continue a levantar e abaixar."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('V Sit', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_112-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_112-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', '', '["Sente-se com as pernas estendidas para a frente e levante as pernas até um ângulo de 45 graus do chão.","Estenda os braços para frente ou para cima em direção às canelas.","Mantenha essa posição em forma de V por alguns segundos e depois retorne à posição sentada."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Oração Mudra', '', '', 'https://connect.garmin.com/images/exercises/images/PRAYER_MUDRA/heroImage_BBtOcUM.jpg', 'https://connectvideo.garmin.com/msn-workout/Yoga/Y_052-A1.mp4', 'yoga,pilates', 'MOVE', 'Iniciante', '', 'Também conhecido como o "Sinal de Saudação", este mudra é uma das posições de mãos mais reconhecidas no ioga. É tanto uma união quanto um gesto de reverência.', '["Comece sentado com as pernas cruzadas.","Junte as palmas das mãos no centro do tórax e conecte os polegares ao batimento cardíaco. Pressione as palmas das mãos uma na outra uniformemente e abaixe um pouco a cabeça. Respire profundamente pelo menos cinco vezes nessa posição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Bicep Curl with Leg Extension (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_010-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_010-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Mantenha a postura com as pernas retas. Segure um haltere de 1 a 3 kg. Mantenha os cotovelos perto da cintura e as palmas das mãos voltadas para cima.","Curve-se sobre o cóccix.","Levante a perna direita a 5 cm do tapete.","Dobre os cotovelos e a perna direita.","Estique os braços e a perna, passando-a sobre o tapete. Repita 4 vezes.","Abaixe a perna direita.","Levante a perna esquerda a 5 cm do tapete.","Dobre a perna esquerda enquanto flexiona os dois braços. Repita 4 vezes.","Abaixe a perna esquerda.","Encolha-se e mantenha a postura."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Bicicleta', '', '', 'https://connect.garmin.com/images/exercises/images/BICYCLE/heroImage_BBtOlhB.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_011-A2.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'As séries de pernas laterais o desafiam a manter uma pélvis neutra e equilibrada enquanto estiver de lado e lutando contra a gravidade.', '["Deite-se de lado com os ossos dos quadris alinhados um sobre o outro e suas pernas empilhadas uma sobre a outra. Incline suas pernas um pouco para a frente de forma que estejam ligeiramente na frente do tronco.","Levante a perna de cima até a altura do quadril e estique os dedos dos pés.","Dobre o joelho superior em 90 graus.","Em seguida, estique a perna em frente e flexione o pé.","Puxe a perna para trás do quadril. Repita 4 vezes e, em seguida, inverta a direção."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rosca do bíceps com extensão de perna', '', 'Halteres', 'https://connect.garmin.com/images/exercises/images/BICEP_CURL_WITH_LEG_EXTENSION/heroImage_BBtOnp4.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_009-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'This is a coordination exercise.', '["Mantenha a postura com as pernas retas. Segure um haltere de 1 a 3 kg. Mantenha os cotovelos perto da cintura, com as palmas das mãos voltadas para cima.","Curve-se sobre o cóccix.","Levante a perna direita a 5 cm do tapete.","Dobre os cotovelos e a perna direita.","Estique os braços e a perna, passando-a sobre o tapete. Repita 4 vezes.","Abaixe a perna direita.","Levante a perna esquerda a 5 cm do tapete.","Dobre a perna esquerda enquanto flexiona os dois braços. Repita 4 vezes.","Abaixe a perna esquerda.","Encolha-se e mantenha a postura."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Saca-rolha', '', '', 'https://connect.garmin.com/images/exercises/images/CORKSCREW/heroImage_BBtOfjq.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_018-A1.mp4', 'yoga,pilates', 'CORE', 'Intermediário', '', 'This exercise works your abdominals and stretches your spine.', '["Deite-se de costas com as pernas dobradas a 90 graus e os braços ao lado do corpo.","Estique as pernas até o teto e levante o cóccix do tapete.","Use a contração abdominal para inclinar a pélvis e as pernas para o lado esquerdo. Siga a junta da pélvis até o cóccix.","Use o abdome para inclinar a pélvis e as pernas para o lado direito, seguindo a junta da pélvis de volta à posição inicial.","Inverta a direção durante cada repetição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Alongamento de duas pernas', '', '', 'https://connect.garmin.com/images/exercises/images/DOUBLE_LEG_STRETCH/heroImage_BBtOfji.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_023-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'This exercise improves stability by moving the limbs while engaging the pelvis and the torso.', '["Deite-se de costas com as pernas dobradas a 90 graus e com a pélvis em uma posição neutra.","Expire enquanto levanta a cabeça e os ombros do chão e estende os braços em direção às panturrilhas.","Inspire e estique os braços em direção às orelhas enquanto as pernas se estendem para a frente.","Expire enquanto circula os braços ao redor das panturrilhas e puxa as pernas até o peito."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Criss-Cross', '', '', 'https://connect.garmin.com/images/exercises/images/CRISS_CROSS/heroImage_BBtOiZH.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_019-B1.mp4', 'yoga,pilates', 'CORE', 'Intermediário', '', 'Esee exercício ajuda a manter a pelve neutra e estável enquanto gira a caixa torácica.', '["Deite-se de costas com as pernas esticadas em um ângulo de 90 graus. Coloque as mãos atrás do pescoço com os cotovelos abertos.","Curve e tire a cabeça e os ombros do colchonete.","Expire ao cruzar o cotovelo esquerdo até o joelho direito.","Inspire e gire o tronco para o centro.","Expire e cruze o cotovelo direito até o joelho esquerdo."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Lower Lift (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_049-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_049-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis estável e levemente inclinada. Segure halteres de 1 a 3 kg em suas mãos com os braços para os lados.","Levante a cabeça e os ombros do tapete enquanto levanta os braços e estica as pernas até o teto.","Inspire enquanto abaixa as pernas.","Expire e levante as pernas em direção ao teto."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Relógios pélvicos', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_055-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_055-B1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'Este é um exercício fundamental do Pilates. O movimento envolve os músculos do assoalho pélvico na pelve. Ele também fortalece o abdome inferior enquanto libera a tensão lombar.', '["Deite-se de costas com os joelhos dobrados e os pés apoiados. Coloque um disco de equilíbrio sob a pélvis.","Dobre a pélvis para baixo, trazendo o osso púbico em direção ao umbigo.","Contraia o abdome e solte lentamente a pélvis para o lado esquerdo e mova-se em direção ao cóccix.","Use a contração abdominal para controlar seu movimento enquanto se levanta novamente.","Inverta a direção durante cada repetição."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento para trás', '', '', 'https://connect.garmin.com/images/exercises/images/ROLL_OVER/heroImage_BBtOiZz.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_071-B1.mp4', 'yoga,pilates', 'CORE', 'Avançado', '', 'Este exercício ajuda a alongar a coluna e os os músculos posteriores da coxa e, ao mesmo tempo, fortalece os músculos abdominais.', '["Deite-se de costas com os braços ao lado do corpo, com as palmas para baixo, e eleve as pernas em direção ao teto .","Contraia o abdômen para trazer as pernas sobre a cabeça até um ângulo de 45 graus.","Afaste as pernas na largura dos quadris.","Abaixe os quadris, movendo a coluna, uma vértebra por vez, para voltar À posição inicial.","Aperte as pernas juntas. Repita três vezes.","Depois, mude de direção. Deite-se com as pernas esticadas na largura do quadril, e os pés flexionados.","Contraia o abdômen para levantar as pernas.","Contraia as coxas uma contra a outra enquanto desenrola de volta ao chão através da coluna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rolamento para cima', '', '', 'https://connect.garmin.com/images/exercises/images/ROLL_UP/heroImage_BBtOfjb.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_072-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'Este exercício atinge os músculos abdominais e a coluna. Quando realizado corretamente, o exercício alonga a coluna enquanto fortalece os músculos abdominais. Joseph Pilates afirmou que o movimento de rolamento pode também melhorar os pulmões.', '["Deite sobre as costas com as pernas retas. Aperte as coxas juntas.","Eleve os braços em direção ao teto e para trás nas laterais das orelhas sem mover as costelas.","Acene com a cabeça e levante os ombros para fora do tatame ao levar os braços em direção aos pés.","Encaixe o cóccix embaixo, desenrolando-se de volta ao tatame, uma vértebra de cada vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remando 1', '', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ROWING_1/heroImage_BBtOlhk.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_075-A1.mp4', 'yoga,pilates', 'CORE', 'Intermediário', '', 'Esse exercício trabalha o corpo todo enquanto treina a estabilização e coordenação dos ombros.', '["Sente-se com os pés e a coluna reta, dedos expostos e segure halteres de 0,5 a 3 kg.  Toque os dedos juntos na altura do tórax e abra os cotovelos para os lados.","Curve-se sobre o cóccix.","Abra os braços para formar um \"V\".","Gire as palmas das mãos para a parede. Em seguida, pressione os braços para trás ao enrolar a coluna para frente.","Circule os braços para cima e vá em direção aos pés.","Empilhe a coluna e levante até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rowing 1 (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_076-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_076-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Segurando halteres de 1 a 3 kg, sente-se com as pernas e a coluna retas e os pés flexionados.","Curve-se sobre o cóccix.","Abra os braços em forma de V.","Gire as palmas das mãos para a parede. Em seguida, pressione os braços para trás ao enrolar a coluna para frente.","Circule os braços para cima e vá em direção aos pés.","Empilhe a coluna e levante até a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Remo 2', '', 'Halteres', 'https://connect.garmin.com/images/exercises/images/ROWING_2/heroImage_BBtOcPF.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_077-A1.mp4', 'yoga,pilates', 'CORE', 'Intermediário', '', 'Esse exercício trabalha o corpo todo enquanto treina a estabilização e coordenação dos ombros.', '["Sente-se com a coluna ereta e as pernas retas, com os pés flexionados. Segure halteres de 1 a 3 kg. Levante os braços à sua frente na altura dos ombros, com as palmas das mãos voltadas para cima.","Dobre os cotovelos a 90 graus.","Mantendo as costas retas, incline-se para trás em um ponto onde você possa manter a posição confortavelmente.","Estenda os braços para cima, com as palmas das mãos voltadas para trás.","Estenda os braços em direção aos pés enquanto se inclina para a frente.","Vire as palmas das mãos para o chão e mova os braços em direção à parede atrás de você.","Faça um círculo com os braços para cima em direção aos dedos dos pés.","Estique sua coluna e retorne à posição ereta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Rowing 2 (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_078-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_078-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Segurando halteres de 1 a 3 kg, sente-se com as pernas e a coluna retas e os pés flexionados.","Dobre os cotovelos a 90 graus.","Mantendo as costas retas, incline-se para trás em um ponto onde você possa manter a posição confortavelmente.","Estenda os braços para cima, com as palmas das mãos voltadas para trás.","Estenda os braços em direção aos pés enquanto se inclina para a frente.","Vire as palmas das mãos para o chão e mova os braços em direção à parede atrás de você.","Faça um círculo com os braços para cima em direção aos dedos dos pés.","Estique sua coluna e retorne à posição ereta."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Tesoura', '', '', 'https://connect.garmin.com/images/exercises/images/SCISSORS/heroImage_BBtOhry.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_081-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'This exercise works to challenge the ability of the pelvis to stabilize. It also stretches the hamstrings and increases mobility in the hip joints.', '["Deite-se de costas com a pélvis estável e ligeiramente inclinada e as pernas dobradas a 90 graus.","Levante a cabeça e os ombros do tapete enquanto estica as pernas em direção ao teto.","Segure uma perna enquanto abaixa a outra.","Segure a outra coxa enquanto a outra perna desce em direção ao chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Single-leg Stretch (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_091-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_091-B1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis estável e ligeiramente inclinada e as pernas dobradas a 90 graus. Segure halteres de 1 a 3 kg em cada mão.","Levante a cabeça e os ombros do tapete e levante as mãos ligeiramente do chão.","Expire pela boca enquanto leva o joelho direito em direção ao peito e estica o joelho esquerdo. Inspire pelo nariz.","Expire e troque as pernas, trazendo a perna esquerda para dentro e estendendo a perna direita em linha reta.","Repita o exercício, inspirando e expirando a cada mudança na direção da perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Scissors (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_083-A2.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_083-A2.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', '["Deite-se de costas com a pélvis estável e ligeiramente inclinada e as pernas dobradas a 90 graus. Segure halteres de 1 a 3 kg em cada mão.","Levante a cabeça e os ombros do tapete enquanto estica as pernas em direção ao teto e levanta ligeiramente os braços.","Expire pela boca enquanto abaixa a perna direita, mantendo-a ligeiramente afastada do chão.","Levante a perna direita de novo enquanto a perna esquerda abaixa em direção ao chão e, em seguida, expire novamente.","Repita o exercício, inspirando e expirando a cada mudança na direção da perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Cisne', '', '', 'https://connect.garmin.com/images/exercises/images/SWAN/heroImage_BBtOcPW.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_102-A1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', 'Este é um exercício de extensão. Joseph Pilates acreditava que quando o corpo se curva para a frente na flexão na maior parte do dia, ele livra-se do alinhamento natural do corpo. O movimento do cisne ajuda a trazer o corpo de volta ao equilíbrio.', '["Deite-se de bruços para o tatame e com os braços curvados 90 graus na altura do ombro. Pressione as mãos no tatame e pressione as bolas do pé contra o chão.","Deslize a omoplata para baixo da caixa torácica. Depois estique os braços e pressione o tronco para a frente, erguendo do chão enquanto os cotovelos giram para dentro.","Flexione os cotovelos, mantendo as escápulas expandidas para abaixar-se para a posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Teaser', '', '', 'https://connect.garmin.com/images/exercises/images/TEASER/heroImage_BBtOli4.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_105-B2.mp4', 'yoga,pilates', 'CORE', 'Avançado', '', 'Este é um exercício fundamental na prática do Pilates. Ele foi projetado para melhorar o equilíbrio, visando o abdome.', '["Deite-se de costas com as coxas se tocando, os joelhos dobrados e os pés apoiados. Descanse os braços retos ao lado do corpo, com as palmas das mãos voltadas para cima.","Levante uma perna em direção ao teto.","Levante os braços em direção ao teto.","Levante a cabeça e os ombros do tapete, levantando o tronco em direção à perna esticada.","Role para baixo, uma vértebra de cada vez.","Troque de perna.","Deite-se de costas com as duas pernas levantadas a 90 graus. Levante os braços em direção ao teto.","Estenda os braços em direção aos pés enquanto rola para descansar sobre os ossos dos glúteos.","Abaixe e levante as pernas.","Role a coluna, uma vértebra de cada vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('O cem', '', '', 'https://connect.garmin.com/images/exercises/images/THE_HUNDRED/heroImage_BBtOpZs.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_106-B1.mp4', 'yoga,pilates', 'CORE', 'Intermediário', '', 'This is a fundamental move of Pilates practice. It warms up the body, promotes circulation, and strengthens the core. The hundred helps build a foundation of strength to perform the more advanced abdominal exercises.', '["Deite-se de costas com a pelve em uma posição neutra, joelhos flexionados e braços descansando nas laterais do corpo.","Levante uma perna de cada vez com os joelhos flexionados a 90 graus, em uma posição de \"tabletop\".","Levante a cabeça e os ombros do tatame.","Estique as pernas, mantendo os calcanhares juntos.","Bata os braços, inspire e contando até cinco, depois expire contando até cinco. Repita dez vezes."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Criss Cross (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_020-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_020-B1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('The Hundred (with weight)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_107-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_107-B1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Double-leg Stretch (with weights)', '', '', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_024-B1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_024-B1.mp4', 'yoga,pilates', 'CORE', 'Iniciante', '', '', NULL);
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Raspando a cabeça', '', 'Halteres', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_086-A1.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_086-A1.mp4', 'yoga,pilates', 'LATERAL_RAISE', 'Intermediário', '', 'Este exercício ajuda a melhorar a estabilidade ao atingir áreas específicas do corpo, uma de cada vez.', '["Sente-se com as pernas cruzadas em posição de lótus. Enrole uma faixa de elástico em torno de suas costelas e enrole as extremidades em torno de halteres de 1 a 3 kg. Segurando os pesos, estique a faixa elástica e levante os braços até a altura dos ombros, com as palmas das mãos para baixo e os pesos se tocando.","Incline a coluna ligeiramente para a frente enquanto levanta os braços 5 a 7 cm para cima.","Dobre os cotovelos para o lado, puxando os pesos de volta para a cabeça.","Pressione os braços para cima, acima da cabeça."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Ponte com elevação inferior do glúteo', '', '', 'https://connect.garmin.com/images/exercises/images/BRIDGE_WITH_GLUTE_LOWER_LIFT/heroImage_BBtOnpF.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_013-A1.mp4', 'yoga,pilates', 'PLANK', 'Iniciante', '', 'Isolar os glúteos enquanto libera os flexores dos quadris pode ajudar a aliviar dores nas costas bem como melhorar a funcionalidade das pernas.', '["Deite-se de costas com seus joelhos flexionados, pés apoiados no chão e alinhados com os quadris.","Levante-se para uma posição de ponte.","Abaixe a pélvis a 5 cm do chão.","Contraia os glúteos e eleve a pélvis de volta à posição de ponte. Execute 10 repetições.","Abaixe a coluna no chão, uma vértebra de cada vez."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Ponte: ponte de uma perna', '', '', 'https://connect.garmin.com/images/exercises/images/BRIDGE_ONE_LEG_BRIDGE/heroImage_BBtO59J.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_014-A1.mp4', 'yoga,pilates', 'PLANK', 'Iniciante', '', 'This exercise stretches and strengthens the muscles around the 26 vertebrae of the spine.', '["Deite-se de costas com seus joelhos flexionados, pés apoiados no chão e alinhados com os quadris.","Dobre o cóccix e role cada vértebra do chão, uma de cada vez.","Estenda a perna direita em direção ao teto.","Abaixe e levante a perna direita 4 vezes.","Retorne à posição inicial. Em seguida, troque as pernas.","Abaixe uma vértebra de cada vez até o chão."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha (com variações dos braços)', '', '', 'https://connect.garmin.com/images/exercises/images/PLANK_WITH_ARM_VARIATIONS/heroImage_BBtO59t.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_061-B1.mp4', 'yoga,pilates', 'PLANK', 'Intermediário', '', 'Esse exercício enfatiza o fortalecimento do corpo inteiro.', '["Apoie-se sobre suas mãos e joelhos. Alinhe os joelhos embaixo dos quadris e posicione as mãos embaixo dos ombros.","Contraia o abdômen conforme move sua perna direita para trás e aloja os dedos dos pés sob o colchonete.","Traga sua perna esquerda para trás para junto de sua perna direita. Contraia os músculos posteriores e a parte interna das coxas.","Retorne à posição inicial. Em seguida, alterne os lados."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Prancha invertida (com arranque das pernas)', '', '', 'https://connect.garmin.com/images/exercises/images/REVERSE_PLANK_WITH_LEG_PULL/heroImage_BBtOq0g.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_068-B1.mp4', 'yoga,pilates', 'PLANK', 'Intermediário', '', 'Esse exercício fortalece a parte posterior do corpo enquanto alonga a parte frontal.', '["Sente-se ereto com ambas as pernas estendidas. Posicione suas mãos firmemente sobre o colchonete atrás, com os dedos voltados uns contra os outros.","Pressione as mãos e pés no chão para levantar o tronco, formando uma linha reta desde os ombros até a ponta dos pés.","Eleve sua perna direita em direção ao teto.","Retorne a perna direita ao chão.","Eleve sua perna esquerda em direção ao teto.","Traga sua perna esquerda para o chão.","Abaixe o tronco de volta à posição inicial."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Agachamentos “plié” de Pilates (paralelo, voltado para fora, nivelado e com os calcanhares)', '', '', 'https://connect.garmin.com/images/exercises/images/PILATES_PLIE_SQUATS_PARALLEL_TURNED_OUT_FLAT_AND_HEELS/heroImage_BBtOj0x.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_057-A3.mp4', 'yoga,pilates', 'SQUAT', 'Intermediário', '', 'As variações de agachamento do Pilates imitam o trabalho dos pés, que é feito em equipamentos de Pilates. Este movimento mantém o tronco controlado e estável enquanto muda constantemente a posição das pernas e pés.', '["Fique em pé com os pés afastados na largura do quadril. Estenda os braços para a frente e segure-os na altura dos ombros.","Dobre os joelhos e abaixe os quadris em direção ao chão.","Pressione os pés e aperte os glúteos para retornar à posição ereta.","Levante os calcanhares.","Dobre os joelhos com os calcanhares levantados.","Estique as pernas.","Com os pés apoiados, gire os calcanhares externamente.","Flexione os joelhos.","Estique as pernas.","Gire as pernas para fora e levante os calcanhares.","Flexione os joelhos.","Estique as pernas."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('"Relevê", pernas retas e joelhos flexionados (com variação de uma perna)', '', '', 'https://connect.garmin.com/images/exercises/images/RELEVE_STRAIGHT_LEG_AND_KNEE_BENT_WITH_ONE_LEG_VARIATION/heroImage_BBtOhsi.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_067-A3.mp4', 'yoga,pilates', 'SQUAT', 'Iniciante', '', 'Este é um exercício de equilíbrio que começa pelos pés, pois eles podem passar despercebidos em muitos treinos. Os pés são a base da estabilidade na prática do Pilates.', '["Fique de pé com os pés juntos. Coloque os dedos parte de trás de uma cadeira para se equilibrar, se necessário.","Levante os dois calcanhares.","Abaixe os dois calcanhares. Repita 12 vezes.","Repita, levantando o calcanhar enquanto se apoia em apenas uma perna.","Repita, desta vez levantando os calcanhares com os pés juntos e os joelhos dobrados.","Repita, levantando o calcanhar enquanto se equilibra em uma perna dobrada. Repita a sequência na outra perna."]');
INSERT INTO exercises (name, muscle_group, equipment, garmin_image_url, garmin_video_url, discipline, category, difficulty, secondary_muscles, description, steps) VALUES ('Flexão de braços de Pilates', '', '', 'https://connect.garmin.com/images/exercises/images/PILATES_PUSHUP/heroImage_BBtOfjY.jpg', 'https://connectvideo.garmin.com/msn-workout/Pilates/P_059-A4.mp4', 'yoga,pilates', 'PUSH_UP', 'Intermediário', '', 'A flexão de Pilates desenvolve força e resistência.', '["Fique em pé com as pernas juntas.","Dobre o queixo e abaixe a coluna até que as mãos alcancem o chão.","Caminhe com as mãos até a posição de prancha.","Pressione as mãos e dobre os cotovelos para os lados para abaixar o peito.","Pressione as mãos e estique os braços, levantando-se de volta até a posição de prancha.","Movimente as mãos de volta aos dedos dos pés.","Retorne à posição ereta, curvando uma vértebra de cada vez."]');
